--
-- Name: fun_activar_desactivar_descuento(numeric, boolean, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_activar_desactivar_descuento(p_id_descuento numeric, p_activar boolean, p_usr_update numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_existe BOOLEAN := FALSE;
    v_estado_actual BOOLEAN;
    v_nombre_descuento VARCHAR;
BEGIN
    -- PASO 1: Verificar que el descuento existe y obtener su estado actual
    SELECT 
        EXISTS(SELECT 1 FROM tab_descuentos WHERE id_descuento = p_id_descuento),
        ind_activo,
        nom_descuento
    INTO v_existe, v_estado_actual, v_nombre_descuento
    FROM tab_descuentos 
    WHERE id_descuento = p_id_descuento;
    
    -- VALIDACIÓN 1: Existencia del descuento
    IF NOT v_existe THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El descuento especificado no existe'
        );
    END IF;

    -- VALIDACIÓN 2: Verificar si ya tiene el estado deseado
    IF v_estado_actual = p_activar THEN
        RETURN json_build_object(
            'success', true,
            'message', CASE 
                WHEN p_activar THEN 'El descuento ya está activo'
                ELSE 'El descuento ya está inactivo'
            END,
            'descuento', json_build_object(
                'id_descuento', p_id_descuento,
                'nombre', v_nombre_descuento,
                'estado', CASE WHEN p_activar THEN 'Activo' ELSE 'Inactivo' END
            )
        );
    END IF;

    -- ACTUALIZACIÓN: Cambiar estado del descuento con auditoría
    UPDATE tab_descuentos 
    SET 
        ind_activo = p_activar,                                 -- Nuevo estado
        usr_update = p_usr_update,                              -- Usuario que modifica
        fec_update = NOW()                                      -- Timestamp de modificación
    WHERE id_descuento = p_id_descuento;

    -- RESPUESTA: Confirmar éxito con información detallada
    RETURN json_build_object(
        'success', true,
        'message', CASE 
            WHEN p_activar THEN 'Descuento activado exitosamente'
            ELSE 'Descuento desactivado exitosamente'
        END,
        'descuento', json_build_object(
            'id_descuento', p_id_descuento,
            'nombre', v_nombre_descuento,
            'estado_anterior', CASE WHEN v_estado_actual THEN 'Activo' ELSE 'Inactivo' END,
            'estado_nuevo', CASE WHEN p_activar THEN 'Activo' ELSE 'Inactivo' END
        )
    );

-- MANEJO DE ERRORES: Capturar excepciones SQL
EXCEPTION 
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Error inesperado: ' || SQLERRM
        );
END;
$$;


--
-- Name: fun_actualizar_config_puntos_empresa(integer, numeric, character varying, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_actualizar_config_puntos_empresa(p_id_config_puntos integer, p_nuevo_pesos_por_punto numeric, p_descripcion character varying, p_usr_operacion numeric) RETURNS json
    LANGUAGE plpgsql
    AS $_$
BEGIN
    -- VALIDACIÓN 1: ID de configuración es obligatorio
    IF p_id_config_puntos IS NULL OR p_id_config_puntos <= 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El ID de configuración es obligatorio y debe ser mayor a 0'
        );
    END IF;
    
    -- VALIDACIÓN 2: Valor de pesos por punto debe ser positivo
    IF p_nuevo_pesos_por_punto IS NULL OR p_nuevo_pesos_por_punto <= 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El valor de pesos por punto es obligatorio y debe ser mayor a 0'
        );
    END IF;
    
    -- VALIDACIÓN 3: Usuario operación para auditoría
    IF p_usr_operacion IS NULL OR p_usr_operacion <= 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El usuario que realiza la operación es obligatorio para auditoría'
        );
    END IF;
    
    -- VALIDACIÓN 4: Verificar que existe la configuración específica y está activa
    IF NOT EXISTS (
        SELECT 1 FROM tab_config_puntos_empresa 
        WHERE id_config_puntos = p_id_config_puntos AND ind_activo = TRUE
    ) THEN
        RETURN json_build_object(
            'success', false,
            'message', 'No existe una configuración activa con el ID especificado: ' || p_id_config_puntos,
            'sugerencia', 'Verifique el ID o ejecute fun_crear_config_puntos_empresa() para crear una nueva configuración'
        );
    END IF;
    
    -- ACTUALIZACIÓN: Modificar configuración específica del sistema de puntos
    UPDATE tab_config_puntos_empresa 
    SET 
        pesos_por_punto = p_nuevo_pesos_por_punto,                  -- Nuevo valor pesos por punto
        descripcion = COALESCE(                                     -- Nueva descripción
            p_descripcion, 
            'Actualizado: 1 punto por cada $' || p_nuevo_pesos_por_punto::TEXT || ' pesos'
        ),
        usr_update = p_usr_operacion,                               -- Usuario que actualiza
        fec_update = NOW()                                          -- Timestamp de actualización
    WHERE id_config_puntos = p_id_config_puntos                     -- Configuración específica por ID
      AND ind_activo = TRUE;                                        -- Y que esté activa (seguridad extra)
    
    -- VERIFICACIÓN: Confirmar que se actualizó al menos una fila
    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'No se pudo actualizar la configuración de puntos'
        );
    END IF;
    
    -- RESPUESTA: Confirmar éxito con información actualizada
    RETURN json_build_object(
        'success', true,
        'message', 'Configuración de puntos actualizada exitosamente',
        'nuevo_valor', p_nuevo_pesos_por_punto,
        'descripcion_actualizada', COALESCE(
            p_descripcion, 
            'Actualizado: 1 punto por cada $' || p_nuevo_pesos_por_punto::TEXT || ' pesos'
        )
    );
-- MANEJO DE ERRORES: Capturar excepciones
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Error inesperado al actualizar configuración: ' || SQLERRM
        );
END;
$_$;


--
-- Name: fun_actualizar_metodo_pago_default(numeric, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_actualizar_metodo_pago_default(p_id_usuario numeric, p_id_metodo_pago integer, p_usr_operacion numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_updated_rows INT;
BEGIN
    -- Quitar la marca de predeterminado de cualquier otro método del usuario
    UPDATE tab_metodos_pago_usuario
    SET 
        is_default = FALSE,
        usr_update = p_usr_operacion
    WHERE 
        id_usuario = p_id_usuario AND is_default = TRUE;

    -- Establecer el método seleccionado como predeterminado
    UPDATE tab_metodos_pago_usuario
    SET 
        is_default = TRUE,
        usr_update = p_usr_operacion
    WHERE 
        id_usuario = p_id_usuario AND id_metodo_pago = p_id_metodo_pago;

    GET DIAGNOSTICS v_updated_rows = ROW_COUNT;

    -- RESPUESTA
    IF v_updated_rows = 0 THEN
        RETURN json_build_object(
            'success', false, 
            'message', 'El método de pago no fue encontrado para este usuario.'
        );
    END IF;
    
    RETURN json_build_object(
        'success', true,
        'message', 'Método de pago predeterminado actualizado exitosamente.'
    );

EXCEPTION 
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false, 
            'message', 'Error inesperado: ' || SQLERRM
        );
END;
$$;


--
-- Name: fun_actualizar_pago(character varying, character varying, character varying, character varying, jsonb, numeric, numeric, timestamp without time zone, jsonb, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_actualizar_pago(p_provider_transaction_id character varying, p_status character varying, p_status_detail character varying, p_payment_method_type character varying, p_payment_method_extra jsonb, p_fee_amount numeric, p_net_received_amount numeric, p_provider_date_approved timestamp without time zone, p_raw_response jsonb, p_usr_operacion numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_updated_rows INT;
BEGIN
    -- VALIDACIONES
    IF p_provider_payment_id IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'El ID de pago del proveedor es obligatorio.');
    END IF;

    -- ACTUALIZACIÓN
    UPDATE tab_pagos
    SET
        status = p_status,
        status_detail = p_status_detail,
        payment_method_type = p_payment_method_type,
        payment_method_extra = p_payment_method_extra,
        fee_amount = p_fee_amount,
        net_received_amount = p_net_received_amount,
        provider_date_approved = p_provider_date_approved,
        raw_response = p_raw_response,
        estado_procesamiento = CASE WHEN p_status = 'APPROVED' THEN 'procesado' ELSE 'error' END,
        usr_update = p_usr_operacion,
        fec_update = NOW()
    WHERE
        -- Usamos el ID de transacción para encontrar el registro
        provider_transaction_id = p_provider_transaction_id;

    GET DIAGNOSTICS v_updated_rows = ROW_COUNT;

    -- RESPUESTA
    IF v_updated_rows = 0 THEN
        RETURN json_build_object(
            'success', false, 
            'message', 'No se encontró un pago con el ID de proveedor especificado.'
        );
    END IF;
    
    RETURN json_build_object(
        'success', true,
        'message', 'Pago actualizado exitosamente.'
    );

EXCEPTION 
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false, 
            'message', 'Error inesperado: ' || SQLERRM
        );
END;
$$;


--
-- Name: fun_actualizar_posicion_widget(integer, jsonb, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_actualizar_posicion_widget(p_id_widget integer, p_nueva_posicion jsonb, p_id_usuario numeric DEFAULT NULL::numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_widget_valido BOOLEAN;
BEGIN
    -- VERIFICAR: Widget existe y pertenece al usuario
    SELECT EXISTS(
        SELECT 1 FROM tab_widgets_dashboard w
        JOIN tab_dashboards_usuarios d ON w.id_dashboard = d.id_dashboard
        WHERE w.id_widget = p_id_widget
          AND (p_id_usuario IS NULL OR d.id_usuario = p_id_usuario)
          AND w.ind_activo = TRUE
          AND d.ind_activo = TRUE
    ) INTO v_widget_valido;
    
    IF NOT v_widget_valido THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Widget no encontrado o sin permisos',
            'id_widget', p_id_widget
        );
    END IF;
    
    -- ACTUALIZAR: Posición del widget
    UPDATE tab_widgets_dashboard 
    SET posicion_x = COALESCE((p_nueva_posicion->>'x')::INT, posicion_x),
        posicion_y = COALESCE((p_nueva_posicion->>'y')::INT, posicion_y),
        ancho_columnas = COALESCE((p_nueva_posicion->>'ancho')::INT, ancho_columnas),
        alto_filas = COALESCE((p_nueva_posicion->>'alto')::INT, alto_filas),
        orden_z = COALESCE((p_nueva_posicion->>'z_index')::INT, orden_z),
        fec_update = NOW()
    WHERE id_widget = p_id_widget;
    
    RETURN json_build_object(
        'success', true,
        'id_widget', p_id_widget,
        'nueva_posicion', p_nueva_posicion,
        'fecha_actualizacion', NOW()
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Error actualizando posición: ' || SQLERRM,
            'sql_state', SQLSTATE
        );
END;
$$;


--
-- Name: fun_actualizar_resumen_categoria(numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_actualizar_resumen_categoria(p_id_categoria numeric DEFAULT NULL::numeric, p_recalcular_todo boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_inicio_proceso TIMESTAMP := NOW();
    v_categorias_actualizadas INT := 0;
    v_mes_actual VARCHAR(7) := TO_CHAR(NOW(), 'YYYY-MM');
    v_mes_anterior VARCHAR(7) := TO_CHAR(NOW() - INTERVAL '1 month', 'YYYY-MM');
    v_categoria_record RECORD;
    v_stats_record RECORD;
    v_total_ventas_sistema DECIMAL(15,2) := 0;
    v_top_productos RECORD;
BEGIN
    -- OBTENER: Total de ventas del sistema para calcular participación
    SELECT SUM(o.val_total_pedido) INTO v_total_ventas_sistema
    FROM tab_ordenes o 
    WHERE o.ind_estado IN (2, 3); -- Órdenes pagadas o completadas
    
    v_total_ventas_sistema := COALESCE(v_total_ventas_sistema, 1); -- Evitar división por 0
    
    -- DECIDIR: Qué categorías actualizar (tabla categories)
    FOR v_categoria_record IN 
        SELECT DISTINCT c.id AS id_categoria
        FROM tab_categories c
        WHERE c.is_active = TRUE
          AND (p_recalcular_todo = TRUE OR 
               p_id_categoria IS NULL OR 
               c.id = p_id_categoria)
    LOOP
        -- CALCULAR: Estadísticas completas para la categoría
        SELECT 
            c.name AS nom_categoria,
            c.is_active AS categoria_activa,
            COUNT(p.id) AS total_productos,
            COUNT(CASE WHEN p.is_active THEN 1 END) AS productos_activos,
            COUNT(CASE WHEN ep.total_unidades_vendidas > 0 THEN 1 END) AS productos_con_ventas,
            COALESCE(SUM(ep.total_ordenes), 0) AS total_ordenes,
            COALESCE(SUM(ep.total_unidades_vendidas), 0) AS total_unidades_vendidas,
            COALESCE(SUM(ep.total_ingresos), 0) AS total_ingresos,
            COALESCE(SUM(ep.ventas_mes_actual), 0) AS ventas_mes_actual,
            COALESCE(SUM(ep.ingresos_mes_actual), 0) AS ingresos_mes_actual,
            COALESCE(SUM(ep.ventas_mes_anterior), 0) AS ventas_mes_anterior,
            COALESCE(SUM(ep.ingresos_mes_anterior), 0) AS ingresos_mes_anterior,
            MIN(ep.fecha_primera_venta) AS fecha_primera_venta,
            MAX(ep.fecha_ultima_venta) AS fecha_ultima_venta,
            CASE WHEN COUNT(p.id) > 0 THEN ROUND(AVG(ep.precio_actual), 2) ELSE 0 END AS precio_promedio_categoria
        INTO v_stats_record
        FROM tab_categories c
        LEFT JOIN tab_products p ON p.category_id = c.id
        LEFT JOIN tab_estadisticas_productos ep ON ep.product_id = p.id
        WHERE c.id = v_categoria_record.id_categoria
        GROUP BY c.id, c.name, c.is_active;
        
        -- CALCULAR: Análisis adicionales y productos top
        DECLARE
            v_participacion_ventas DECIMAL(5,2) := 0;
            v_crecimiento_mensual DECIMAL(5,2) := 0;
            v_producto_mas_vendido VARCHAR(255);
            v_producto_mayor_ingreso VARCHAR(255);
            v_unidades_top_producto INT := 0;
            v_mejor_mes_ventas VARCHAR(7);
        BEGIN
            -- Participación en ventas totales
            IF v_total_ventas_sistema > 0 AND v_stats_record.total_ingresos > 0 THEN
                v_participacion_ventas := ROUND((v_stats_record.total_ingresos / v_total_ventas_sistema) * 100, 2);
            END IF;
            
            -- Crecimiento mensual
            IF v_stats_record.ingresos_mes_anterior > 0 THEN
                v_crecimiento_mensual := ROUND(
                    ((v_stats_record.ingresos_mes_actual - v_stats_record.ingresos_mes_anterior) / 
                     v_stats_record.ingresos_mes_anterior) * 100, 2);
            ELSIF v_stats_record.ingresos_mes_actual > 0 THEN
                v_crecimiento_mensual := 100; -- Nuevo crecimiento desde 0
            END IF;
            
            -- Producto más vendido por unidades (products con category_id)
            SELECT ep.nom_producto, ep.total_unidades_vendidas
            INTO v_producto_mas_vendido, v_unidades_top_producto
            FROM tab_estadisticas_productos ep
            JOIN tab_products p ON p.id = ep.product_id AND p.category_id = v_categoria_record.id_categoria
            WHERE ep.total_unidades_vendidas > 0
            ORDER BY ep.total_unidades_vendidas DESC
            LIMIT 1;
            
            -- Producto que genera más ingresos
            SELECT ep.nom_producto INTO v_producto_mayor_ingreso
            FROM tab_estadisticas_productos ep
            JOIN tab_products p ON p.id = ep.product_id AND p.category_id = v_categoria_record.id_categoria
            WHERE ep.total_ingresos > 0
            ORDER BY ep.total_ingresos DESC LIMIT 1;
            
            -- Mejor mes de ventas de la categoría (vía variant -> product -> category_id)
            SELECT TO_CHAR(o.fec_pedido, 'YYYY-MM') INTO v_mejor_mes_ventas
            FROM tab_orden_productos op
            JOIN tab_product_variant_combinations pv ON pv.id = op.variant_id
            JOIN tab_product_variant_groups g ON g.id = pv.group_id
            JOIN tab_products p ON p.id = g.product_id AND p.category_id = v_categoria_record.id_categoria
            JOIN tab_ordenes o ON op.id_orden = o.id_orden
            WHERE o.ind_estado IN (2, 3)
            GROUP BY TO_CHAR(o.fec_pedido, 'YYYY-MM')
            ORDER BY SUM(op.cant_producto * op.precio_unitario_orden) DESC LIMIT 1;
            
            -- INSERTAR/ACTUALIZAR: tab_estadisticas_categorias (category_id)
            INSERT INTO tab_estadisticas_categorias (
                category_id,
                nom_categoria,
                categoria_activa,
                total_productos,
                productos_activos,
                productos_con_ventas,
                total_ordenes,
                total_unidades_vendidas,
                total_ingresos,
                ventas_mes_actual,
                ingresos_mes_actual,
                ventas_mes_anterior,
                ingresos_mes_anterior,
                participacion_ventas,
                crecimiento_mensual,
                precio_promedio_categoria,
                producto_mas_vendido,
                producto_mayor_ingreso,
                unidades_top_producto,
                fecha_primera_venta,
                fecha_ultima_venta,
                mejor_mes_ventas,
                ultima_actualizacion,
                periodo_calculo
            ) VALUES (
                v_categoria_record.id_categoria,
                v_stats_record.nom_categoria,
                v_stats_record.categoria_activa,
                v_stats_record.total_productos,
                v_stats_record.productos_activos,
                v_stats_record.productos_con_ventas,
                v_stats_record.total_ordenes,
                v_stats_record.total_unidades_vendidas,
                v_stats_record.total_ingresos,
                v_stats_record.ventas_mes_actual,
                v_stats_record.ingresos_mes_actual,
                v_stats_record.ventas_mes_anterior,
                v_stats_record.ingresos_mes_anterior,
                v_participacion_ventas,
                v_crecimiento_mensual,
                v_stats_record.precio_promedio_categoria,
                v_producto_mas_vendido,
                v_producto_mayor_ingreso,
                v_unidades_top_producto,
                v_stats_record.fecha_primera_venta,
                v_stats_record.fecha_ultima_venta,
                v_mejor_mes_ventas,
                NOW(),
                v_mes_actual
            )
            ON CONFLICT (category_id)
            DO UPDATE SET
                nom_categoria = EXCLUDED.nom_categoria,
                categoria_activa = EXCLUDED.categoria_activa,
                total_productos = EXCLUDED.total_productos,
                productos_activos = EXCLUDED.productos_activos,
                productos_con_ventas = EXCLUDED.productos_con_ventas,
                total_ordenes = EXCLUDED.total_ordenes,
                total_unidades_vendidas = EXCLUDED.total_unidades_vendidas,
                total_ingresos = EXCLUDED.total_ingresos,
                ventas_mes_actual = EXCLUDED.ventas_mes_actual,
                ingresos_mes_actual = EXCLUDED.ingresos_mes_actual,
                ventas_mes_anterior = EXCLUDED.ventas_mes_anterior,
                ingresos_mes_anterior = EXCLUDED.ingresos_mes_anterior,
                participacion_ventas = EXCLUDED.participacion_ventas,
                crecimiento_mensual = EXCLUDED.crecimiento_mensual,
                precio_promedio_categoria = EXCLUDED.precio_promedio_categoria,
                producto_mas_vendido = EXCLUDED.producto_mas_vendido,
                producto_mayor_ingreso = EXCLUDED.producto_mayor_ingreso,
                unidades_top_producto = EXCLUDED.unidades_top_producto,
                fecha_primera_venta = EXCLUDED.fecha_primera_venta,
                fecha_ultima_venta = EXCLUDED.fecha_ultima_venta,
                mejor_mes_ventas = EXCLUDED.mejor_mes_ventas,
                ultima_actualizacion = EXCLUDED.ultima_actualizacion,
                periodo_calculo = EXCLUDED.periodo_calculo;
                
            v_categorias_actualizadas := v_categorias_actualizadas + 1;
            
        END;
    END LOOP;
    
    -- RESPUESTA: Resultado de la actualización
    RETURN json_build_object(
        'success', true,
        'categorias_actualizadas', v_categorias_actualizadas,
        'tiempo_procesamiento', (NOW() - v_inicio_proceso),
        'periodo_calculo', v_mes_actual,
        'mes_anterior_procesado', v_mes_anterior,
        'total_ventas_sistema', v_total_ventas_sistema,
        'timestamp', NOW(),
        'tipo_actualizacion', CASE 
            WHEN p_recalcular_todo THEN 'RECALCULO_COMPLETO'
            WHEN p_id_categoria IS NOT NULL THEN 'CATEGORIA_ESPECIFICA'
            ELSE 'INCREMENTAL'
        END
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Error al actualizar estadísticas de categoría: ' || SQLERRM,
            'categorias_actualizadas', v_categorias_actualizadas,
            'tiempo_procesamiento', (NOW() - v_inicio_proceso),
            'sql_state', SQLSTATE
        );
END;
$$;


--
-- Name: fun_actualizar_resumen_ventas(numeric, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_actualizar_resumen_ventas(p_id_categoria numeric DEFAULT NULL::numeric, p_id_producto numeric DEFAULT NULL::numeric, p_recalcular_todo boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_inicio TIMESTAMP := NOW();
    v_productos_actualizados INT := 0;
    v_mes_actual VARCHAR(7) := TO_CHAR(NOW(), 'YYYY-MM');
    v_mes_anterior VARCHAR(7) := TO_CHAR(NOW() - INTERVAL '1 month', 'YYYY-MM');
    v_rec RECORD;
    v_stock_actual INT;
    v_precio_min DECIMAL(12,2);
BEGIN
    FOR v_rec IN
        SELECT DISTINCT p.id AS product_id
        FROM tab_orden_productos op
        JOIN tab_product_variant_combinations pv ON pv.id = op.variant_id
        JOIN tab_product_variant_groups g ON g.id = pv.group_id
        JOIN tab_products p ON p.id = g.product_id
        JOIN tab_ordenes o ON op.id_orden = o.id_orden
        WHERE o.ind_estado IN (2, 3)
          AND (p_recalcular_todo OR (p_id_categoria IS NULL OR p.category_id = p_id_categoria)
               AND (p_id_producto IS NULL OR p.id = p_id_producto))
    LOOP
        SELECT
            p.name,
            (SELECT MIN(c.price) FROM tab_product_variant_combinations c JOIN tab_product_variant_groups g ON g.id = c.group_id WHERE g.product_id = p.id AND c.is_active),
            (SELECT COALESCE(SUM(c.stock), 0) FROM tab_product_variant_combinations c JOIN tab_product_variant_groups g ON g.id = c.group_id WHERE g.product_id = p.id AND c.is_active),
            p.is_active,
            COUNT(DISTINCT o.id_orden),
            COALESCE(SUM(op.cant_producto), 0),
            COALESCE(SUM(op.cant_producto * op.precio_unitario_orden), 0),
            COALESCE(SUM(CASE WHEN TO_CHAR(o.fec_pedido, 'YYYY-MM') = v_mes_actual THEN op.cant_producto ELSE 0 END), 0),
            COALESCE(SUM(CASE WHEN TO_CHAR(o.fec_pedido, 'YYYY-MM') = v_mes_actual THEN op.cant_producto * op.precio_unitario_orden ELSE 0 END), 0),
            COALESCE(SUM(CASE WHEN TO_CHAR(o.fec_pedido, 'YYYY-MM') = v_mes_anterior THEN op.cant_producto ELSE 0 END), 0),
            COALESCE(SUM(CASE WHEN TO_CHAR(o.fec_pedido, 'YYYY-MM') = v_mes_anterior THEN op.cant_producto * op.precio_unitario_orden ELSE 0 END), 0),
            MIN(o.fec_pedido)::DATE,
            MAX(o.fec_pedido)::DATE,
            CASE WHEN SUM(op.cant_producto) > 0 THEN ROUND(SUM(op.cant_producto * op.precio_unitario_orden) / SUM(op.cant_producto), 2) ELSE 0 END,
            ROUND(COALESCE(SUM(op.cant_producto), 0) / GREATEST(1, EXTRACT(months FROM AGE(NOW(), MIN(o.fec_pedido)))), 2),
            ROUND(COALESCE(SUM(op.cant_producto * op.precio_unitario_orden), 0) / GREATEST(1, EXTRACT(months FROM AGE(NOW(), MIN(o.fec_pedido)))), 2)
        INTO v_rec.nom_producto, v_precio_min, v_stock_actual, v_rec.producto_activo,
             v_rec.total_ordenes, v_rec.total_unidades_vendidas, v_rec.total_ingresos,
             v_rec.ventas_mes_actual, v_rec.ingresos_mes_actual, v_rec.ventas_mes_anterior, v_rec.ingresos_mes_anterior,
             v_rec.fecha_primera_venta, v_rec.fecha_ultima_venta, v_rec.precio_promedio_venta,
             v_rec.promedio_venta_mensual, v_rec.promedio_ingreso_mensual
        FROM tab_products p
        LEFT JOIN tab_product_variant_groups g ON g.product_id = p.id
        LEFT JOIN tab_product_variant_combinations pv ON pv.group_id = g.id
        LEFT JOIN tab_orden_productos op ON op.variant_id = pv.id
        LEFT JOIN tab_ordenes o ON op.id_orden = o.id_orden AND o.ind_estado IN (2, 3)
        WHERE p.id = v_rec.product_id
        GROUP BY p.id, p.name, p.is_active;

        INSERT INTO tab_estadisticas_productos (
            product_id, nom_producto, precio_actual, stock_actual, producto_activo,
            total_ordenes, total_unidades_vendidas, total_ingresos,
            ventas_mes_actual, ingresos_mes_actual, ventas_mes_anterior, ingresos_mes_anterior,
            promedio_venta_mensual, promedio_ingreso_mensual, precio_promedio_venta,
            fecha_primera_venta, fecha_ultima_venta, mes_mejor_venta, mejor_venta_unidades,
            dias_desde_ultima_venta, rotacion_inventario, nivel_rotacion,
            ultima_actualizacion, periodo_calculo
        ) VALUES (
            v_rec.product_id, v_rec.nom_producto, v_precio_min, v_stock_actual, v_rec.producto_activo,
            v_rec.total_ordenes, v_rec.total_unidades_vendidas, v_rec.total_ingresos,
            v_rec.ventas_mes_actual, v_rec.ingresos_mes_actual, v_rec.ventas_mes_anterior, v_rec.ingresos_mes_anterior,
            v_rec.promedio_venta_mensual, v_rec.promedio_ingreso_mensual, v_rec.precio_promedio_venta,
            v_rec.fecha_primera_venta, v_rec.fecha_ultima_venta, NULL, 0,
            CASE WHEN v_rec.fecha_ultima_venta IS NOT NULL THEN EXTRACT(days FROM NOW() - v_rec.fecha_ultima_venta)::INT ELSE NULL END,
            0, CASE WHEN v_rec.total_unidades_vendidas = 0 THEN 'SIN_VENTAS' ELSE 'MEDIA' END,
            NOW(), v_mes_actual
        )
        ON CONFLICT (product_id) DO UPDATE SET
            nom_producto = EXCLUDED.nom_producto,
            precio_actual = EXCLUDED.precio_actual,
            stock_actual = EXCLUDED.stock_actual,
            producto_activo = EXCLUDED.producto_activo,
            total_ordenes = EXCLUDED.total_ordenes,
            total_unidades_vendidas = EXCLUDED.total_unidades_vendidas,
            total_ingresos = EXCLUDED.total_ingresos,
            ventas_mes_actual = EXCLUDED.ventas_mes_actual,
            ingresos_mes_actual = EXCLUDED.ingresos_mes_actual,
            ventas_mes_anterior = EXCLUDED.ventas_mes_anterior,
            ingresos_mes_anterior = EXCLUDED.ingresos_mes_anterior,
            promedio_venta_mensual = EXCLUDED.promedio_venta_mensual,
            promedio_ingreso_mensual = EXCLUDED.promedio_ingreso_mensual,
            precio_promedio_venta = EXCLUDED.precio_promedio_venta,
            fecha_primera_venta = EXCLUDED.fecha_primera_venta,
            fecha_ultima_venta = EXCLUDED.fecha_ultima_venta,
            dias_desde_ultima_venta = EXCLUDED.dias_desde_ultima_venta,
            nivel_rotacion = EXCLUDED.nivel_rotacion,
            ultima_actualizacion = EXCLUDED.ultima_actualizacion,
            periodo_calculo = EXCLUDED.periodo_calculo;

        v_productos_actualizados := v_productos_actualizados + 1;
    END LOOP;

    RETURN json_build_object(
        'success', true,
        'productos_actualizados', v_productos_actualizados,
        'tiempo_procesamiento', (NOW() - v_inicio),
        'periodo_calculo', v_mes_actual,
        'timestamp', NOW()
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'error', SQLERRM,
            'productos_actualizados', v_productos_actualizados,
            'sql_state', SQLSTATE
        );
END;
$$;


--
-- Name: fun_actualizar_stock_automatico(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_actualizar_stock_automatico() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_stock_actual  INT;
    v_stock_nuevo   INT;
    v_record        RECORD;
    v_id_orden      tab_ordenes.id_orden%TYPE;
    v_usr           DECIMAL(10);
    v_cogs_total    DECIMAL(14, 2);
    v_cogs_unit     DECIMAL(12, 2);
    v_saldo_actual  DECIMAL(14, 2);
BEGIN
    -- Disparar al entrar a "procesada/pagada" (2) o "completada" (3)
    IF NEW.ind_estado NOT IN (2, 3) THEN
        RETURN NULL;
    END IF;
    -- En UPDATE, solo descontar si antes no estaba pagada (evitar doble descuento)
    IF TG_OP = 'UPDATE' AND OLD.ind_estado IN (2, 3) THEN
        RETURN NULL;
    END IF;

    v_id_orden := NEW.id_orden;
    v_usr := COALESCE(NEW.usr_update, 1000000000);

    FOR v_record IN
        SELECT op.id_orden_producto, op.variant_id, op.cant_producto, p.name AS nom_producto
        FROM tab_orden_productos op
        JOIN tab_product_variant_combinations pv ON pv.id = op.variant_id
        JOIN tab_product_variant_groups g ON g.id = pv.group_id
        JOIN tab_products p ON p.id = g.product_id
        WHERE op.id_orden = v_id_orden
    LOOP
        -- Bloqueo de fila: serializa ventas/compras concurrentes de esta variante
        -- en orden de llegada (FIFO). El segundo proceso espera a que el primero
        -- confirme, leyendo siempre el stock más reciente -> sin sobreventa.
        SELECT stock INTO v_stock_actual
        FROM tab_product_variant_combinations
        WHERE id = v_record.variant_id
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Error: Combinación no encontrada (variant_id %)', v_record.variant_id;
        END IF;

        IF v_stock_actual < v_record.cant_producto THEN
            RAISE EXCEPTION 'Error: Stock insuficiente para %. Stock actual: %, Solicitado: %',
                v_record.nom_producto, v_stock_actual, v_record.cant_producto;
        END IF;

        v_stock_nuevo := v_stock_actual - v_record.cant_producto;

        UPDATE tab_product_variant_combinations
        SET stock = v_stock_nuevo, usr_update = v_usr, fec_update = NOW()
        WHERE id = v_record.variant_id;

        -- Consumo FIFO de lotes -> COGS de esta línea de venta.
        v_cogs_total := fun_consumir_fifo(v_record.variant_id, v_record.cant_producto);
        v_cogs_unit := CASE
            WHEN v_record.cant_producto > 0 THEN ROUND(v_cogs_total / v_record.cant_producto, 2)
            ELSE 0 END;
        v_saldo_actual := fun_saldo_costo_inventario(v_record.variant_id);

        INSERT INTO tab_movimientos_inventario (
            variant_id, tipo_movimiento, cantidad, costo_unitario_movimiento,
            stock_anterior, stock_actual,
            saldo_costo_total_anterior_mov, saldo_costo_total_actual_mov,
            id_orden_usuario_detalle, descripcion, usr_insert
        ) VALUES (
            v_record.variant_id,
            'salida_venta',
            v_record.cant_producto,
            v_cogs_unit,
            v_stock_actual,
            v_stock_nuevo,
            v_saldo_actual + v_cogs_total,
            v_saldo_actual,
            v_record.id_orden_producto,
            'Venta procesada (FIFO) - Orden #' || v_id_orden || ' - ' || v_record.nom_producto,
            v_usr
        );
    END LOOP;

    RETURN NULL;
EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Error en actualización automática de stock: %', SQLERRM;
END;
$$;


--
-- Name: fun_acumular_puntos_compra(numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_acumular_puntos_compra(p_id_usuario numeric, p_id_orden numeric, p_val_total_pedido numeric, p_usr_operacion numeric) RETURNS json
    LANGUAGE plpgsql
    AS $_$
DECLARE
    -- Variables para cálculo de puntos
    v_puntos_ganados INT;                               -- Puntos calculados por la compra
    v_saldo_anterior INT;                               -- Saldo de puntos antes de acumular
    v_saldo_nuevo INT;                                  -- Saldo de puntos después de acumular
    v_usuario_existe BOOLEAN := FALSE;                  -- Flag para verificar si usuario tiene registro
BEGIN
    -- VALIDACIÓN 1: Usuario obligatorio
    IF p_id_usuario IS NULL OR p_id_usuario <= 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El ID de usuario es obligatorio y debe ser mayor a 0'
        );
    END IF;
    
    -- VALIDACIÓN 2: Orden obligatoria
    IF p_id_orden IS NULL OR p_id_orden <= 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El ID de orden es obligatorio y debe ser mayor a 0'
        );
    END IF;
    
    -- VALIDACIÓN 3: Valor total debe ser positivo
    IF p_val_total_pedido IS NULL OR p_val_total_pedido <= 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El valor total del pedido debe ser mayor a 0'
        );
    END IF;
    
    -- VALIDACIÓN 4: Usuario operación para auditoría
    IF p_usr_operacion IS NULL OR p_usr_operacion <= 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El usuario que realiza la operación es obligatorio para auditoría'
        );
    END IF;
    
    -- VALIDACIÓN 5: Verificar que la orden no haya acumulado puntos previamente
    IF EXISTS (
        SELECT 1 FROM tab_movimientos_puntos 
        WHERE id_orden_origen = p_id_orden 
          AND tipo_movimiento = 1  -- tipo 1 = acumulación
    ) THEN
        RETURN json_build_object(
            'success', false,
            'message', 'La orden ' || p_id_orden || ' ya tiene puntos acumulados previamente'
        );
    END IF;
    
    -- PASO 1: Calcular puntos ganados por la compra
    BEGIN
        SELECT fun_calcular_puntos_por_compra(p_val_total_pedido) INTO v_puntos_ganados;
    EXCEPTION
        WHEN OTHERS THEN
            RETURN json_build_object(
                'success', false,
                'message', 'Error al calcular puntos: ' || SQLERRM
            );
    END;
    
    -- VERIFICACIÓN: Si no se ganan puntos, no hay nada que hacer
    IF v_puntos_ganados <= 0 THEN
        RETURN json_build_object(
            'success', true,
            'message', 'Compra procesada, pero no genera puntos (valor insuficiente)',
            'puntos_acumulados', 0,
            'saldo_anterior', 0,
            'saldo_nuevo', 0
        );
    END IF;
    
    -- PASO 2: Verificar si el usuario ya tiene registro de puntos
    SELECT 
        CASE WHEN COUNT(*) > 0 THEN TRUE ELSE FALSE END,
        COALESCE(MAX(puntos_disponibles), 0)
    INTO v_usuario_existe, v_saldo_anterior
    FROM tab_puntos_usuario
    WHERE id_usuario = p_id_usuario;
    
    -- PASO 3: Crear o actualizar registro de puntos del usuario
    IF NOT v_usuario_existe THEN
        -- INSERCIÓN: Crear registro inicial para el usuario
        INSERT INTO tab_puntos_usuario (
            id_usuario,
            puntos_disponibles,
            puntos_totales_ganados,
            puntos_totales_canjeados,
            usr_insert
        ) VALUES (
            p_id_usuario,
            v_puntos_ganados,                               -- Puntos disponibles = puntos ganados
            v_puntos_ganados,                               -- Total ganados = puntos ganados
            0,                                              -- Total canjeados = 0 (nuevo usuario)
            p_usr_operacion                               -- Usuario que registra
        );
        
        v_saldo_anterior := 0;                              -- Era un usuario nuevo
        v_saldo_nuevo := v_puntos_ganados;                  -- Su nuevo saldo son los puntos ganados
    ELSE
        -- ACTUALIZACIÓN: Sumar puntos al usuario existente
        UPDATE tab_puntos_usuario 
        SET 
            puntos_disponibles = puntos_disponibles + v_puntos_ganados,
            puntos_totales_ganados = puntos_totales_ganados + v_puntos_ganados,
            usr_update = p_usr_operacion
        WHERE id_usuario = p_id_usuario;
        
        v_saldo_nuevo := v_saldo_anterior + v_puntos_ganados;
    END IF;
    
    -- PASO 4: Registrar movimiento en historial de puntos
    INSERT INTO tab_movimientos_puntos (
        id_usuario,
        tipo_movimiento,                                    -- tipo 1 = acumulación
        cantidad_puntos,                                    -- Positivo para acumulación
        puntos_disponibles_anterior,
        puntos_disponibles_actual,
        id_orden_origen,                                    -- Orden que generó los puntos
        id_descuento_canjeado,                              -- NULL para acumulaciones
        descripcion,
        usr_insert
    ) VALUES (
        p_id_usuario,
        1,                                                  -- tipo 1 = acumulación
        v_puntos_ganados,                                   -- Cantidad positiva
        v_saldo_anterior,                                   -- Saldo antes de la acumulación
        v_saldo_nuevo,                                      -- Saldo después de la acumulación
        p_id_orden,                                         -- Orden origen
        NULL,                                               -- No aplica para acumulaciones
        'Puntos ganados por compra - Orden #' || p_id_orden || ' - Valor base: $' || p_val_total_pedido,
        p_usr_operacion
    );
    
    -- RESPUESTA: Retornar resultado exitoso con información detallada
    RETURN json_build_object(
        'success', true,
        'message', 'Puntos acumulados exitosamente por compra realizada',
        'puntos_acumulados', v_puntos_ganados,
        'saldo_anterior', v_saldo_anterior,
        'saldo_nuevo', v_saldo_nuevo,
        'orden_origen', p_id_orden,
        'valor_compra', p_val_total_pedido
    );

-- MANEJO DE ERRORES: Capturar excepciones no contempladas
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Error inesperado al acumular puntos: ' || SQLERRM,
            'detalle', 'Usuario: ' || p_id_usuario || ', Orden: ' || p_id_orden
        );
END;
$_$;


--
-- Name: fun_agregar_metodo_pago(numeric, character varying, character varying, character varying, character varying, integer, integer, character varying, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_agregar_metodo_pago(p_id_usuario numeric, p_provider_name character varying, p_provider_source_id character varying, p_brand character varying, p_last_four_digits character varying, p_expiration_month integer, p_expiration_year integer, p_card_holder character varying, p_usr_operacion numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_metodo_pago INT;
    v_new_payment_method JSON;
BEGIN
    -- VALIDACIONES
    IF p_id_usuario IS NULL OR p_provider_source_id IS NULL OR p_last_four_digits IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'ID de usuario, ID de fuente de pago y últimos 4 dígitos son obligatorios');
    END IF;

    -- INSERCIÓN
    INSERT INTO tab_metodos_pago_usuario (
        id_usuario,
        provider_name,
        provider_source_id, -- Columna actualizada
        brand,
        last_four_digits,
        expiration_month,
        expiration_year,
        card_holder,        -- Columna añadida
        usr_insert
    ) VALUES (
        p_id_usuario,
        p_provider_name,
        p_provider_source_id,
        p_brand,
        p_last_four_digits,
        p_expiration_month,
        p_expiration_year,
        p_card_holder,
        p_usr_operacion
    )
    ON CONFLICT (id_usuario, provider_source_id, provider_name) DO NOTHING
    RETURNING id_metodo_pago INTO v_id_metodo_pago;

    -- RESPUESTA
    IF v_id_metodo_pago IS NULL THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El método de pago ya existe para este usuario.'
        );
    END IF;

    -- Devolver el registro completo para usar en la API
    SELECT json_build_object(
        'id_metodo_pago', m.id_metodo_pago,
        'provider_source_id', m.provider_source_id,
        'brand', m.brand,
        'last_four_digits', m.last_four_digits,
        'card_holder', m.card_holder,
        'is_default', m.is_default
    ) INTO v_new_payment_method
    FROM tab_metodos_pago_usuario m WHERE m.id_metodo_pago = v_id_metodo_pago;

    RETURN json_build_object(
        'success', true,
        'message', 'Método de pago agregado exitosamente.',
        'data', v_new_payment_method
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Error inesperado: ' || SQLERRM
        );
END;
$$;


--
-- Name: fun_agregar_producto_carrito(numeric, character varying, numeric, integer, jsonb, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_agregar_producto_carrito(p_id_usuario numeric, p_session_id character varying, p_variant_id numeric, p_cantidad integer, p_opciones_elegidas jsonb DEFAULT '{}'::jsonb, p_usr_operacion numeric DEFAULT NULL::numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_carrito tab_carritos.id_carrito%TYPE;
    v_precio tab_product_variant_combinations.price%TYPE;
    v_stock tab_product_variant_combinations.stock%TYPE;
    v_cantidad_actual tab_carrito_productos.cantidad%TYPE;
    v_usr_final tab_carrito_productos.usr_insert%TYPE;
BEGIN
    IF p_id_usuario IS NULL AND p_session_id IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Debe proporcionar id_usuario o session_id');
    END IF;

    v_usr_final := COALESCE(p_usr_operacion, p_id_usuario, ABS(hashtext(p_session_id))::DECIMAL(10));

    SELECT price, stock INTO v_precio, v_stock
    FROM tab_product_variant_combinations
    WHERE id = p_variant_id AND is_active = TRUE;

    IF v_precio IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Variante no encontrada o no disponible');
    END IF;

    v_id_carrito := fun_obtener_carrito_usuario(p_id_usuario, p_session_id);

    SELECT cantidad INTO v_cantidad_actual
    FROM tab_carrito_productos
    WHERE id_carrito = v_id_carrito AND variant_id = p_variant_id;

    IF (COALESCE(v_cantidad_actual, 0) + p_cantidad) > v_stock THEN
        RETURN json_build_object('success', false, 'message', 'Stock insuficiente');
    END IF;

    INSERT INTO tab_carrito_productos (
        id_carrito, variant_id, cantidad, precio_unitario_carrito, opciones_elegidas, usr_insert
    ) VALUES (
        v_id_carrito, p_variant_id, p_cantidad, v_precio, COALESCE(p_opciones_elegidas, '{}'::JSONB), v_usr_final
    )
    ON CONFLICT (id_carrito, variant_id)
    DO UPDATE SET
        cantidad = tab_carrito_productos.cantidad + p_cantidad,
        precio_unitario_carrito = v_precio,
        opciones_elegidas = COALESCE(EXCLUDED.opciones_elegidas, tab_carrito_productos.opciones_elegidas, '{}'::JSONB),
        usr_update = v_usr_final,
        fec_update = NOW();

    UPDATE tab_carritos SET fec_update = NOW(), usr_update = v_usr_final WHERE id_carrito = v_id_carrito;

    RETURN json_build_object('success', true, 'message', 'Producto agregado al carrito', 'id_carrito', v_id_carrito);
END;
$$;


--
-- Name: fun_agregar_widget(integer, integer, jsonb, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_agregar_widget(p_id_dashboard integer, p_id_kpi integer, p_configuracion_widget jsonb DEFAULT '{}'::jsonb, p_id_usuario numeric DEFAULT NULL::numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_dashboard_valido BOOLEAN;
    v_kpi_valido BOOLEAN;
    v_nuevo_widget_id INT;
    v_posicion_x INT := 0;
    v_posicion_y INT := 0;
BEGIN
    -- VERIFICAR: Dashboard existe y pertenece al usuario
    SELECT EXISTS(
        SELECT 1 FROM tab_dashboards_usuarios 
        WHERE id_dashboard = p_id_dashboard
          AND (p_id_usuario IS NULL OR id_usuario = p_id_usuario)
          AND ind_activo = TRUE
    ) INTO v_dashboard_valido;
    
    IF NOT v_dashboard_valido THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Dashboard no encontrado o sin permisos',
            'id_dashboard', p_id_dashboard
        );
    END IF;
    
    -- VERIFICAR: KPI existe y está activo
    SELECT EXISTS(
        SELECT 1 FROM tab_kpis_maestros 
        WHERE id_kpi = p_id_kpi AND ind_activo = TRUE
    ) INTO v_kpi_valido;
    
    IF NOT v_kpi_valido THEN
        RETURN json_build_object(
            'success', false,
            'error', 'KPI no encontrado o inactivo',
            'id_kpi', p_id_kpi
        );
    END IF;
    
    -- CALCULAR: Posición automática si no se especifica
    IF p_configuracion_widget->>'posicion_x' IS NULL OR p_configuracion_widget->>'posicion_y' IS NULL THEN
        SELECT 
            COALESCE(MAX(posicion_x + ancho_columnas), 0),
            COALESCE(MAX(posicion_y), 0)
        INTO v_posicion_x, v_posicion_y
        FROM tab_widgets_dashboard 
        WHERE id_dashboard = p_id_dashboard AND ind_activo = TRUE;
        
        -- Si se excede el ancho de la grilla, pasar a siguiente fila
        DECLARE
            v_columnas_grid INT;
        BEGIN
            SELECT columnas_grid INTO v_columnas_grid
            FROM tab_dashboards_usuarios 
            WHERE id_dashboard = p_id_dashboard;
            
            IF v_posicion_x >= v_columnas_grid THEN
                v_posicion_x := 0;
                v_posicion_y := v_posicion_y + 1;
            END IF;
        END;
    ELSE
        v_posicion_x := (p_configuracion_widget->>'posicion_x')::INT;
        v_posicion_y := (p_configuracion_widget->>'posicion_y')::INT;
    END IF;
    
    -- CREAR: Nuevo widget
    INSERT INTO tab_widgets_dashboard (
        id_dashboard, id_kpi, posicion_x, posicion_y,
        ancho_columnas, alto_filas, orden_z,
        titulo_personalizado, mostrar_titulo, tipo_grafico, color_personalizado,
        mostrar_valor_anterior, mostrar_porcentaje_cambio,
        parametros_kpi, periodo_comparacion, filtros_adicionales
    ) VALUES (
        p_id_dashboard, p_id_kpi, v_posicion_x, v_posicion_y,
        COALESCE((p_configuracion_widget->>'ancho_columnas')::INT, 1),
        COALESCE((p_configuracion_widget->>'alto_filas')::INT, 1),
        COALESCE((p_configuracion_widget->>'orden_z')::INT, 1),
        p_configuracion_widget->>'titulo_personalizado',
        COALESCE((p_configuracion_widget->>'mostrar_titulo')::BOOLEAN, TRUE),
        p_configuracion_widget->>'tipo_grafico',
        p_configuracion_widget->>'color_personalizado',
        COALESCE((p_configuracion_widget->>'mostrar_valor_anterior')::BOOLEAN, TRUE),
        COALESCE((p_configuracion_widget->>'mostrar_porcentaje_cambio')::BOOLEAN, TRUE),
        COALESCE(p_configuracion_widget->'parametros_kpi', '{}'),
        COALESCE(p_configuracion_widget->>'periodo_comparacion', 'MES_ANTERIOR'),
        COALESCE(p_configuracion_widget->'filtros_adicionales', '{}')
    ) RETURNING id_widget INTO v_nuevo_widget_id;
    
    -- RESPUESTA: Widget agregado exitosamente
    RETURN json_build_object(
        'success', true,
        'id_widget', v_nuevo_widget_id,
        'id_dashboard', p_id_dashboard,
        'id_kpi', p_id_kpi,
        'posicion', json_build_object('x', v_posicion_x, 'y', v_posicion_y),
        'configuracion_aplicada', p_configuracion_widget,
        'fecha_creacion', NOW()
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Error agregando widget: ' || SQLERRM,
            'sql_state', SQLSTATE
        );
END;
$$;


--
-- Name: fun_aplicar_canje_orden(integer, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_aplicar_canje_orden(p_id_canje integer, p_id_orden numeric, p_id_usuario numeric, p_usr_operacion numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_canje RECORD;
    v_orden RECORD;
    v_descuento_info RECORD;
    v_valor_descuento DECIMAL(10,2) := 0;
    v_total_productos DECIMAL(10,2);
    v_total_descuentos_actual DECIMAL(10,2);
    v_total_final DECIMAL(10,2);
    v_descuentos_aplicados JSON;
    v_nuevo_descuento JSON;
BEGIN
    -- PASO 1: Obtener información del canje y validar
    SELECT 
        c.id_canje, c.id_usuario, c.id_descuento, c.puntos_utilizados,
        c.ind_utilizado, c.fec_expiracion_canje, c.id_orden_aplicado,
        d.nom_descuento, d.tipo_calculo, d.val_porce_descuento, d.val_monto_descuento,
        d.aplica_a, d.min_valor_pedido, d.cantidad_minima_producto, d.monto_minimo_producto,
        d.id_categoria_aplica, d.id_marca_aplica, d.id_producto_aplica,
        d.id_categoria, d.id_linea, d.id_sublinea
    INTO v_canje
    FROM tab_canjes_puntos_descuentos c
    JOIN tab_descuentos d ON c.id_descuento = d.id_descuento
    WHERE c.id_canje = p_id_canje;

    -- VALIDACIÓN 1: Verificar que el canje existe
    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El canje especificado no existe'
        );
    END IF;

    -- VALIDACIÓN 2: Verificar que pertenece al usuario
    IF v_canje.id_usuario != p_id_usuario THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El canje no pertenece al usuario especificado'
        );
    END IF;

    -- VALIDACIÓN 3: Verificar que no esté ya utilizado
    IF v_canje.ind_utilizado THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El canje ya ha sido utilizado',
            'orden_aplicado', v_canje.id_orden_aplicado
        );
    END IF;

    -- VALIDACIÓN 4: Verificar que no haya expirado
    IF v_canje.fec_expiracion_canje IS NOT NULL AND v_canje.fec_expiracion_canje < CURRENT_DATE THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El canje ha expirado',
            'fecha_expiracion', v_canje.fec_expiracion_canje
        );
    END IF;

    -- VALIDACIÓN 5: Verificar que la orden existe y pertenece al usuario
    SELECT 
        o.id_orden, o.id_usuario, o.val_total_productos, o.val_total_descuentos, 
        o.val_total_pedido, o.ind_estado, o.detalle_descuentos_aplicados
    INTO v_orden
    FROM tab_ordenes o
    WHERE o.id_orden = p_id_orden AND o.id_usuario = p_id_usuario;
    
    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'La orden no existe o no pertenece al usuario'
        );
    END IF;

    -- VALIDACIÓN 6: Verificar que la orden no esté completada
    IF v_orden.ind_estado = 3 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'No se puede aplicar canje a una orden ya completada'
        );
    END IF;

    -- PASO 2: Calcular valor del descuento usando la misma lógica que fun_calcular_total_carrito
    v_total_productos := v_orden.val_total_productos;
    
    -- Calcular descuento según el tipo de aplicación
    CASE 
        -- TIPO 1: Descuento por total del pedido
        WHEN v_canje.aplica_a = 'total_pedido' AND v_total_productos >= v_canje.min_valor_pedido THEN
            IF v_canje.tipo_calculo THEN 
                -- Porcentual sobre el total de productos
                v_valor_descuento := v_total_productos * v_canje.val_porce_descuento / 100;
            ELSE 
                -- Fijo: no puede exceder el total
                v_valor_descuento := LEAST(v_canje.val_monto_descuento, v_total_productos);
            END IF;
            
        -- TIPO 2: Descuento por producto específico
        WHEN v_canje.aplica_a = 'producto_especifico' THEN
            SELECT COALESCE(SUM(
                CASE WHEN v_canje.tipo_calculo THEN 
                   -- Porcentual sobre el valor del producto específico
                   (op.cantidad * op.precio_unitario * v_canje.val_porce_descuento / 100)
                ELSE 
                   -- Fijo: una sola aplicación por producto
                   LEAST(op.cantidad, 1) * v_canje.val_monto_descuento
                END
            ), 0) INTO v_valor_descuento
            FROM tab_orden_productos op
            WHERE op.id_orden = p_id_orden
                AND op.id_categoria_producto = v_canje.id_categoria
                AND op.id_linea_producto = v_canje.id_linea
                AND op.id_sublinea_producto = v_canje.id_sublinea
                AND op.id_producto = v_canje.id_producto_aplica
                AND op.cantidad >= v_canje.cantidad_minima_producto
                AND (op.cantidad * op.precio_unitario) >= v_canje.monto_minimo_producto;
                
        -- TIPO 3: Descuento por categoría específica
        WHEN v_canje.aplica_a = 'categoria_especifica' THEN
            SELECT COALESCE(SUM(
                CASE WHEN v_canje.tipo_calculo THEN 
                   -- Porcentual sobre todos los productos de la categoría
                   (op.cantidad * op.precio_unitario * v_canje.val_porce_descuento / 100)
                ELSE 
                   -- Fijo: por cada producto de la categoría
                   op.cantidad * v_canje.val_monto_descuento
                END
            ), 0) INTO v_valor_descuento
            FROM tab_orden_productos op
            WHERE op.id_orden = p_id_orden
                AND op.id_categoria_producto = v_canje.id_categoria_aplica
                AND op.cantidad >= v_canje.cantidad_minima_producto
                AND (op.cantidad * op.precio_unitario) >= v_canje.monto_minimo_producto;
                
        -- TIPO 4: Descuento por marca específica
        WHEN v_canje.aplica_a = 'marca_especifica' THEN
            SELECT COALESCE(SUM(
                CASE WHEN v_canje.tipo_calculo THEN 
                   -- Porcentual sobre todos los productos de la marca
                   (op.cantidad * op.precio_unitario * v_canje.val_porce_descuento / 100)
                ELSE 
                   -- Fijo: por cada producto de la marca
                   op.cantidad * v_canje.val_monto_descuento
                END
            ), 0) INTO v_valor_descuento
            FROM tab_orden_productos op
            JOIN tab_productos p ON (
                op.id_categoria_producto = p.id_categoria AND 
                op.id_linea_producto = p.id_linea AND 
                op.id_sublinea_producto = p.id_sublinea AND 
                op.id_producto = p.id_producto
                AND p.ind_activo = TRUE
            )
            WHERE op.id_orden = p_id_orden
                AND p.id_marca = v_canje.id_marca_aplica
                AND op.cantidad >= v_canje.cantidad_minima_producto
                AND (op.cantidad * op.precio_unitario) >= v_canje.monto_minimo_producto;
        ELSE
            v_valor_descuento := 0;
    END CASE;
    
    -- Validar que el descuento calculado sea aplicable
    IF v_valor_descuento <= 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El descuento no aplica a los productos de esta orden',
            'motivo', 'No cumple con los criterios de aplicación del descuento'
        );
    END IF;
    
    -- PASO 3: Actualizar totales de la orden
    v_total_descuentos_actual := COALESCE(v_orden.val_total_descuentos, 0) + v_valor_descuento;
    v_total_final := v_total_productos - v_total_descuentos_actual;
    
    -- Asegurar que el total final no sea negativo
    IF v_total_final < 0 THEN
        v_valor_descuento := v_valor_descuento + v_total_final; -- Ajustar descuento
        v_total_descuentos_actual := v_total_productos; -- Descuento máximo = total productos
        v_total_final := 0;
    END IF;
    
    -- PASO 4: Preparar JSON del nuevo descuento aplicado
    v_nuevo_descuento := json_build_object(
        'id_descuento', v_canje.id_descuento,
        'id_canje', v_canje.id_canje,
        'nombre', v_canje.nom_descuento,
        'tipo', CASE WHEN v_canje.tipo_calculo THEN 'porcentaje' ELSE 'monto_fijo' END,
        'valor', CASE WHEN v_canje.tipo_calculo THEN v_canje.val_porce_descuento ELSE v_canje.val_monto_descuento END,
        'descuento_aplicado', v_valor_descuento,
        'puntos_utilizados', v_canje.puntos_utilizados,
        'tipo_descuento', 'canje_puntos'
    );
    
    -- Agregar el nuevo descuento a los existentes
    v_descuentos_aplicados := COALESCE(v_orden.detalle_descuentos_aplicados, '[]'::JSON);
    v_descuentos_aplicados := (
        SELECT json_agg(elemento)
        FROM (
            SELECT json_array_elements(v_descuentos_aplicados) AS elemento
            UNION ALL
            SELECT v_nuevo_descuento AS elemento
        ) AS subconsulta
    );
    
    -- PASO 5: Actualizar la orden con los nuevos totales
    UPDATE tab_ordenes
    SET 
        val_total_descuentos = v_total_descuentos_actual,
        val_total_pedido = v_total_final,
        detalle_descuentos_aplicados = v_descuentos_aplicados,
        usr_update = p_usr_operacion,
        fec_update = NOW()
    WHERE id_orden = p_id_orden;
    
    -- PASO 6: Marcar el canje como utilizado
    UPDATE tab_canjes_puntos_descuentos
    SET 
        ind_utilizado = TRUE,
        fec_utilizacion = NOW(),
        id_orden_aplicado = p_id_orden,
        usr_update = p_usr_operacion
    WHERE id_canje = p_id_canje;

    -- RESPUESTA: Confirmar éxito con información completa
    RETURN json_build_object(
        'success', true,
        'message', 'Canje aplicado exitosamente a la orden',
        'id_canje', p_id_canje,
        'id_orden', p_id_orden,
        'descuento', v_canje.nom_descuento,
        'puntos_utilizados', v_canje.puntos_utilizados,
        'valor_descuento_aplicado', v_valor_descuento,
        'total_productos', v_total_productos,
        'total_descuentos', v_total_descuentos_actual,
        'total_final', v_total_final
    );

-- MANEJO DE ERRORES
EXCEPTION 
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false, 
            'message', 'Error inesperado: ' || SQLERRM,
            'error_code', SQLSTATE
        );
END;
$$;


--
-- Name: fun_audit_tablas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_audit_tablas() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.fec_insert = CURRENT_TIMESTAMP;
        RETURN NEW;
    END IF;
    
    IF TG_OP = 'UPDATE' THEN
        -- tab_movimientos_puntos es solo de inserción (historial), no se actualiza
        IF TG_TABLE_NAME != 'tab_movimientos_puntos' THEN
            NEW.fec_update = CURRENT_TIMESTAMP;
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP = 'DELETE' THEN
        INSERT INTO tab_reg_del(tab_name, atributos, usr_delete, fec_delete)
        VALUES (TG_TABLE_NAME, row_to_json(OLD), CURRENT_USER, CURRENT_TIMESTAMP);
        RETURN OLD;
    END IF;
END;
$$;


--
-- Name: fun_calcular_kpi(integer, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_calcular_kpi(p_id_kpi integer, p_parametros jsonb DEFAULT '{}'::jsonb, p_forzar_recalculo boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_kpi_config RECORD;
    v_cache_record RECORD;
    v_parametros_hash VARCHAR(64);
    v_sql_formula TEXT;
    v_sql_anterior TEXT;
    v_valor_actual DECIMAL(15,4);
    v_valor_anterior DECIMAL(15,4);
    v_porcentaje_cambio DECIMAL(5,2);
    v_tendencia VARCHAR(10);
    v_datos_extra JSONB;
    v_metadata JSONB;
    v_fecha_expiracion TIMESTAMP;
    v_inicio_calculo TIMESTAMP := NOW();
BEGIN
    -- OBTENER: Configuración del KPI
    SELECT 
        k.id_kpi,
        k.id_tipo_kpi,
        k.nom_kpi,
        k.descripcion_kpi,
        k.formula_sql,
        k.unidad_medida,
        k.formato_numero,
        k.rango_esperado_min,
        k.rango_esperado_max,
        k.frecuencia_actualizacion,
        k.ultima_actualizacion,
        k.duracion_cache_minutos,
        k.tipo_grafico_sugerido,
        k.color_primario,
        k.mostrar_tendencia,
        k.mostrar_comparacion,
        k.solo_administradores,
        k.requiere_parametros,
        k.parametros_permitidos,
        k.creado_por,
        k.ind_activo,
        k.fec_creacion,
        k.fec_update,
        t.nom_tipo_kpi
    INTO v_kpi_config
    FROM tab_kpis_maestros k
    JOIN tab_tipos_kpi t ON k.id_tipo_kpi = t.id_tipo_kpi
    WHERE k.id_kpi = p_id_kpi 
      AND k.ind_activo = TRUE;
    
    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'error', 'KPI no encontrado o inactivo',
            'id_kpi', p_id_kpi
        );
    END IF;
    
    -- GENERAR: Hash único para cache basado en parámetros
    v_parametros_hash := ENCODE(SHA256(CONVERT_TO(
        p_id_kpi::TEXT || COALESCE(p_parametros::TEXT, '{}'), 'UTF8'
    )), 'hex');
    
    -- VERIFICAR: Cache existente y válido
    IF NOT p_forzar_recalculo THEN
        SELECT
            id_cache,
            id_kpi,
            parametros_hash,
            valor_actual,
            valor_anterior,
            porcentaje_cambio,
            tendencia,
            datos_extra,
            metadata_calculo,
            fecha_calculo,
            fecha_expiracion,
            numero_accesos
        INTO v_cache_record
        FROM tab_valores_kpi_cache
        WHERE id_kpi = p_id_kpi 
          AND parametros_hash = v_parametros_hash
          AND fecha_expiracion > NOW();
        
        IF FOUND THEN
            -- ACTUALIZAR: Contador de accesos al cache
            UPDATE tab_valores_kpi_cache 
            SET numero_accesos = numero_accesos + 1
            WHERE id_cache = v_cache_record.id_cache;
            
            -- RETORNAR: Datos del cache
            RETURN json_build_object(
                'success', true,
                'origen', 'CACHE',
                'valor_actual', v_cache_record.valor_actual,
                'valor_anterior', v_cache_record.valor_anterior,
                'porcentaje_cambio', v_cache_record.porcentaje_cambio,
                'tendencia', v_cache_record.tendencia,
                'datos_extra', v_cache_record.datos_extra,
                'metadata', v_cache_record.metadata_calculo,
                'fecha_calculo', v_cache_record.fecha_calculo,
                'kpi_config', row_to_json(v_kpi_config)
            );
        END IF;
    END IF;
    
    -- PREPARAR: Fórmula SQL con reemplazo de parámetros
    v_sql_formula := v_kpi_config.formula_sql;
    
    -- REEMPLAZAR: Parámetros en la fórmula SQL
    IF p_parametros IS NOT NULL AND jsonb_typeof(p_parametros) = 'object' THEN
        DECLARE
            param_key TEXT;
            param_value TEXT;
        BEGIN
            FOR param_key, param_value IN 
                SELECT key, value FROM jsonb_each_text(p_parametros)
            LOOP
                v_sql_formula := REPLACE(v_sql_formula, '${' || param_key || '}', param_value);
            END LOOP;
        END;
    END IF;
    
    -- REEMPLAZAR: Variables de sistema comunes
    v_sql_formula := REPLACE(v_sql_formula, '${FECHA_ACTUAL}', '''NOW()''');
    v_sql_formula := REPLACE(v_sql_formula, '${MES_ACTUAL}', '''' || TO_CHAR(NOW(), 'YYYY-MM') || '''');
    v_sql_formula := REPLACE(v_sql_formula, '${MES_ANTERIOR}', '''' || TO_CHAR(NOW() - INTERVAL '1 month', 'YYYY-MM') || '''');
    v_sql_formula := REPLACE(v_sql_formula, '${TRIMESTRE_ACTUAL}', '''' || TO_CHAR(NOW(), 'YYYY-Q') || '''');
    v_sql_formula := REPLACE(v_sql_formula, '${AÑO_ACTUAL}', EXTRACT(YEAR FROM NOW())::TEXT);
    
    -- EJECUTAR: Fórmula principal para valor actual
    BEGIN
        EXECUTE v_sql_formula INTO v_valor_actual;
        v_valor_actual := COALESCE(v_valor_actual, 0);
    EXCEPTION
        WHEN OTHERS THEN
            RETURN json_build_object(
                'success', false,
                'error', 'Error ejecutando fórmula SQL: ' || SQLERRM,
                'sql_formula', v_sql_formula,
                'sql_state', SQLSTATE
            );
    END;
    
    -- CALCULAR: Valor anterior para comparación
    v_sql_anterior := REPLACE(v_kpi_config.formula_sql, '${MES_ACTUAL}', '''' || TO_CHAR(NOW() - INTERVAL '1 month', 'YYYY-MM') || '''');
    v_sql_anterior := REPLACE(v_sql_anterior, '${MES_ANTERIOR}', '''' || TO_CHAR(NOW() - INTERVAL '2 month', 'YYYY-MM') || '''');
    v_sql_anterior := REPLACE(v_sql_anterior, '${TRIMESTRE_ACTUAL}', '''' || TO_CHAR(NOW() - INTERVAL '3 months', 'YYYY-Q') || '''');
    v_sql_anterior := REPLACE(v_sql_anterior, '${AÑO_ACTUAL}', (EXTRACT(YEAR FROM NOW()) - 1)::TEXT);
    
    -- Reemplazar parámetros también en consulta anterior
    IF p_parametros IS NOT NULL AND jsonb_typeof(p_parametros) = 'object' THEN
        DECLARE
            param_key TEXT;
            param_value TEXT;
        BEGIN
            FOR param_key, param_value IN 
                SELECT key, value FROM jsonb_each_text(p_parametros)
            LOOP
                v_sql_anterior := REPLACE(v_sql_anterior, '${' || param_key || '}', param_value);
            END LOOP;
        END;
    END IF;
    
    BEGIN
        EXECUTE v_sql_anterior INTO v_valor_anterior;
        v_valor_anterior := COALESCE(v_valor_anterior, 0);
    EXCEPTION
        WHEN OTHERS THEN
            v_valor_anterior := 0; -- Si falla, usar 0 como valor anterior
    END;
    
    -- CALCULAR: Porcentaje de cambio y tendencia
    IF v_valor_anterior > 0 THEN
        v_porcentaje_cambio := ROUND(((v_valor_actual - v_valor_anterior) / v_valor_anterior) * 100, 2);
    ELSE
        v_porcentaje_cambio := CASE WHEN v_valor_actual > 0 THEN 100.00 ELSE 0.00 END;
    END IF;
    
    -- DETERMINAR: Tendencia
    IF v_porcentaje_cambio > 1 THEN
        v_tendencia := 'POSITIVA';
    ELSIF v_porcentaje_cambio < -1 THEN
        v_tendencia := 'NEGATIVA';
    ELSE
        v_tendencia := 'ESTABLE';
    END IF;
    
    -- CONSTRUIR: Datos extra para gráficos (si el KPI lo requiere)
    v_datos_extra := '{}';
    
    -- Si es un KPI que necesita datos históricos para gráficos
    IF v_kpi_config.tipo_grafico_sugerido IN ('LINEA', 'BARRA') THEN
        DECLARE
            v_sql_historico TEXT;
            v_datos_historicos JSONB;
        BEGIN
            -- Construir consulta histórica básica (últimos 12 meses)
            v_sql_historico := REPLACE(v_kpi_config.formula_sql, 
                'WHERE', 
                'WHERE DATE_TRUNC(''month'', fec_pedido) >= DATE_TRUNC(''month'', NOW() - INTERVAL ''11 months'') AND'
            );
            
            -- Para KPIs complejos, usar datos básicos
            v_datos_extra := json_build_object(
                'tipo_grafico', v_kpi_config.tipo_grafico_sugerido,
                'historico_disponible', true,
                'periodo_datos', '12_MESES'
            );
        EXCEPTION
            WHEN OTHERS THEN
                v_datos_extra := '{}';
        END;
    END IF;
    
    -- CONSTRUIR: Metadata del cálculo
    v_metadata := json_build_object(
        'tiempo_calculo_ms', EXTRACT(EPOCH FROM (NOW() - v_inicio_calculo)) * 1000,
        'formula_ejecutada', v_sql_formula,
        'parametros_usados', p_parametros,
        'origen_calculo', 'TIEMPO_REAL',
        'validacion_formula', 'OK',
        'rango_esperado', json_build_object(
            'min', v_kpi_config.rango_esperado_min,
            'max', v_kpi_config.rango_esperado_max,
            'dentro_rango', (
                v_valor_actual >= COALESCE(v_kpi_config.rango_esperado_min, v_valor_actual) AND
                v_valor_actual <= COALESCE(v_kpi_config.rango_esperado_max, v_valor_actual)
            )
        )
    );
    
    -- CALCULAR: Fecha de expiración del cache
    v_fecha_expiracion := NOW() + (v_kpi_config.duracion_cache_minutos || ' minutes')::INTERVAL;
    
    -- ALMACENAR: Resultado en cache
    INSERT INTO tab_valores_kpi_cache (
        id_kpi, parametros_hash, valor_actual, valor_anterior,
        porcentaje_cambio, tendencia, datos_extra, metadata_calculo,
        fecha_expiracion, numero_accesos
    ) VALUES (
        p_id_kpi, v_parametros_hash, v_valor_actual, v_valor_anterior,
        v_porcentaje_cambio, v_tendencia, v_datos_extra, v_metadata,
        v_fecha_expiracion, 1
    )
    ON CONFLICT (id_kpi, parametros_hash) 
    DO UPDATE SET 
        valor_actual = EXCLUDED.valor_actual,
        valor_anterior = EXCLUDED.valor_anterior,
        porcentaje_cambio = EXCLUDED.porcentaje_cambio,
        tendencia = EXCLUDED.tendencia,
        datos_extra = EXCLUDED.datos_extra,
        metadata_calculo = EXCLUDED.metadata_calculo,
        fecha_calculo = NOW(),
        fecha_expiracion = EXCLUDED.fecha_expiracion,
        numero_accesos = tab_valores_kpi_cache.numero_accesos + 1;
    
    -- ACTUALIZAR: Última actualización del KPI
    UPDATE tab_kpis_maestros 
    SET ultima_actualizacion = NOW()
    WHERE id_kpi = p_id_kpi;
    
    -- RETORNAR: Resultado completo
    RETURN json_build_object(
        'success', true,
        'origen', 'CALCULADO',
        'valor_actual', v_valor_actual,
        'valor_anterior', v_valor_anterior,
        'porcentaje_cambio', v_porcentaje_cambio,
        'tendencia', v_tendencia,
        'datos_extra', v_datos_extra,
        'metadata', v_metadata,
        'fecha_calculo', NOW(),
        'kpi_config', json_build_object(
            'id_kpi', v_kpi_config.id_kpi,
            'nombre', v_kpi_config.nom_kpi,
            'tipo', v_kpi_config.nom_tipo_kpi,
            'unidad_medida', v_kpi_config.unidad_medida,
            'formato_numero', v_kpi_config.formato_numero,
            'tipo_grafico', v_kpi_config.tipo_grafico_sugerido,
            'color_primario', v_kpi_config.color_primario
        )
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Error general calculando KPI: ' || SQLERRM,
            'sql_state', SQLSTATE,
            'id_kpi', p_id_kpi,
            'parametros', p_parametros,
            'tiempo_transcurrido', EXTRACT(EPOCH FROM (NOW() - v_inicio_calculo)) * 1000
        );
END;
$_$;


--
-- Name: fun_calcular_puntos_por_compra(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_calcular_puntos_por_compra(p_valor_compra numeric) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Variables para el cálculo
    v_pesos_por_punto DECIMAL(10,2);                   -- Configuración activa de pesos por punto
    puntos_ganados INT;                                 -- Puntos calculados a otorgar
BEGIN
    -- PASO 1: Obtener configuración activa de puntos de la empresa
    -- Buscar la configuración que esté activa y vigente
    SELECT pesos_por_punto INTO v_pesos_por_punto
    FROM tab_config_puntos_empresa
    WHERE ind_activo = TRUE
        AND fec_inicio_vigencia <= CURRENT_DATE
        AND (fec_fin_vigencia IS NULL OR fec_fin_vigencia >= CURRENT_DATE)
    ORDER BY fec_inicio_vigencia DESC
    LIMIT 1;
    
    -- VALIDACIÓN: Verificar que existe una configuración activa
    IF v_pesos_por_punto IS NULL THEN
        RAISE EXCEPTION 'No se encontró configuración activa de puntos para la empresa';
    END IF;
    
    -- PASO 2: Calcular puntos usando división entera (sin decimales)
    -- Fórmula: cantidad_puntos = valor_compra ÷ pesos_por_punto (redondeado hacia abajo)
    puntos_ganados := FLOOR(p_valor_compra / v_pesos_por_punto);
    
    -- PASO 3: Retornar cantidad de puntos ganados
    RETURN puntos_ganados;
END;
$$;


--
-- Name: fun_calcular_total_carrito(numeric, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_calcular_total_carrito(p_id_usuario numeric DEFAULT NULL::numeric, p_session_id character varying DEFAULT NULL::character varying, p_id_canje_aplicar integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $_$
DECLARE
    -- Variables principales del proceso
    v_id_carrito INT;                                           -- ID del carrito del usuario
    v_total_productos DECIMAL(10,2) := 0;                      -- Total de productos sin descuentos
    v_total_descuentos DECIMAL(10,2) := 0;                     -- Total de descuentos aplicados
    v_total_final DECIMAL(10,2);                               -- Total final a pagar
    v_descuentos_aplicados JSON := '[]'::JSON;                 -- Array de descuentos aplicados
    v_descuento RECORD;                                         -- Record para iterar descuentos
    v_es_primera_compra BOOLEAN;                                -- Indicador primera compra
    
    -- Variables para  lógica simplificada
    v_descuentos_automaticos JSON := '[]'::JSON;               -- Array de descuentos automáticos
    v_descuento_canjeado JSON;                                  -- Descuento canjeado por puntos
    v_total_desc_automaticos DECIMAL(10,2) := 0;               -- Total descuentos automáticos
    v_total_desc_canjeado DECIMAL(10,2) := 0;                  -- Total descuento canjeado
    v_canje_info RECORD;                                        -- Información del canje de puntos
    v_puntos_a_ganar INT;
    

BEGIN
    -- VALIDACIÓN: Al menos uno de los parámetros debe ser proporcionado
    IF p_id_usuario IS NULL AND p_session_id IS NULL THEN
        RAISE EXCEPTION 'Al menos uno de los parámetros (p_id_usuario o p_session_id) debe ser proporcionado';
    END IF;
    
    -- VALIDACIÓN: Solo usuarios registrados pueden comprar (y por tanto tener descuentos)
    -- Los usuarios anónimos solo pueden ver el carrito pero no pueden proceder al pago
    IF p_id_usuario IS NULL THEN
        -- Para usuarios anónimos, solo calcular total sin descuentos
        v_id_carrito := fun_obtener_carrito_usuario(p_id_usuario, p_session_id);
        
        -- Calcular total de productos sin descuentos
        SELECT COALESCE(SUM(cantidad * precio_unitario_carrito), 0) INTO v_total_productos
        FROM tab_carrito_productos
        WHERE id_carrito = v_id_carrito;
        
        -- Retornar resultado sin descuentos para usuarios anónimos
        RETURN json_build_object(
            'success', true,
            'total_final', v_total_productos,
            'total_productos', v_total_productos,
            'total_descuentos', 0,
            'ahorro_total', 0,
            'resumen', json_build_object(
                'subtotal', v_total_productos,
                'descuentos', 0,
                'total_a_pagar', v_total_productos,
                'ahorro_porcentaje', 0
            ),
            'descuentos_aplicados', NULL,
            'descuentos_automaticos', '[]'::JSON,
            'descuento_canjeado', NULL,
            'total_desc_automaticos', 0,
            'total_desc_canjeado', 0,
            'es_primera_compra', FALSE,
            'puntos_a_ganar', 0,
            'id_canje_aplicado', NULL,
            'mensaje', 'Regístrate para acceder a descuentos y puntos',
            'mensaje_puntos', 'Regístrate para acumular puntos',
            'mensaje_resumen', 'Total: $' || v_total_productos || ' (regístrate para descuentos)'
        );
    END IF;

    -- PASO 1: Obtener carrito del usuario
    -- Busca el carrito activo del usuario especificado (logueado o anónimo)
    v_id_carrito := fun_obtener_carrito_usuario(p_id_usuario, p_session_id);
    
    -- PASO 2: Calcular total de productos sin descuentos
    -- Suma cantidad × precio de todos los productos en el carrito
    -- COALESCE asegura que devuelva 0 si el carrito está vacío (SUM devolvería NULL)
    SELECT COALESCE(SUM(cantidad * precio_unitario_carrito), 0) INTO v_total_productos
    FROM tab_carrito_productos
    WHERE id_carrito = v_id_carrito;
    
    -- VALIDACIÓN: Si el carrito está vacío, retornar inmediatamente
    -- Evita procesar descuentos innecesariamente en carritos sin productos
    IF v_total_productos = 0 THEN
        RETURN json_build_object(
            'total_productos', 0,
            'total_descuentos', 0,
            'total_final', 0,
            'descuentos_aplicados', '[]'::JSON,
            'descuentos_automaticos', '[]'::JSON,
            'descuento_canjeado', NULL,
            'message', 'Carrito vacío'
        );
    END IF;
    
    -- PASO 3: Verificar si es primera compra del usuario
    -- NOT EXISTS verifica que NO exista ninguna orden previa del usuario
    -- Útil para aplicar descuentos de bienvenida a nuevos clientes
    -- Solo aplica para usuarios registrados
    IF p_id_usuario IS NOT NULL THEN
    SELECT NOT EXISTS (
        SELECT 1 FROM tab_ordenes WHERE id_usuario = p_id_usuario
    ) INTO v_es_primera_compra;
    ELSE
        v_es_primera_compra := FALSE; -- Usuarios anónimos no pueden tener "primera compra"
    END IF;
    
    -- PASO 4: Buscar y aplicar TODOS los descuentos automáticos disponibles y aplicables
    -- FOR LOOP itera sobre cada descuento automático que cumple las condiciones
    FOR v_descuento IN
        SELECT 
            d.id_descuento,
            d.nom_descuento,
            d.des_descuento,
            d.tipo_calculo,
            d.val_porce_descuento,
            d.val_monto_descuento,
            d.aplica_a,
            d.product_id_aplica,
            d.id_marca_aplica,
            d.min_valor_pedido,
            d.ind_es_para_cumpleanos,
            d.fec_inicio,
            d.fec_fin,
            d.ind_activo,
            d.max_usos_total,
            d.usos_actuales_total,
            d.costo_puntos_canje,
            d.ind_canjeable_puntos,
            d.codigo_descuento,
            d.max_usos_por_usuario,
            d.dias_semana_aplica,
            d.horas_inicio,
            d.horas_fin,
            d.solo_primera_compra,
            d.monto_minimo_producto,
            d.cantidad_minima_producto,
            d.requiere_codigo,
            d.usr_insert,
            d.fec_insert,
            d.usr_update,
            d.fec_update,
                CASE 
                    -- TIPO 1: Descuento por total del pedido (o 'todos' = aplicar al total)
                    -- Se aplica cuando el total del carrito cumple el mínimo requerido
                    WHEN d.aplica_a IN ('total_pedido', 'todos') AND v_total_productos >= COALESCE(d.min_valor_pedido, 0) THEN
                        CASE WHEN d.tipo_calculo THEN 
                           -- Descuento porcentual: calcula % sobre el total
                           v_total_productos * d.val_porce_descuento / 100
                        ELSE 
                            -- Descuento fijo: aplica monto fijo pero no puede ser mayor al total
                            LEAST(d.val_monto_descuento, v_total_productos)
                        END
                    WHEN d.aplica_a = 'producto_especifico' THEN
                        (SELECT COALESCE(SUM(
                            CASE WHEN d.tipo_calculo THEN (cp.cantidad * cp.precio_unitario_carrito * d.val_porce_descuento / 100)
                            ELSE LEAST(cp.cantidad, 1) * d.val_monto_descuento END
                        ), 0)
                        FROM tab_carrito_productos cp
                        JOIN tab_product_variant_combinations pv ON pv.id = cp.variant_id
                        JOIN tab_product_variant_groups g ON g.id = pv.group_id
                        JOIN tab_products p ON p.id = g.product_id
                        WHERE cp.id_carrito = v_id_carrito
                            AND p.id = d.product_id_aplica
                            AND cp.cantidad >= d.cantidad_minima_producto
                            AND (cp.cantidad * cp.precio_unitario_carrito) >= d.monto_minimo_producto)
                    WHEN d.aplica_a = 'categoria_especifica' THEN
                        (SELECT COALESCE(SUM(
                            CASE WHEN d.tipo_calculo THEN (cp.cantidad * cp.precio_unitario_carrito * d.val_porce_descuento / 100)
                            ELSE cp.cantidad * d.val_monto_descuento END
                        ), 0)
                        FROM tab_carrito_productos cp
                        JOIN tab_product_variant_combinations pv ON pv.id = cp.variant_id
                        JOIN tab_product_variant_groups g ON g.id = pv.group_id
                        JOIN tab_products p ON p.id = g.product_id
                        WHERE cp.id_carrito = v_id_carrito
                            AND p.category_id IN (
                                WITH RECURSIVE categorias_objetivo AS (
                                    SELECT id FROM tab_categories WHERE id = d.category_id_aplica
                                    UNION ALL
                                    SELECT c.id
                                    FROM tab_categories c
                                    JOIN categorias_objetivo co ON c.parent_id = co.id
                                )
                                SELECT id FROM categorias_objetivo
                            )
                            AND cp.cantidad >= d.cantidad_minima_producto
                            AND (cp.cantidad * cp.precio_unitario_carrito) >= d.monto_minimo_producto)
                    WHEN d.aplica_a = 'marca_especifica' THEN
                        (SELECT COALESCE(SUM(
                            CASE WHEN d.tipo_calculo THEN (cp.cantidad * cp.precio_unitario_carrito * d.val_porce_descuento / 100)
                            ELSE cp.cantidad * d.val_monto_descuento END
                        ), 0)
                        FROM tab_carrito_productos cp
                        JOIN tab_product_variant_combinations pv ON pv.id = cp.variant_id
                        JOIN tab_product_variant_groups g ON g.id = pv.group_id
                        JOIN tab_products p ON p.id = g.product_id AND p.is_active = TRUE
                        WHERE cp.id_carrito = v_id_carrito
                            AND p.id_marca = d.id_marca_aplica
                            AND cp.cantidad >= d.cantidad_minima_producto
                            AND (cp.cantidad * cp.precio_unitario_carrito) >= d.monto_minimo_producto)
                    -- Si no aplica ningún tipo, descuento = 0
                    ELSE 0
                END AS descuento_calculado
        FROM tab_descuentos d
        WHERE d.ind_activo = TRUE                                                    -- Solo descuentos activos
            AND (d.fec_inicio IS NULL OR d.fec_inicio <= CURRENT_DATE)               -- Fecha inicio: NULL = sin restricción
            AND (d.fec_fin IS NULL OR d.fec_fin >= CURRENT_DATE)                     -- Fecha fin: NULL = sin restricción (permite primera compra, cupón)
            AND d.ind_canjeable_puntos = FALSE                                      -- Solo descuentos automáticos (no canjeables)
            AND d.requiere_codigo = FALSE                                           -- Sin código requerido (automáticos)
            AND (d.codigo_descuento IS NULL OR d.codigo_descuento = '')            -- NO debe tener código definido (automáticos puros)
            -- Función que valida reglas adicionales del descuento
            -- Solo aplicar descuentos a usuarios registrados (los anónimos no pueden comprar)
            AND p_id_usuario IS NOT NULL 
            AND fun_validar_descuento_aplicable(d.id_descuento, p_id_usuario, NULL::VARCHAR, p_id_usuario) = TRUE
    LOOP
        -- PASO 5: Aplicar descuento automático si es aplicable
        -- Solo agrega descuentos que realmente tienen valor > 0
        IF v_descuento.descuento_calculado > 0 THEN
            -- Acumular al total de descuentos automáticos
            v_total_desc_automaticos := v_total_desc_automaticos + v_descuento.descuento_calculado;
            
            -- Agregar descuento automático al array
            -- Utiliza UNION ALL para combinar elementos existentes con el nuevo
            v_descuentos_automaticos := (
                SELECT json_agg(elemento)
                FROM (
                    -- Elementos ya existentes en el array
                    SELECT json_array_elements(v_descuentos_automaticos) AS elemento
                    UNION ALL
                    -- Nuevo elemento a agregar
                    SELECT json_build_object(
                        'id_descuento', v_descuento.id_descuento,
                        'nombre', v_descuento.nom_descuento,
                        -- Convierte tipo_calculo booleano a texto descriptivo
                        'tipo', CASE WHEN v_descuento.tipo_calculo THEN 'porcentaje' ELSE 'monto_fijo' END,
                        -- Muestra el valor original del descuento (% o monto)
                        'valor', CASE WHEN v_descuento.tipo_calculo THEN v_descuento.val_porce_descuento ELSE v_descuento.val_monto_descuento END,
                        -- Valor real aplicado en este carrito específico
                        'descuento_aplicado', v_descuento.descuento_calculado,
                        'aplica_a', v_descuento.aplica_a,
                        'tipo_descuento', 'automatico'
                    )
                ) AS subconsulta
            );
        END IF;
    END LOOP;

    -- PASO 6: Aplicar descuento canjeado por puntos (si se especifica)
    -- Solo procesa si el usuario pasó un ID de canje válido Y es un usuario registrado
    IF p_id_canje_aplicar IS NOT NULL AND p_id_usuario IS NOT NULL THEN
        -- Obtener información del canje y verificar que sea válido
        -- JOIN con descuentos para obtener toda la configuración necesaria
        SELECT 
            c.id_canje, c.id_usuario, c.id_descuento, c.puntos_utilizados,
            c.ind_utilizado, c.fec_expiracion_canje,
            d.nom_descuento, d.des_descuento, d.tipo_calculo,
            d.val_porce_descuento, d.val_monto_descuento, d.aplica_a,
            d.min_valor_pedido, d.cantidad_minima_producto, d.monto_minimo_producto,
            d.category_id_aplica, d.product_id_aplica, d.id_marca_aplica
        INTO v_canje_info
        FROM tab_canjes_puntos_descuentos c
        JOIN tab_descuentos d ON c.id_descuento = d.id_descuento
        WHERE c.id_canje = p_id_canje_aplicar
            -- Debe pertenecer al usuario que hace la consulta
            AND c.id_usuario = p_id_usuario
            -- No debe estar ya utilizado
            AND c.ind_utilizado = FALSE
            -- No debe estar expirado (si tiene fecha de expiración)
            AND (c.fec_expiracion_canje IS NULL OR c.fec_expiracion_canje >= CURRENT_DATE);

        -- Si el canje es válido, calcular el descuento
        -- FOUND es TRUE si la consulta anterior encontró registros
        IF FOUND THEN
            -- Calcular descuento usando la misma lógica que descuentos automáticos
            -- pero aplicando la configuración específica del canje
            SELECT 
                CASE 
                    -- TIPO 1: Descuento por total del pedido
                    WHEN v_canje_info.aplica_a = 'total_pedido' AND v_total_productos >= COALESCE(v_canje_info.min_valor_pedido, 0) THEN
                        CASE WHEN v_canje_info.tipo_calculo THEN 
                            -- Porcentual: sin límite máximo para canjes (ya pagaron puntos)
                           LEAST(v_total_productos * v_canje_info.val_porce_descuento / 100, v_total_productos)
                        ELSE 
                            -- Fijo: no puede exceder el total del carrito
                            LEAST(v_canje_info.val_monto_descuento, v_total_productos)
                        END
                    WHEN v_canje_info.aplica_a = 'producto_especifico' THEN
                        (SELECT COALESCE(SUM(
                            CASE WHEN v_canje_info.tipo_calculo THEN (cp.cantidad * cp.precio_unitario_carrito * v_canje_info.val_porce_descuento / 100)
                            ELSE LEAST(cp.cantidad, 1) * v_canje_info.val_monto_descuento END
                        ), 0)
                        FROM tab_carrito_productos cp
                        JOIN tab_product_variant_combinations pv ON pv.id = cp.variant_id
                        JOIN tab_product_variant_groups g ON g.id = pv.group_id
                        JOIN tab_products p ON p.id = g.product_id
                        WHERE cp.id_carrito = v_id_carrito
                            AND p.id = v_canje_info.product_id_aplica
                            AND cp.cantidad >= v_canje_info.cantidad_minima_producto
                            AND (cp.cantidad * cp.precio_unitario_carrito) >= v_canje_info.monto_minimo_producto)
                    WHEN v_canje_info.aplica_a = 'categoria_especifica' THEN
                        (SELECT COALESCE(SUM(
                            CASE WHEN v_canje_info.tipo_calculo THEN (cp.cantidad * cp.precio_unitario_carrito * v_canje_info.val_porce_descuento / 100)
                            ELSE cp.cantidad * v_canje_info.val_monto_descuento END
                        ), 0)
                        FROM tab_carrito_productos cp
                        JOIN tab_product_variant_combinations pv ON pv.id = cp.variant_id
                        JOIN tab_product_variant_groups g ON g.id = pv.group_id
                        JOIN tab_products p ON p.id = g.product_id
                        WHERE cp.id_carrito = v_id_carrito
                            AND p.category_id IN (
                                WITH RECURSIVE categorias_objetivo AS (
                                    SELECT id FROM tab_categories WHERE id = v_canje_info.category_id_aplica
                                    UNION ALL
                                    SELECT c.id
                                    FROM tab_categories c
                                    JOIN categorias_objetivo co ON c.parent_id = co.id
                                )
                                SELECT id FROM categorias_objetivo
                            )
                            AND cp.cantidad >= v_canje_info.cantidad_minima_producto
                            AND (cp.cantidad * cp.precio_unitario_carrito) >= v_canje_info.monto_minimo_producto)
                    WHEN v_canje_info.aplica_a = 'marca_especifica' THEN
                        (SELECT COALESCE(SUM(
                            CASE WHEN v_canje_info.tipo_calculo THEN (cp.cantidad * cp.precio_unitario_carrito * v_canje_info.val_porce_descuento / 100)
                            ELSE cp.cantidad * v_canje_info.val_monto_descuento END
                        ), 0)
                        FROM tab_carrito_productos cp
                        JOIN tab_product_variant_combinations pv ON pv.id = cp.variant_id
                        JOIN tab_product_variant_groups g ON g.id = pv.group_id
                        JOIN tab_products p ON p.id = g.product_id AND p.is_active = TRUE
                        WHERE cp.id_carrito = v_id_carrito
                            AND p.id_marca = v_canje_info.id_marca_aplica
                            AND cp.cantidad >= v_canje_info.cantidad_minima_producto
                            AND (cp.cantidad * cp.precio_unitario_carrito) >= v_canje_info.monto_minimo_producto)
                    WHEN v_canje_info.aplica_a IN ('linea_especifica', 'sublinea_especifica') THEN 0
                    ELSE 0
                END INTO v_total_desc_canjeado;

            -- Si el descuento canjeado es aplicable, agregarlo
            -- Solo construye el objeto JSON si realmente hay descuento
            IF v_total_desc_canjeado > 0 THEN
                v_descuento_canjeado := json_build_object(
                    'id_canje', v_canje_info.id_canje,
                    'id_descuento', v_canje_info.id_descuento,
                    'nombre', v_canje_info.nom_descuento,
                    -- Convierte tipo_calculo booleano a texto descriptivo
                    'tipo', CASE WHEN v_canje_info.tipo_calculo THEN 'porcentaje' ELSE 'monto_fijo' END,
                    -- Valor original configurado en el descuento
                    'valor', CASE WHEN v_canje_info.tipo_calculo THEN v_canje_info.val_porce_descuento ELSE v_canje_info.val_monto_descuento END,
                    -- Valor realmente aplicado en este carrito
                    'descuento_aplicado', v_total_desc_canjeado,
                    'aplica_a', v_canje_info.aplica_a,
                    -- Información adicional específica de canjes
                    'puntos_utilizados', v_canje_info.puntos_utilizados,
                    'tipo_descuento', 'canjeado'
                );
            END IF;
        END IF;
    END IF;

    -- PASO 7: Sumar todos los descuentos
    -- Combina descuentos automáticos y canjeados en un total único
    v_total_descuentos := v_total_desc_automaticos + v_total_desc_canjeado;
    
    -- Construir array combinado de descuentos aplicados
    -- Solo mostrar descuentos_aplicados cuando hay MIX de automáticos y canjeados
    IF v_total_desc_automaticos > 0 AND v_total_desc_canjeado > 0 THEN
        -- Combinar automáticos y canjeado (ambos tipos presentes)
        v_descuentos_aplicados := (
            SELECT json_agg(elemento)
            FROM (
                -- Todos los descuentos automáticos
                SELECT json_array_elements(v_descuentos_automaticos) AS elemento
                UNION ALL
                -- El descuento canjeado
                SELECT v_descuento_canjeado AS elemento
            ) AS combinados
        );
    ELSE
        -- Solo un tipo de descuento: no duplicar información
        v_descuentos_aplicados := NULL; -- No mostrar campo duplicado
    END IF;
    
    -- PASO 8: Validación final - el descuento nunca puede exceder el total de productos
    -- LEAST asegura que el descuento nunca haga el total negativo
    v_total_descuentos := LEAST(v_total_descuentos, v_total_productos);
    -- Calcula el monto final que debe pagar el cliente
    v_total_final := v_total_productos - v_total_descuentos;
    
    -- NUEVO: Calcular puntos que ganará por esta compra (solo usuarios registrados)
    -- IMPORTANTE: Los puntos se calculan sobre el valor ANTES de descuentos para incentivar las compras
    IF p_id_usuario IS NOT NULL THEN
        -- Intentar calcular puntos, pero manejar caso donde no hay configuración activa
        BEGIN
            v_puntos_a_ganar := fun_calcular_puntos_por_compra(v_total_productos);
        EXCEPTION
            WHEN OTHERS THEN
                -- Si no hay configuración de puntos activa, no generar puntos
                v_puntos_a_ganar := 0;
        END;
    ELSE
        v_puntos_a_ganar := 0; -- Usuarios anónimos no acumulan puntos
    END IF;
    
    -- PASO 9: Construir respuesta JSON con todos los resultados del cálculo
    -- Retorna estructura completa con toda la información del cálculo
    RETURN json_build_object(
        -- === TOTALES PRINCIPALES (información más importante primero) ===
        'success', true,
        'total_final', v_total_final,                               -- TOTAL A PAGAR (más prominente)
        'total_productos', v_total_productos,                       -- Subtotal de productos sin descuentos
        'total_descuentos', v_total_descuentos,                     -- Total de descuentos aplicados
        'ahorro_total', v_total_descuentos,                         -- Cuánto se ahorra (igual que total_descuentos)
        
        -- === RESUMEN DE TOTALES ===
        'resumen', json_build_object(
            'subtotal', v_total_productos,
            'descuentos', v_total_descuentos,
            'total_a_pagar', v_total_final,
            'ahorro_porcentaje', CASE 
                WHEN v_total_productos > 0 THEN ROUND((v_total_descuentos / v_total_productos) * 100, 2)
                ELSE 0 
            END
        ),
        
        -- === DETALLES DE DESCUENTOS ===
        'descuentos_aplicados', v_descuentos_aplicados,             -- Array detallado de todos los descuentos
        'descuentos_automaticos', v_descuentos_automaticos,         -- Array de descuentos automáticos de empresa
        'descuento_canjeado', v_descuento_canjeado,                 -- Descuento canjeado por puntos
        'total_desc_automaticos', v_total_desc_automaticos,         -- Total de descuentos automáticos
        'total_desc_canjeado', v_total_desc_canjeado,               -- Total de descuento canjeado
        
        -- === INFORMACIÓN DEL USUARIO ===
        'es_primera_compra', v_es_primera_compra,                   -- Indicador para descuentos de bienvenida
        'puntos_a_ganar', v_puntos_a_ganar,                        -- Puntos que ganará con esta compra
        'id_canje_aplicado', p_id_canje_aplicar,                    -- ID del canje aplicado (si aplica)
        
        -- === MENSAJES INFORMATIVOS ===
        'mensaje', CASE 
            WHEN v_total_descuentos > 0 THEN 
                CASE 
                    WHEN v_total_desc_automaticos > 0 AND v_total_desc_canjeado > 0 THEN 'Descuentos automáticos + descuento canjeado aplicados'
                    WHEN v_total_desc_automaticos > 0 THEN 'Descuentos automáticos aplicados'
                    ELSE 'Descuento canjeado aplicado'
                END
            ELSE 'Sin descuentos aplicables' 
        END,
        'mensaje_puntos', CASE 
            WHEN p_id_usuario IS NULL THEN 'Regístrate para acumular puntos'
            WHEN v_puntos_a_ganar > 0 THEN 'Ganarás ' || v_puntos_a_ganar || ' puntos con esta compra'
            ELSE 'Esta compra no genera puntos'
        END,
        'mensaje_resumen', 'Total a pagar: $' || v_total_final || 
            CASE 
                WHEN v_total_descuentos > 0 THEN ' (ahorraste $' || v_total_descuentos || ')'
                ELSE ' (sin descuentos)'
        END
    );
END;
$_$;


--
-- Name: fun_canjear_puntos_descuento(numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_canjear_puntos_descuento(p_id_usuario numeric, p_id_descuento numeric, p_usr_operacion numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_descuento RECORD;
    v_puntos_usuario INT;
    v_puntos_anteriores INT;
    v_puntos_nuevos INT;
    v_id_canje INT;
    
    -- Variables para aplicación automática al carrito
    v_id_carrito tab_carritos.id_carrito%TYPE;
    v_carrito_total DECIMAL(10,2);
    v_descuento_aplicado DECIMAL(10,2) := 0;
    v_total_final DECIMAL(10,2);
    v_aplicado_automaticamente BOOLEAN := FALSE;
    v_calculo_carrito JSON;
    v_total_canjes INT := 0;
    v_canjes_usuario INT := 0;
BEGIN
    -- PASO 1: Verificar que el descuento existe y es canjeable
    SELECT 
        d.id_descuento,
        d.nom_descuento,
        d.des_descuento,
        d.tipo_calculo,
        d.val_porce_descuento,
        d.val_monto_descuento,
        d.aplica_a,
        d.product_id_aplica,
        d.id_marca_aplica,
        d.min_valor_pedido,
        d.ind_es_para_cumpleanos,
        d.fec_inicio,
        d.fec_fin,
        d.ind_activo,
        d.max_usos_total,
        d.usos_actuales_total,
        d.costo_puntos_canje,
        d.ind_canjeable_puntos,
        d.codigo_descuento,
        d.max_usos_por_usuario,
        d.dias_semana_aplica,
        d.horas_inicio,
        d.horas_fin,
        d.solo_primera_compra,
        d.monto_minimo_producto,
        d.cantidad_minima_producto,
        d.requiere_codigo,
        d.usr_insert,
        d.fec_insert,
        d.usr_update,
        d.fec_update,
        CASE 
            WHEN (d.fec_inicio IS NULL AND d.fec_fin IS NULL) 
                 OR (d.fec_inicio IS NOT NULL AND d.fec_fin IS NOT NULL AND CURRENT_DATE BETWEEN d.fec_inicio AND d.fec_fin) 
            THEN TRUE 
            ELSE FALSE 
        END AS vigente
    INTO v_descuento
    FROM tab_descuentos d
    WHERE d.id_descuento = p_id_descuento;
    
    -- VALIDACIÓN 1: Existencia del descuento
    IF NOT FOUND THEN
        RETURN json_build_object('success', false, 'message', 'Descuento no encontrado');
    END IF;
    
    -- VALIDACIÓN 2: Verificar que es canjeable por puntos
    IF NOT v_descuento.ind_canjeable_puntos THEN
        RETURN json_build_object('success', false, 'message', 'Este descuento no es canjeable por puntos');
    END IF;
    
    -- VALIDACIÓN 3: Verificar vigencia para canje (fechas null = siempre; con fechas = current entre ellas)
    IF NOT v_descuento.vigente THEN
        RETURN json_build_object('success', false, 'message', 'El descuento no está vigente para canje');
    END IF;

    -- VALIDACIÓN 3b: Límite total de canjes del descuento.
    IF v_descuento.max_usos_total IS NOT NULL THEN
        SELECT COUNT(*) INTO v_total_canjes
        FROM tab_canjes_puntos_descuentos
        WHERE id_descuento = p_id_descuento;

        IF COALESCE(v_total_canjes, 0) >= v_descuento.max_usos_total THEN
            RETURN json_build_object('success', false, 'message', 'Este descuento alcanzó su límite máximo de canjes');
        END IF;
    END IF;

    -- VALIDACIÓN 3c: Límite de canjes por usuario.
    IF v_descuento.max_usos_por_usuario IS NOT NULL THEN
        SELECT COUNT(*) INTO v_canjes_usuario
        FROM tab_canjes_puntos_descuentos
        WHERE id_descuento = p_id_descuento
          AND id_usuario = p_id_usuario;

        IF COALESCE(v_canjes_usuario, 0) >= v_descuento.max_usos_por_usuario THEN
            RETURN json_build_object('success', false, 'message', 'Ya alcanzaste el límite de canjes para este descuento');
        END IF;
    END IF;

    -- PASO 2: Asegurar que el usuario tenga registro de puntos
    INSERT INTO tab_puntos_usuario (id_usuario, usr_insert)
    VALUES (p_id_usuario, p_usr_operacion)
    ON CONFLICT (id_usuario) DO NOTHING;
    
    -- PASO 3: Verificar puntos disponibles del usuario
    SELECT COALESCE(puntos_disponibles, 0) INTO v_puntos_usuario
    FROM tab_puntos_usuario
    WHERE id_usuario = p_id_usuario;
    
    -- VALIDACIÓN 4: Verificar puntos suficientes
    IF v_puntos_usuario < v_descuento.costo_puntos_canje THEN
        RETURN json_build_object(
            'success', false, 
            'message', 'Puntos insuficientes',
            'puntos_necesarios', v_descuento.costo_puntos_canje,
            'puntos_disponibles', v_puntos_usuario
        );
    END IF;
    
    -- PASO 4: Calcular nuevos totales de puntos
    v_puntos_anteriores := v_puntos_usuario;
    v_puntos_nuevos := v_puntos_anteriores - v_descuento.costo_puntos_canje;
    
    -- PASO 5: Actualizar puntos del usuario
    UPDATE tab_puntos_usuario
    SET puntos_disponibles = v_puntos_nuevos,
        puntos_totales_canjeados = puntos_totales_canjeados + v_descuento.costo_puntos_canje,
        fec_ultimo_canje = NOW(),
        usr_update = p_usr_operacion
    WHERE id_usuario = p_id_usuario;
    
    -- PASO 6: Registrar el canje (válido por 30 días)
    INSERT INTO tab_canjes_puntos_descuentos (
        id_usuario, id_descuento, puntos_utilizados,
        fec_expiracion_canje, usr_insert
    ) VALUES (
        p_id_usuario, p_id_descuento, v_descuento.costo_puntos_canje,
        CURRENT_DATE + INTERVAL '30 days', p_usr_operacion
    ) RETURNING id_canje INTO v_id_canje;
    
    -- PASO 7: Registrar movimiento de puntos para auditoría (tipo 2 = canje)
    INSERT INTO tab_movimientos_puntos (
        id_usuario, tipo_movimiento, cantidad_puntos,
        puntos_disponibles_anterior, puntos_disponibles_actual,
        id_descuento_canjeado, descripcion, usr_insert
    ) VALUES (
        p_id_usuario, 2, -v_descuento.costo_puntos_canje,
        v_puntos_anteriores, v_puntos_nuevos,
        p_id_descuento,
        CONCAT('Canje por descuento: ', v_descuento.nom_descuento),
        p_usr_operacion
    );
    
    -- PASO 8 NUEVO: Buscar carrito activo del usuario y verificar si aplica automáticamente
    SELECT c.id_carrito INTO v_id_carrito
    FROM tab_carritos c
    WHERE c.id_usuario = p_id_usuario
        AND EXISTS (
            SELECT 1 FROM tab_carrito_productos cp 
            WHERE cp.id_carrito = c.id_carrito
        )
    ORDER BY c.fec_update DESC
    LIMIT 1;
    
    -- Si el usuario tiene un carrito activo, verificar si el descuento aplica
    IF v_id_carrito IS NOT NULL THEN
        BEGIN
            -- Calcular total del carrito con el canje recién creado
            SELECT fun_calcular_total_carrito(
                p_id_usuario, 
                NULL, -- session_id 
                v_id_canje -- aplicar el canje recién creado
            ) INTO v_calculo_carrito;
            
            -- Extraer información del cálculo
            IF (v_calculo_carrito->>'success')::BOOLEAN = TRUE THEN
                v_carrito_total := (v_calculo_carrito->>'total_productos')::DECIMAL;
                v_total_final := (v_calculo_carrito->>'total_final')::DECIMAL;
                
                -- Verificar si el descuento se aplicó (buscar en descuentos aplicados)
                IF v_calculo_carrito->'descuentos_aplicados' IS NOT NULL AND 
                   json_array_length(v_calculo_carrito->'descuentos_aplicados') > 0 THEN
                    
                    -- Buscar si nuestro canje está en los descuentos aplicados
                    SELECT SUM((descuento->>'descuento_aplicado')::DECIMAL)
                    INTO v_descuento_aplicado
                    FROM json_array_elements(v_calculo_carrito->'descuentos_aplicados') AS descuento
                    WHERE (descuento->>'id_canje')::INT = v_id_canje;
                    
                    -- Si se aplicó el descuento, marcarlo como utilizado automáticamente
                    IF v_descuento_aplicado > 0 THEN
                        v_aplicado_automaticamente := TRUE;
                        
                        -- Marcar el canje como utilizado automáticamente en el carrito
                        UPDATE tab_canjes_puntos_descuentos
                        SET ind_utilizado = TRUE,
                            fec_utilizacion = NOW(),
                            usr_update = p_usr_operacion
                        WHERE id_canje = v_id_canje;
                    END IF;
                END IF;
            END IF;
        EXCEPTION 
            WHEN OTHERS THEN
                -- Si hay error en el cálculo del carrito, continuar sin aplicación automática
                v_aplicado_automaticamente := FALSE;
        END;
    END IF;
    
    -- RESPUESTA: Confirmar éxito del canje con información de aplicación automática
    RETURN json_build_object(
        'success', true,
        'message', CASE 
            WHEN v_aplicado_automaticamente THEN 
                'Descuento canjeado y aplicado automáticamente a tu carrito actual'
            ELSE 
                'Descuento canjeado exitosamente. Disponible para usar en tu próxima compra'
        END,
        'id_canje', v_id_canje,
        'descuento', v_descuento.nom_descuento,
        'puntos_utilizados', v_descuento.costo_puntos_canje,
        'puntos_restantes', v_puntos_nuevos,
        'aplicado_automaticamente', v_aplicado_automaticamente,
        'valor_descuento_aplicado', COALESCE(v_descuento_aplicado, 0),
        'total_carrito_anterior', COALESCE(v_carrito_total, 0),
        'total_carrito_final', COALESCE(v_total_final, 0),
        'id_carrito_aplicado', CASE WHEN v_aplicado_automaticamente THEN v_id_carrito ELSE NULL END
    );

-- MANEJO DE ERRORES: Capturar excepciones inesperadas
EXCEPTION 
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false, 
            'message', 'Error inesperado: ' || SQLERRM,
            'error_code', SQLSTATE
        );
END;
$$;


--
-- Name: fun_consumir_fifo(numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_consumir_fifo(p_variant_id numeric, p_cantidad integer) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_restante    INT := p_cantidad;
    v_costo_total DECIMAL(14, 2) := 0;
    v_take        INT;
    v_lote        RECORD;
BEGIN
    IF p_cantidad IS NULL OR p_cantidad <= 0 THEN
        RETURN 0;
    END IF;

    FOR v_lote IN
        SELECT id_lote, cantidad_restante, costo_unitario
        FROM tab_lotes_inventario
        WHERE variant_id = p_variant_id AND cantidad_restante > 0
        ORDER BY fec_entrada, id_lote
        FOR UPDATE
    LOOP
        EXIT WHEN v_restante <= 0;
        v_take := LEAST(v_lote.cantidad_restante, v_restante);

        UPDATE tab_lotes_inventario
        SET cantidad_restante = cantidad_restante - v_take
        WHERE id_lote = v_lote.id_lote;

        v_costo_total := v_costo_total + (v_take * v_lote.costo_unitario);
        v_restante := v_restante - v_take;
    END LOOP;

    IF v_restante > 0 THEN
        RAISE NOTICE 'FIFO: lotes insuficientes para variante % (faltan % uds); faltante costeado a 0.',
            p_variant_id, v_restante;
    END IF;

    RETURN v_costo_total;
END;
$$;


--
-- Name: fun_crear_config_puntos_empresa(numeric, character varying, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_crear_config_puntos_empresa(p_pesos_por_punto numeric, p_descripcion character varying, p_usr_operacion numeric) RETURNS json
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_config_existente INTEGER;
    v_nuevo_id INTEGER;
    v_descripcion_final VARCHAR;
BEGIN
    -- VALIDACIÓN 1: Verificar si ya existe una configuración activa
    SELECT COUNT(*) INTO v_config_existente 
    FROM tab_config_puntos_empresa 
    WHERE ind_activo = TRUE;
    
    IF v_config_existente > 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Ya existe una configuración activa. Use la función de actualización en su lugar.',
            'sugerencia', 'Ejecute fun_actualizar_config_puntos_empresa() para modificar la configuración existente'
        );
    END IF;
    
    -- VALIDACIÓN 2: Valor de pesos por punto debe ser positivo
    IF p_pesos_por_punto IS NULL OR p_pesos_por_punto <= 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El valor de pesos por punto es obligatorio y debe ser mayor a 0'
        );
    END IF;
    
    -- VALIDACIÓN 3: Usuario operación para auditoría
    IF p_usr_operacion IS NULL OR p_usr_operacion <= 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El usuario que realiza la operación es obligatorio para auditoría'
        );
    END IF;

    
    -- PREPARAR: Descripción final
    v_descripcion_final := COALESCE(
        p_descripcion, 
        'Configuración inicial: 1 punto por cada $' || p_pesos_por_punto::TEXT || ' pesos gastados'
    );
    
    -- INSERCIÓN: Crear nueva configuración activa
    INSERT INTO tab_config_puntos_empresa (
        pesos_por_punto,
        ind_activo,
        descripcion,
        fec_inicio_vigencia,
        fec_fin_vigencia,
        usr_insert
    ) VALUES (
        p_pesos_por_punto,          -- Valor pesos por punto
        TRUE,                       -- Configuración activa
        v_descripcion_final,        -- Descripción
        CURRENT_DATE,               -- Vigente desde hoy
        NULL,                       -- Sin fecha fin (indefinida)
        p_usr_operacion            -- Usuario que crea
    ) RETURNING id_config_puntos INTO v_nuevo_id;
    
    -- VERIFICACIÓN: Confirmar que se insertó correctamente
    IF v_nuevo_id IS NULL THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Error al crear la configuración de puntos'
        );
    END IF;
    
    -- RESPUESTA: Confirmar éxito con información de la configuración creada
    RETURN json_build_object(
        'success', true,
        'message', 'Configuración de puntos creada exitosamente',
        'config_id', v_nuevo_id,
        'valor_configurado', p_pesos_por_punto,
        'descripcion', v_descripcion_final,
        'fecha_vigencia', CURRENT_DATE
    );
    
-- MANEJO DE ERRORES: Capturar excepciones
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Error inesperado al crear configuración: ' || SQLERRM
        );
END;
$_$;


--
-- Name: fun_crear_dashboard(numeric, character varying, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_crear_dashboard(p_id_usuario numeric, p_nombre_dashboard character varying, p_descripcion text DEFAULT NULL::text, p_configuracion jsonb DEFAULT '{}'::jsonb, p_es_principal boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_nuevo_dashboard_id INT;
    v_usuario_existe BOOLEAN;
    v_dashboard_existe BOOLEAN;
BEGIN
    -- VERIFICAR: Usuario existe y está activo
    SELECT EXISTS(
        SELECT 1 FROM tab_usuarios 
        WHERE id_usuario = p_id_usuario AND ind_activo = TRUE
    ) INTO v_usuario_existe;
    
    IF NOT v_usuario_existe THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Usuario no encontrado o inactivo',
            'id_usuario', p_id_usuario
        );
    END IF;
    
    -- VERIFICAR: Nombre único para el usuario
    SELECT EXISTS(
        SELECT 1 FROM tab_dashboards_usuarios 
        WHERE id_usuario = p_id_usuario 
          AND nom_dashboard = p_nombre_dashboard
          AND ind_activo = TRUE
    ) INTO v_dashboard_existe;
    
    IF v_dashboard_existe THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Ya existe un dashboard con ese nombre para el usuario',
            'nombre_dashboard', p_nombre_dashboard
        );
    END IF;
    
    -- Si es principal, desmarcar otros dashboards principales
    IF p_es_principal THEN
        UPDATE tab_dashboards_usuarios 
        SET es_dashboard_principal = FALSE,
            fec_update = NOW()
        WHERE id_usuario = p_id_usuario;
    END IF;
    
    -- CREAR: Nuevo dashboard
    INSERT INTO tab_dashboards_usuarios (
        id_usuario, nom_dashboard, descripcion, 
        tipo_layout, columnas_grid, tema_color, mostrar_filtros,
        es_publico, es_dashboard_principal, auto_refresh_segundos,
        notificaciones_cambios, fecha_ultimo_acceso, numero_accesos
    ) VALUES (
        p_id_usuario, p_nombre_dashboard, p_descripcion,
        COALESCE(p_configuracion->>'tipo_layout', 'GRID'),
        COALESCE((p_configuracion->>'columnas_grid')::INT, 3),
        COALESCE(p_configuracion->>'tema_color', 'DEFAULT'),
        COALESCE((p_configuracion->>'mostrar_filtros')::BOOLEAN, TRUE),
        COALESCE((p_configuracion->>'es_publico')::BOOLEAN, FALSE),
        p_es_principal,
        COALESCE((p_configuracion->>'auto_refresh_segundos')::INT, 300),
        COALESCE((p_configuracion->>'notificaciones_cambios')::BOOLEAN, FALSE),
        NOW(), 1
    ) RETURNING id_dashboard INTO v_nuevo_dashboard_id;
    
    -- RESPUESTA: Dashboard creado exitosamente
    RETURN json_build_object(
        'success', true,
        'id_dashboard', v_nuevo_dashboard_id,
        'nombre_dashboard', p_nombre_dashboard,
        'es_principal', p_es_principal,
        'configuracion_aplicada', p_configuracion,
        'fecha_creacion', NOW()
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Error creando dashboard: ' || SQLERRM,
            'sql_state', SQLSTATE
        );
END;
$$;


--
-- Name: fun_crear_orden_desde_carrito(integer, numeric, character varying, character varying, numeric, integer, numeric, character varying, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_crear_orden_desde_carrito(p_id_carrito integer, p_id_direccion numeric, p_codigo_descuento character varying, p_observaciones character varying, p_usr_operacion numeric, p_id_canje integer DEFAULT NULL::integer, p_ind_estado numeric DEFAULT NULL::numeric, p_metodo_pago character varying DEFAULT NULL::character varying, p_costo_envio numeric DEFAULT 0) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Variables principales del proceso
    v_carrito_info RECORD;                                   -- Información del carrito
    v_id_usuario tab_usuarios.id_usuario%TYPE;               -- ID del usuario del carrito
    v_session_id tab_carritos.session_id%TYPE;               -- Session ID para usuarios anónimos
    v_total_productos DECIMAL(10,2) := 0;                    -- Total de productos sin descuentos
    v_total_descuentos DECIMAL(10,2) := 0;                   -- Total de descuentos aplicados
    v_total_final DECIMAL(10,2);                             -- Total final de la orden
    v_costo_envio DECIMAL(10,2) := 0;                        -- Costo envío (COP)
    v_id_orden tab_ordenes.id_orden%TYPE;                    -- ID de la orden generada
    v_producto_record RECORD;                                -- Record para iterar productos
    v_direccion_valida BOOLEAN := FALSE;                     -- Validar dirección
    v_count_productos INT := 0;                              -- Contador de productos en carrito
    
    -- Variables para manejo de descuentos
    v_descuentos_automaticos JSON := '[]'::JSON;             -- Descuentos automáticos
    v_descuento_codigo JSON;                                 -- Descuento por código
    v_descuento_canje JSON;                                  -- Descuento por canje de puntos
    v_descuentos_aplicados JSON := '[]'::JSON;               -- Todos los descuentos aplicados
    v_descuento RECORD;                                       -- Record para iterar descuentos
    v_descuento_auto RECORD;                                 -- Record para iterar descuentos automáticos en registro de usos
    v_canje_info RECORD;                                     -- Información del canje
    v_es_primera_compra BOOLEAN := FALSE;                    -- Indicador primera compra
    v_descuento_canje_valor DECIMAL(10,2) := 0;               -- Descuento calculado por canje (PASO 7.5)

BEGIN
    -- PASO 1: Validar que el carrito existe y obtener información
    SELECT c.id_carrito, c.id_usuario, c.session_id
    INTO v_carrito_info
    FROM tab_carritos c
    WHERE c.id_carrito = p_id_carrito;
    
    -- Verificar que el carrito existe
    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false, 
            'message', 'El carrito especificado no existe',
            'id_carrito', p_id_carrito
        );
    END IF;
    
    -- Extraer datos del carrito
    v_id_usuario := v_carrito_info.id_usuario;
    v_session_id := v_carrito_info.session_id;
    
    -- PASO 2: Verificar que el carrito tenga productos
    SELECT COUNT(1), COALESCE(SUM(cp.cantidad * cp.precio_unitario_carrito), 0)----
    INTO v_count_productos, v_total_productos
    FROM tab_carrito_productos cp
    WHERE cp.id_carrito = p_id_carrito;
    
    -- Validar que el carrito no esté vacío
    IF v_count_productos = 0 OR v_total_productos = 0 THEN
        RETURN json_build_object(
            'success', false, 
            'message', 'El carrito está vacío',
            'id_carrito', p_id_carrito
        );
    END IF;
    
    -- PASO 3: Validar dirección de entrega (solo para usuarios registrados)
    IF v_id_usuario IS NOT NULL THEN
        SELECT EXISTS(
            SELECT 1 
            FROM tab_direcciones_usuario 
            WHERE id_direccion = p_id_direccion
            AND id_usuario = v_id_usuario
            AND ind_activa = TRUE
        ) INTO v_direccion_valida;
        
        IF NOT v_direccion_valida THEN
            RETURN json_build_object(
                'success', false, 
                'message', 'La dirección especificada no existe o no pertenece al usuario',
                'id_direccion', p_id_direccion
            );
        END IF;
    END IF;
    
    -- PASO 4: Verificar stock disponible (variantes)
    FOR v_producto_record IN 
        SELECT cp.variant_id, cp.cantidad, cp.precio_unitario_carrito, pv.stock, p.name AS nom_producto
        FROM tab_carrito_productos cp
        JOIN tab_product_variant_combinations pv ON pv.id = cp.variant_id AND pv.is_active = TRUE
        JOIN tab_product_variant_groups g ON g.id = pv.group_id
        JOIN tab_products p ON p.id = g.product_id AND p.is_active = TRUE
        WHERE cp.id_carrito = p_id_carrito
    LOOP
        IF v_producto_record.cantidad > v_producto_record.stock THEN
            RETURN json_build_object(
                'success', false, 
                'message', 'Stock insuficiente para: ' || v_producto_record.nom_producto,
                'producto_sin_stock', v_producto_record.nom_producto,
                'stock_disponible', v_producto_record.stock,
                'cantidad_solicitada', v_producto_record.cantidad
            );
        END IF;
    END LOOP;
    
    -- PASO 5: Verificar si es primera compra (solo usuarios registrados)
    IF v_id_usuario IS NOT NULL THEN
        SELECT NOT EXISTS (
            SELECT 1 FROM tab_ordenes WHERE id_usuario = v_id_usuario
        ) INTO v_es_primera_compra;
    END IF;
    
    -- PASO 6: Calcular descuentos automáticos (misma lógica que fun_calcular_total_carrito,
    -- usando el nuevo esquema de descuentos basado en categorías/productos modernos)
    FOR v_descuento IN
        SELECT 
            d.id_descuento,
            d.nom_descuento,
            d.des_descuento,
            d.tipo_calculo,
            d.val_porce_descuento,
            d.val_monto_descuento,
            d.aplica_a,
            d.product_id_aplica,
            d.id_marca_aplica,
            d.min_valor_pedido,
            d.ind_es_para_cumpleanos,
            d.fec_inicio,
            d.fec_fin,
            d.ind_activo,
            d.max_usos_total,
            d.usos_actuales_total,
            d.costo_puntos_canje,
            d.ind_canjeable_puntos,
            d.codigo_descuento,
            d.max_usos_por_usuario,
            d.dias_semana_aplica,
            d.horas_inicio,
            d.horas_fin,
            d.solo_primera_compra,
            d.monto_minimo_producto,
            d.cantidad_minima_producto,
            d.requiere_codigo,
            d.usr_insert,
            d.fec_insert,
            d.usr_update,
            d.fec_update,
                CASE 
                    WHEN d.aplica_a IN ('total_pedido', 'todos') AND v_total_productos >= COALESCE(d.min_valor_pedido, 0) THEN
                        CASE WHEN d.tipo_calculo THEN
                           v_total_productos * d.val_porce_descuento / 100
                        ELSE
                            LEAST(d.val_monto_descuento, v_total_productos)
                        END
                    WHEN d.aplica_a = 'producto_especifico' THEN
                        (SELECT COALESCE(SUM(
                            CASE WHEN d.tipo_calculo THEN 
                               (cp.cantidad * cp.precio_unitario_carrito * d.val_porce_descuento / 100)
                            ELSE 
                               LEAST(cp.cantidad, 1) * d.val_monto_descuento
                            END
                        ), 0)
                        FROM tab_carrito_productos cp
                        JOIN tab_product_variant_combinations pv ON pv.id = cp.variant_id
                        JOIN tab_product_variant_groups g ON g.id = pv.group_id
                        JOIN tab_products p ON p.id = g.product_id
                        WHERE cp.id_carrito = p_id_carrito
                            AND p.id = d.product_id_aplica
                            AND cp.cantidad >= d.cantidad_minima_producto
                            AND (cp.cantidad * cp.precio_unitario_carrito) >= d.monto_minimo_producto)
                    WHEN d.aplica_a = 'categoria_especifica' THEN
                        (SELECT COALESCE(SUM(
                            CASE WHEN d.tipo_calculo THEN 
                               (cp.cantidad * cp.precio_unitario_carrito * d.val_porce_descuento / 100)
                            ELSE 
                               cp.cantidad * d.val_monto_descuento
                            END
                        ), 0)
                        FROM tab_carrito_productos cp
                        JOIN tab_product_variant_combinations pv ON pv.id = cp.variant_id
                        JOIN tab_product_variant_groups g ON g.id = pv.group_id
                        JOIN tab_products p ON p.id = g.product_id
                        WHERE cp.id_carrito = p_id_carrito
                            AND p.category_id IN (
                                WITH RECURSIVE categorias_objetivo AS (
                                    SELECT id FROM tab_categories WHERE id = d.category_id_aplica
                                    UNION ALL
                                    SELECT c.id
                                    FROM tab_categories c
                                    JOIN categorias_objetivo co ON c.parent_id = co.id
                                )
                                SELECT id FROM categorias_objetivo
                            )
                            AND cp.cantidad >= d.cantidad_minima_producto
                            AND (cp.cantidad * cp.precio_unitario_carrito) >= d.monto_minimo_producto)
                    WHEN d.aplica_a = 'marca_especifica' THEN
                        (SELECT COALESCE(SUM(
                            CASE WHEN d.tipo_calculo THEN 
                               (cp.cantidad * cp.precio_unitario_carrito * d.val_porce_descuento / 100)
                            ELSE 
                               cp.cantidad * d.val_monto_descuento
                            END
                        ), 0)
                        FROM tab_carrito_productos cp
                        JOIN tab_product_variant_combinations pv ON pv.id = cp.variant_id
                        JOIN tab_product_variant_groups g ON g.id = pv.group_id
                        JOIN tab_products p ON p.id = g.product_id AND p.is_active = TRUE
                        WHERE cp.id_carrito = p_id_carrito
                            AND p.id_marca = d.id_marca_aplica
                            AND cp.cantidad >= d.cantidad_minima_producto
                            AND (cp.cantidad * cp.precio_unitario_carrito) >= d.monto_minimo_producto)
                    ELSE 0
                END AS descuento_calculado
        FROM tab_descuentos d
        WHERE d.ind_activo = TRUE
            AND (d.fec_inicio IS NULL OR d.fec_inicio <= CURRENT_DATE)
            AND (d.fec_fin IS NULL OR d.fec_fin >= CURRENT_DATE)
            AND d.ind_canjeable_puntos = FALSE
            AND d.requiere_codigo = FALSE
            AND (d.codigo_descuento IS NULL OR d.codigo_descuento = '')
            -- Usar función completa de validación para descuentos automáticos (incluye solo_primera_compra)
            AND v_id_usuario IS NOT NULL
            AND fun_validar_descuento_aplicable(d.id_descuento, v_id_usuario, NULL::VARCHAR, p_usr_operacion) = TRUE
    LOOP
        -- Aplicar descuento automático si es aplicable
        IF v_descuento.descuento_calculado > 0 THEN
            v_total_descuentos := v_total_descuentos + v_descuento.descuento_calculado;
            
            -- Agregar a array de descuentos automáticos
            v_descuentos_automaticos := (
                SELECT json_agg(elemento)
                FROM (
                    SELECT json_array_elements(v_descuentos_automaticos) AS elemento
                    UNION ALL
                    SELECT json_build_object(
                        'id_descuento', v_descuento.id_descuento,
                        'nombre', v_descuento.nom_descuento,
                        'tipo', CASE WHEN v_descuento.tipo_calculo THEN 'porcentaje' ELSE 'monto_fijo' END,
                        'valor', CASE WHEN v_descuento.tipo_calculo THEN v_descuento.val_porce_descuento ELSE v_descuento.val_monto_descuento END,
                        'descuento_aplicado', v_descuento.descuento_calculado,
                        'aplica_a', v_descuento.aplica_a,
                        'tipo_descuento', 'automatico'
                    )
                ) AS subconsulta
            );
        END IF;
    END LOOP;
    
    -- PASO 7: Aplicar código de descuento (si se especifica)
    IF p_codigo_descuento IS NOT NULL THEN
        -- Buscar descuento por código (mismas columnas relevantes que en descuentos automáticos)
        SELECT 
            d.id_descuento,
            d.nom_descuento,
            d.des_descuento,
            d.tipo_calculo,
            d.val_porce_descuento,
            d.val_monto_descuento,
            d.aplica_a,
            d.product_id_aplica,
            d.id_marca_aplica,
            d.min_valor_pedido,
            d.ind_es_para_cumpleanos,
            d.fec_inicio,
            d.fec_fin,
            d.ind_activo,
            d.max_usos_total,
            d.usos_actuales_total,
            d.costo_puntos_canje,
            d.ind_canjeable_puntos,
            d.codigo_descuento,
            d.max_usos_por_usuario,
            d.dias_semana_aplica,
            d.horas_inicio,
            d.horas_fin,
            d.solo_primera_compra,
            d.monto_minimo_producto,
            d.cantidad_minima_producto,
            d.requiere_codigo,
            d.usr_insert,
            d.fec_insert,
            d.usr_update,
            d.fec_update,
                CASE 
                    WHEN d.aplica_a = 'total_pedido' AND v_total_productos >= d.min_valor_pedido THEN
                        CASE WHEN d.tipo_calculo THEN 
                           v_total_productos * d.val_porce_descuento / 100
                        ELSE 
                            LEAST(d.val_monto_descuento, v_total_productos)
                        END
                    ELSE 0
                END AS descuento_calculado
        INTO v_descuento
        FROM tab_descuentos d
        WHERE UPPER(TRIM(d.codigo_descuento)) = UPPER(TRIM(p_codigo_descuento))
            AND d.ind_activo = TRUE
            AND CURRENT_DATE BETWEEN d.fec_inicio AND d.fec_fin
            AND (d.requiere_codigo = TRUE OR d.codigo_descuento IS NOT NULL);
        
        -- Si se encontró el código, validar que sea aplicable al usuario
        IF FOUND AND v_descuento.descuento_calculado > 0 THEN
            -- VALIDACIÓN ESPECIAL: Para descuentos de solo_primera_compra, verificar antes de que exista la orden
            IF v_descuento.solo_primera_compra = TRUE THEN
                -- Para primera compra, validar manualmente sin depender de la función que verifica órdenes existentes
                IF v_es_primera_compra = FALSE THEN
                    -- El usuario ya no es primera compra, no puede usar este código
                    RETURN json_build_object(
                        'success', false,
                        'message', 'El código "' || p_codigo_descuento || '" solo es válido para la primera compra y usted ya ha realizado compras anteriormente',
                        'error_tipo', 'codigo_descuento_primera_compra',
                        'codigo_rechazado', p_codigo_descuento
                    );
                END IF;
            ELSE
                -- Para otros tipos de descuentos, usar la función completa de validación
                IF NOT fun_validar_descuento_aplicable(v_descuento.id_descuento, v_id_usuario, p_codigo_descuento, p_usr_operacion) THEN
                    RETURN json_build_object(
                        'success', false,
                        'message', 'El código "' || p_codigo_descuento || '" no es aplicable en este momento',
                        'error_tipo', 'codigo_descuento_no_aplicable',
                        'codigo_rechazado', p_codigo_descuento
                    );
                END IF;
            END IF;
            
            -- Si llegó hasta aquí, el descuento es válido y aplicable
            v_total_descuentos := v_total_descuentos + v_descuento.descuento_calculado;
            
            -- Crear objeto de descuento por código
            v_descuento_codigo := json_build_object(
                'id_descuento', v_descuento.id_descuento,
                'nombre', v_descuento.nom_descuento,
                'codigo', p_codigo_descuento,
                'tipo', CASE WHEN v_descuento.tipo_calculo THEN 'porcentaje' ELSE 'monto_fijo' END,
                'valor', CASE WHEN v_descuento.tipo_calculo THEN v_descuento.val_porce_descuento ELSE v_descuento.val_monto_descuento END,
                'descuento_aplicado', v_descuento.descuento_calculado,
                'tipo_descuento', 'codigo'
            );
        ELSE
            -- Código no encontrado o no aplicable
            RETURN json_build_object(
                'success', false,
                'message', 'El código de descuento "' || p_codigo_descuento || '" no es válido o no aplica a este pedido',
                'error_tipo', 'codigo_descuento_invalido',
                'codigo_rechazado', p_codigo_descuento
            );
        END IF;
    END IF;
    
    -- PASO 7.5: Aplicar descuento canjeado por puntos (si se especifica)
    -- Misma lógica que fun_calcular_total_carrito para todos los aplica_a (total_pedido, categoria_especifica, etc.)
    IF p_id_canje IS NOT NULL AND v_id_usuario IS NOT NULL THEN
        -- Obtener información del canje y del descuento (mismas columnas que fun_calcular_total_carrito)
        SELECT 
            c.id_canje, c.id_usuario, c.id_descuento, c.puntos_utilizados,
            c.ind_utilizado, c.fec_expiracion_canje,
            d.nom_descuento, d.des_descuento, d.tipo_calculo,
            d.val_porce_descuento, d.val_monto_descuento, d.aplica_a,
            d.min_valor_pedido, d.cantidad_minima_producto, d.monto_minimo_producto,
            d.category_id_aplica, d.product_id_aplica, d.id_marca_aplica
        INTO v_canje_info
        FROM tab_canjes_puntos_descuentos c
        JOIN tab_descuentos d ON c.id_descuento = d.id_descuento
        WHERE c.id_canje = p_id_canje
            AND c.id_usuario = v_id_usuario
            AND c.ind_utilizado = FALSE
            AND (c.fec_expiracion_canje IS NULL OR c.fec_expiracion_canje >= CURRENT_DATE);

        -- Si el canje es válido, calcular descuento con la misma regla que el carrito
        IF FOUND THEN
            v_descuento_canje_valor := 0;
            -- Calcular valor del descuento canjeado (todos los aplica_a como en fun_calcular_total_carrito)
            SELECT
                    CASE
                        WHEN v_canje_info.aplica_a = 'total_pedido' AND v_total_productos >= COALESCE(v_canje_info.min_valor_pedido, 0) THEN
                            CASE WHEN v_canje_info.tipo_calculo THEN
                                LEAST(v_total_productos * v_canje_info.val_porce_descuento / 100, v_total_productos)
                            ELSE
                                LEAST(v_canje_info.val_monto_descuento, v_total_productos)
                            END
                        WHEN v_canje_info.aplica_a = 'producto_especifico' THEN
                            (SELECT COALESCE(SUM(
                                CASE WHEN v_canje_info.tipo_calculo THEN
                                    (cp.cantidad * cp.precio_unitario_carrito * v_canje_info.val_porce_descuento / 100)
                                ELSE
                                    LEAST(cp.cantidad, 1) * v_canje_info.val_monto_descuento
                                END
                            ), 0)
                            FROM tab_carrito_productos cp
                            JOIN tab_product_variant_combinations pv ON pv.id = cp.variant_id
                            JOIN tab_product_variant_groups g ON g.id = pv.group_id
                            JOIN tab_products p ON p.id = g.product_id
                            WHERE cp.id_carrito = p_id_carrito
                                AND p.id = v_canje_info.product_id_aplica
                                AND cp.cantidad >= COALESCE(v_canje_info.cantidad_minima_producto, 0)
                                AND (cp.cantidad * cp.precio_unitario_carrito) >= COALESCE(v_canje_info.monto_minimo_producto, 0))
                        WHEN v_canje_info.aplica_a = 'categoria_especifica' THEN
                            (SELECT COALESCE(SUM(
                                CASE WHEN v_canje_info.tipo_calculo THEN
                                    (cp.cantidad * cp.precio_unitario_carrito * v_canje_info.val_porce_descuento / 100)
                                ELSE
                                    cp.cantidad * v_canje_info.val_monto_descuento
                                END
                            ), 0)
                            FROM tab_carrito_productos cp
                            JOIN tab_product_variant_combinations pv ON pv.id = cp.variant_id
                            JOIN tab_product_variant_groups g ON g.id = pv.group_id
                            JOIN tab_products p ON p.id = g.product_id
                            WHERE cp.id_carrito = p_id_carrito
                                AND p.category_id IN (
                                    WITH RECURSIVE categorias_objetivo AS (
                                        SELECT id FROM tab_categories WHERE id = v_canje_info.category_id_aplica
                                        UNION ALL
                                        SELECT c.id
                                        FROM tab_categories c
                                        JOIN categorias_objetivo co ON c.parent_id = co.id
                                    )
                                    SELECT id FROM categorias_objetivo
                                )
                                AND cp.cantidad >= COALESCE(v_canje_info.cantidad_minima_producto, 0)
                                AND (cp.cantidad * cp.precio_unitario_carrito) >= COALESCE(v_canje_info.monto_minimo_producto, 0))
                        WHEN v_canje_info.aplica_a = 'marca_especifica' THEN
                            (SELECT COALESCE(SUM(
                                CASE WHEN v_canje_info.tipo_calculo THEN
                                    (cp.cantidad * cp.precio_unitario_carrito * v_canje_info.val_porce_descuento / 100)
                                ELSE
                                    cp.cantidad * v_canje_info.val_monto_descuento
                                END
                            ), 0)
                            FROM tab_carrito_productos cp
                            JOIN tab_product_variant_combinations pv ON pv.id = cp.variant_id
                            JOIN tab_product_variant_groups g ON g.id = pv.group_id
                            JOIN tab_products p ON p.id = g.product_id AND p.is_active = TRUE
                            WHERE cp.id_carrito = p_id_carrito
                                AND p.id_marca = v_canje_info.id_marca_aplica
                                AND cp.cantidad >= COALESCE(v_canje_info.cantidad_minima_producto, 0)
                                AND (cp.cantidad * cp.precio_unitario_carrito) >= COALESCE(v_canje_info.monto_minimo_producto, 0))
                        WHEN v_canje_info.aplica_a IN ('linea_especifica', 'sublinea_especifica') THEN
                            0
                        ELSE 0
                    END
            INTO v_descuento_canje_valor;

            -- Aplicar el descuento si es mayor a 0
            IF v_descuento_canje_valor > 0 THEN
                v_total_descuentos := v_total_descuentos + v_descuento_canje_valor;

                v_descuento_canje := json_build_object(
                    'id_descuento', v_canje_info.id_descuento,
                    'id_canje', v_canje_info.id_canje,
                    'nombre', v_canje_info.nom_descuento,
                    'tipo', CASE WHEN v_canje_info.tipo_calculo THEN 'porcentaje' ELSE 'monto_fijo' END,
                    'valor', CASE WHEN v_canje_info.tipo_calculo THEN v_canje_info.val_porce_descuento ELSE v_canje_info.val_monto_descuento END,
                    'descuento_aplicado', v_descuento_canje_valor,
                    'puntos_utilizados', v_canje_info.puntos_utilizados,
                    'tipo_descuento', 'canje_puntos'
                );
            END IF;
        ELSE
            RETURN json_build_object(
                'success', false,
                'message', 'El canje especificado no es válido o ya fue utilizado',
                'error_tipo', 'canje_no_valido',
                'id_canje', p_id_canje
            );
        END IF;
    END IF;
    
    -- PASO 8: Calcular total final (productos - descuentos + envío)
    v_total_descuentos := LEAST(v_total_descuentos, v_total_productos);
    v_costo_envio := GREATEST(COALESCE(p_costo_envio, 0), 0);
    v_total_final := v_total_productos - v_total_descuentos + v_costo_envio;
    
    -- Construir array completo de descuentos aplicados
    v_descuentos_aplicados := (
        SELECT json_agg(elemento)
        FROM (
            -- Descuentos automáticos
            SELECT json_array_elements(v_descuentos_automaticos) AS elemento
            UNION ALL
            -- Descuento por código
            SELECT v_descuento_codigo AS elemento
            WHERE v_descuento_codigo IS NOT NULL
            UNION ALL
            -- Descuento por canje de puntos
            SELECT v_descuento_canje AS elemento
            WHERE v_descuento_canje IS NOT NULL
        ) AS combinados
    );
    
    -- PASO 9: Siempre crear una nueva orden (no actualizar órdenes existentes)
    -- Esto evita sobreescribir órdenes anteriores del usuario
    -- PASO 10: Generar nuevo ID de orden
            SELECT COALESCE(MAX(id_orden), 0) + 1 INTO v_id_orden FROM tab_ordenes;
            
    -- PASO 11: Crear la orden principal (ind_estado y metodo_pago opcionales: cuando pago ya aprobado)
    -- Nota: trg_limpiar_carrito_pagado está definido solo para UPDATE; si la orden se crea ya como
    -- Pagada (INSERT ind_estado=2), la limpieza del carrito se hace en PASO 12b más abajo.
        INSERT INTO tab_ordenes (
            id_orden, id_usuario, val_total_productos, val_total_descuentos,
            val_costo_envio,
            val_total_pedido, ind_estado, metodo_pago, des_observaciones,
                detalle_descuentos_aplicados, usr_insert
        ) VALUES (
            v_id_orden, 
                v_id_usuario,
            v_total_productos,
            v_total_descuentos,
            v_costo_envio,
            v_total_final, 
            COALESCE(p_ind_estado, 1),  -- 1=Pendiente por defecto; 2=Pagada cuando pago ya aprobado
            p_metodo_pago,  -- NULL por defecto; 'tarjeta'/'transferencia'/etc cuando pago aprobado
            p_observaciones,
                v_descuentos_aplicados,
            p_usr_operacion
        );
        
    -- PASO 12: Transferir productos del carrito a la orden (variant_id + opciones_elegidas)
        FOR v_producto_record IN 
            SELECT id_carrito_producto, variant_id, cantidad, precio_unitario_carrito,
                   COALESCE(opciones_elegidas, '{}'::JSONB) AS opciones_elegidas
            FROM tab_carrito_productos WHERE id_carrito = p_id_carrito
        LOOP
            INSERT INTO tab_orden_productos (
                id_orden_producto,
                id_orden,
                variant_id,
                cant_producto,
                precio_unitario_orden,
                subtotal,
                opciones_elegidas,
                usr_insert,
                fec_insert
            ) VALUES (
                (SELECT COALESCE(MAX(id_orden_producto), 0) + 1 FROM tab_orden_productos),
                v_id_orden,
                v_producto_record.variant_id,
                v_producto_record.cantidad,
                v_producto_record.precio_unitario_carrito,
                (v_producto_record.cantidad * v_producto_record.precio_unitario_carrito),
                v_producto_record.opciones_elegidas,
                p_usr_operacion,
                NOW()
            );
        END LOOP;

    -- PASO 12b: Si la orden se creó ya como Pagada, limpiar el carrito aquí (el trigger
    -- trg_limpiar_carrito_pagado solo se dispara en UPDATE; si disparara en INSERT, vaciaría
    -- el carrito antes de PASO 12 y no se copiarían ítems a tab_orden_productos).
        IF COALESCE(p_ind_estado, 1) = 2 THEN
            DELETE FROM tab_carrito_productos WHERE id_carrito = p_id_carrito;
            UPDATE tab_carritos SET usr_update = p_usr_operacion, fec_update = NOW() WHERE id_carrito = p_id_carrito;
        END IF;
        
    -- PASO 13: Marcar canje como utilizado (si se aplicó)
        IF p_id_canje IS NOT NULL AND v_descuento_canje IS NOT NULL THEN
            UPDATE tab_canjes_puntos_descuentos
            SET ind_utilizado = TRUE,
                fec_utilizacion = NOW(),
                id_orden_aplicado = v_id_orden,
                usr_update = p_usr_operacion
            WHERE id_canje = p_id_canje;
            
            -- Registrar uso del descuento canjeado (si hay usuario)
            IF v_id_usuario IS NOT NULL AND v_canje_info.id_descuento IS NOT NULL THEN
                PERFORM fun_registrar_uso_descuento(v_canje_info.id_descuento, v_id_usuario, p_usr_operacion);
            END IF;
        END IF;
        
    -- PASO 13.5: Registrar usos de descuentos aplicados (código y automáticos)
        -- Registrar uso del descuento por código (si se aplicó y hay usuario)
        IF v_descuento_codigo IS NOT NULL AND v_id_usuario IS NOT NULL THEN
            PERFORM fun_registrar_uso_descuento(
                (v_descuento_codigo->>'id_descuento')::DECIMAL,
                v_id_usuario,
                p_usr_operacion
            );
        END IF;
        
        -- Registrar usos de descuentos automáticos (si hay usuario)
        IF v_id_usuario IS NOT NULL AND v_descuentos_automaticos IS NOT NULL AND json_array_length(v_descuentos_automaticos) > 0 THEN
            FOR v_descuento_auto IN 
                SELECT (elem->>'id_descuento')::DECIMAL AS id_descuento_val
                FROM json_array_elements(v_descuentos_automaticos) AS elem
                WHERE (elem->>'id_descuento') IS NOT NULL
            LOOP
                PERFORM fun_registrar_uso_descuento(
                    v_descuento_auto.id_descuento_val,
                    v_id_usuario,
                    p_usr_operacion
                );
            END LOOP;
        END IF;
        
    -- PASO 14: Productos transferidos exitosamente a la orden
        -- NOTA: El carrito se mantiene intacto hasta que se PAGUE la orden
        --       El trigger trg_limpiar_carrito_pagado se encarga de limpiarlo automáticamente
        --       Esto permite que el usuario pueda cancelar y seguir comprando si es necesario
        
        -- RESPUESTA: Orden procesada exitosamente
        RETURN json_build_object(
            'success', true, 
        'message', 'Orden creada exitosamente',
        'accion_realizada', 'crear',
            'id_orden', v_id_orden,
            'id_carrito', p_id_carrito,
            'total_productos', v_total_productos,
            'total_descuentos', v_total_descuentos,
            'total_final', v_total_final,
            'detalle_descuentos_aplicados', COALESCE(v_descuentos_aplicados, '[]'::JSON),
            'codigo_descuento_aplicado', p_codigo_descuento,
            'productos_transferidos', v_count_productos,
            'estado_orden', 'pendiente',
            'metodo_pago', NULL,
            'es_primera_compra', v_es_primera_compra,
            'procesos_automaticos', json_build_object(
                'carrito_limpiado', false,
                'carrito_limpieza_programada', 'Se limpiará automáticamente al pagar la orden',
                'stock_reservado', true,
                'triggers_activados', true,
            'orden_actualizada', false
            )
        );
        
    EXCEPTION WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false, 
            'message', 'Error al crear la orden: ' || SQLERRM,
            'error_code', SQLSTATE,
            'id_carrito', p_id_carrito
        );
END;
$$;


--
-- Name: fun_crear_pago(numeric, character varying, character varying, numeric, character varying, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_crear_pago(p_id_orden numeric, p_provider_name character varying, p_provider_transaction_id character varying, p_amount numeric, p_status character varying, p_usr_operacion numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_pago INT;
BEGIN
    -- VALIDACIONES
    IF p_id_orden IS NULL OR p_amount <= 0 THEN
        RETURN json_build_object('success', false, 'message', 'El ID de la orden y un monto válido son requeridos.');
    END IF;

     -- INSERCIÓN ACTUALIZADA
    INSERT INTO tab_pagos (
        id_orden,
        provider_name,
        provider_transaction_id, -- Columna actualizada
        amount,
        status,
        status_detail,
        estado_procesamiento,
        usr_insert,
        fec_insert
    ) VALUES (
        p_id_orden,
        p_provider_name,
        p_provider_transaction_id,
        p_amount,
        p_status,
        'payment_intent_created',
        'pendiente',
        p_usr_operacion,
        NOW()
    ) RETURNING id_pago INTO v_id_pago;

    -- RESPUESTA
    RETURN json_build_object(
        'success', true,
        'message', 'Registro de pago creado exitosamente.',
        'id_pago', v_id_pago
    );

EXCEPTION 
    WHEN foreign_key_violation THEN
        RETURN json_build_object('success', false, 'message', 'La orden especificada no existe.');
    WHEN OTHERS THEN
        RETURN json_build_object('success', false, 'message', 'Error inesperado: ' || SQLERRM);
END;
$$;


--
-- Name: fun_deactivate_activate_categoria(numeric, boolean, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_deactivate_activate_categoria(p_id_categoria numeric, p_activar boolean, p_usr_operacion numeric DEFAULT NULL::numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado_actual BOOLEAN;
    v_count_categorias INT := 0;
    v_count_productos INT := 0;
    v_accion TEXT;
BEGIN
    SELECT is_active INTO v_estado_actual FROM tab_categories WHERE id = p_id_categoria;
    IF v_estado_actual IS NULL THEN
        RETURN 'Error: Categoría no encontrada';
    END IF;
    IF v_estado_actual = p_activar THEN
        RETURN FORMAT('Error: La categoría ya está %s', CASE WHEN p_activar THEN 'activa' ELSE 'inactiva' END);
    END IF;

    v_accion := CASE WHEN p_activar THEN 'activada' ELSE 'desactivada' END;

    WITH RECURSIVE tree AS (
        SELECT id FROM tab_categories WHERE id = p_id_categoria
        UNION ALL
        SELECT c.id FROM tab_categories c
        INNER JOIN tree t ON c.parent_id = t.id
    )
    UPDATE tab_categories SET is_active = p_activar, usr_update = p_usr_operacion, fec_update = CURRENT_TIMESTAMP
    WHERE id IN (SELECT id FROM tree);
    GET DIAGNOSTICS v_count_categorias = ROW_COUNT;

    WITH RECURSIVE tree AS (
        SELECT id FROM tab_categories WHERE id = p_id_categoria
        UNION ALL
        SELECT c.id FROM tab_categories c INNER JOIN tree t ON c.parent_id = t.id
    )
    UPDATE tab_products SET is_active = p_activar, usr_update = p_usr_operacion, fec_update = CURRENT_TIMESTAMP
    WHERE category_id IN (SELECT id FROM tree);
    GET DIAGNOSTICS v_count_productos = ROW_COUNT;

    RETURN FORMAT('Categoría %s exitosamente. Se actualizaron %s categoría(s) y %s producto(s).',
        v_accion, v_count_categorias, v_count_productos);
EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Error: ' || SQLERRM;
END;
$$;


--
-- Name: fun_deactivate_activate_marca(numeric, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_deactivate_activate_marca(wid_marca numeric, wusr_operacion numeric, wactivar boolean) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado_actual BOOLEAN;
    v_accion TEXT;
BEGIN
    -- VALIDACIÓN 1: ID de usuario operación para auditoría
    IF wusr_operacion IS NULL OR wusr_operacion <= 0 THEN
        RETURN 'Error: El ID del usuario que realiza la operación es obligatorio y debe ser mayor a 0.';
    END IF;

    -- Obtener el estado actual de la marca
    SELECT ind_activo INTO v_estado_actual
    FROM tab_marcas
    WHERE id_marca = wid_marca;
    
    -- VALIDACIÓN: Verificar que la marca existe
    IF v_estado_actual IS NULL THEN
        RETURN 'Error: Marca no encontrada';
    END IF;
    
    -- VALIDACIÓN: Verificar que el estado es diferente al solicitado
    IF v_estado_actual = wactivar THEN
        RETURN FORMAT('Error: La marca ya está %s', 
                     CASE WHEN wactivar THEN 'activa' ELSE 'inactiva' END);
    END IF;
    
    -- Determinar el texto de la acción
    v_accion := CASE WHEN wactivar THEN 'activada' ELSE 'desactivada' END;

    -- ACTIVACIÓN/DESACTIVACIÓN: Cambiar estado de la marca según wactivar
    UPDATE tab_marcas SET 
        ind_activo = wactivar,
        usr_update = wusr_operacion,
        fec_update = CURRENT_TIMESTAMP
    WHERE id_marca = wid_marca;
    
    -- VERIFICACIÓN: Confirmar que la operación fue exitosa
    IF FOUND THEN
        RAISE NOTICE 'Marca %s exitosamente - ID: % por usuario ID: %', v_accion, wid_marca, wusr_operacion;
        RETURN FORMAT('Marca %s correctamente', v_accion);
    ELSE
        RAISE NOTICE 'No se pudo actualizar la marca - ID: %', wid_marca;
        RETURN 'Error: No se pudo actualizar la marca';
    END IF;

    -- MANEJO DE ERRORES: Capturar excepciones inesperadas
    EXCEPTION
        WHEN OTHERS THEN
            RETURN 'Error inesperado: ' || SQLERRM;
            ROLLBACK;
END;
$$;


--
-- Name: fun_deactivate_activate_producto(numeric, boolean, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_deactivate_activate_producto(p_id_producto numeric, p_activar boolean, p_usr_operacion numeric DEFAULT NULL::numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado BOOLEAN;
    v_var INT;
BEGIN
    SELECT is_active INTO v_estado FROM tab_products WHERE id = p_id_producto;
    IF v_estado IS NULL THEN
        RETURN 'Error: Producto no encontrado';
    END IF;
    IF v_estado = p_activar THEN
        RETURN FORMAT('Error: El producto ya está %s', CASE WHEN p_activar THEN 'activo' ELSE 'inactivo' END);
    END IF;
    UPDATE tab_products SET is_active = p_activar, usr_update = p_usr_operacion, fec_update = CURRENT_TIMESTAMP WHERE id = p_id_producto;
    UPDATE tab_product_variant_groups SET is_active = p_activar, usr_update = p_usr_operacion, fec_update = CURRENT_TIMESTAMP WHERE product_id = p_id_producto;
    UPDATE tab_product_variant_combinations c SET is_active = p_activar, usr_update = p_usr_operacion, fec_update = CURRENT_TIMESTAMP
    WHERE c.group_id IN (SELECT id FROM tab_product_variant_groups WHERE product_id = p_id_producto);
    GET DIAGNOSTICS v_var = ROW_COUNT;
    RETURN FORMAT('Producto %s. Combinaciones actualizadas: %s.', CASE WHEN p_activar THEN 'activado' ELSE 'desactivado' END, v_var);
EXCEPTION
    WHEN OTHERS THEN RETURN 'Error: ' || SQLERRM;
END;
$$;


--
-- Name: fun_deactivate_activate_proveedores(numeric, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_deactivate_activate_proveedores(wid_proveedor numeric, wusr_operacion numeric, wactivar boolean) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado_actual BOOLEAN;
    v_accion TEXT;
BEGIN
    -- VALIDACIÓN 1: ID de usuario operación para auditoría
    IF wusr_operacion IS NULL OR wusr_operacion <= 0 THEN
        RETURN 'Error: El ID del usuario que realiza la operación es obligatorio y debe ser mayor a 0.';
    END IF;

    -- Obtener el estado actual del proveedor
    SELECT ind_activo INTO v_estado_actual
    FROM tab_proveedores
    WHERE id_proveedor = wid_proveedor;
    
    -- VALIDACIÓN: Verificar que el proveedor existe
    IF v_estado_actual IS NULL THEN
        RETURN 'Error: Proveedor no encontrado';
    END IF;
    
    -- VALIDACIÓN: Verificar que el estado es diferente al solicitado
    IF v_estado_actual = wactivar THEN
        RETURN FORMAT('Error: El proveedor ya está %s', 
                     CASE WHEN wactivar THEN 'activo' ELSE 'inactivo' END);
    END IF;
    
    -- Determinar el texto de la acción
    v_accion := CASE WHEN wactivar THEN 'activado' ELSE 'desactivado' END;

    -- ACTIVACIÓN/DESACTIVACIÓN: Cambiar estado del proveedor según wactivar
    UPDATE tab_proveedores SET 
        ind_activo = wactivar,
        usr_update = wusr_operacion,
        fec_update = CURRENT_TIMESTAMP
    WHERE id_proveedor = wid_proveedor;
    
    -- VERIFICACIÓN: Confirmar que la operación fue exitosa
    IF FOUND THEN
        RAISE NOTICE 'Proveedor %s exitosamente - ID: % por usuario ID: %', v_accion, wid_proveedor, wusr_operacion;
        RETURN FORMAT('Proveedor %s correctamente', v_accion);
    ELSE
        RAISE NOTICE 'No se pudo actualizar el proveedor - ID: %', wid_proveedor;
        RETURN 'Error: No se pudo actualizar el proveedor';
    END IF;

    -- MANEJO DE ERRORES: Capturar excepciones inesperadas
    EXCEPTION
        WHEN OTHERS THEN
            RETURN 'Error inesperado: ' || SQLERRM;
            ROLLBACK;
END;
$$;


--
-- Name: fun_deactivate_comentarios(numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_deactivate_comentarios(wid_producto numeric, wid_usuario numeric, wid_comentario numeric, wusr_operacion numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF wusr_operacion IS NULL OR wusr_operacion <= 0 THEN
        RETURN 'Error: El usuario de operación es obligatorio';
    END IF;
    IF wid_producto IS NULL OR wid_producto <= 0 THEN
        RETURN 'Error: El product_id es obligatorio';
    END IF;
    IF wid_usuario IS NULL OR wid_usuario <= 0 THEN
        RETURN 'Error: El ID de usuario es obligatorio';
    END IF;
    IF wid_comentario IS NULL OR wid_comentario <= 0 THEN
        RETURN 'Error: El ID de comentario es obligatorio';
    END IF;

    UPDATE tab_comentarios SET
        ind_activo = FALSE,
        usr_update = wusr_operacion,
        fec_update = NOW()
    WHERE product_id = wid_producto
      AND id_usuario = wid_usuario
      AND id_comentario = wid_comentario
      AND ind_activo = TRUE;

    IF FOUND THEN
        RETURN 'Comentario desactivado correctamente';
    ELSE
        RETURN 'Error: No se encontró el comentario activo especificado';
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Error: ' || SQLERRM;
END;
$$;


--
-- Name: fun_deactivate_direccion_principal(numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_deactivate_direccion_principal(wid_direccion numeric, wid_usuario numeric, wusr_operacion numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_direccion_existe BOOLEAN := FALSE;
    v_es_principal BOOLEAN := FALSE;
    v_mensaje VARCHAR;
BEGIN
    -- VALIDACIÓN 1: ID de dirección
    IF wid_direccion IS NULL OR wid_direccion = 0 THEN
        RETURN 'Error: El ID de dirección es obligatorio y debe ser mayor a 0.';
    END IF;

    -- VALIDACIÓN 2: ID de usuario
    IF wid_usuario IS NULL OR wid_usuario = 0 THEN
        RETURN 'Error: El ID de usuario es obligatorio y debe ser mayor a 0.';
    END IF;

    -- VALIDACIÓN 3: usr_operacion
    IF wusr_operacion IS NULL OR wusr_operacion <= 0 THEN
        RETURN 'Error: El ID del usuario que realiza la operación es obligatorio y debe ser mayor a 0.';
    END IF;

    -- PASO 1: Verificar que la dirección existe y pertenece al usuario
    SELECT EXISTS(
        SELECT 1 FROM tab_direcciones_usuario 
        WHERE id_direccion = wid_direccion 
        AND id_usuario = wid_usuario 
        AND ind_activa = TRUE
    ) INTO v_direccion_existe;

    IF NOT v_direccion_existe THEN
        RETURN 'Error: La dirección no existe, no pertenece al usuario o está inactiva.';
    END IF;

    -- PASO 2: Verificar si la dirección es actualmente principal
    SELECT ind_principal INTO v_es_principal
    FROM tab_direcciones_usuario 
    WHERE id_direccion = wid_direccion AND id_usuario = wid_usuario;

    -- PASO 3: Verificar si ya no es principal
    IF NOT v_es_principal THEN
        v_mensaje := 'La dirección ya no es principal';
        RAISE NOTICE '%', v_mensaje;
        RETURN v_mensaje;
    END IF;

    -- PASO 4: Desactivar el estado principal de la dirección
    UPDATE tab_direcciones_usuario 
    SET ind_principal = FALSE,
        usr_update = wusr_operacion
    WHERE id_direccion = wid_direccion AND id_usuario = wid_usuario;

    -- PASO 5: Verificar éxito de la operación
    IF FOUND THEN
        v_mensaje := 'Dirección removida como principal correctamente';
        RAISE NOTICE 'Dirección % removida como principal para usuario: %', wid_direccion, wid_usuario;
        RETURN v_mensaje;
    ELSE
        RAISE NOTICE 'Error: No se pudo desactivar la dirección como principal';
        RETURN 'Error: No se pudo desactivar la dirección como principal';
    END IF;

    -- MANEJO DE ERRORES: Capturar excepciones inesperadas
    EXCEPTION
        WHEN SQLSTATE '23503' THEN
            RETURN 'Error: El usuario especificado no existe o está inactivo.';
        WHEN OTHERS THEN
            RETURN 'Error inesperado: ' || SQLERRM;
            ROLLBACK;
END;
$$;


--
-- Name: fun_deactivate_direcciones(numeric, numeric, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_deactivate_direcciones(wid_direccion numeric, wid_usuario numeric, wusr_operacion numeric, wactivar boolean DEFAULT false) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado_anterior BOOLEAN;
    v_estado_nuevo BOOLEAN;
    v_mensaje VARCHAR;
BEGIN
    -- PASO 1: Obtener el estado actual de la dirección
    SELECT ind_activa INTO v_estado_anterior
    FROM tab_direcciones_usuario 
    WHERE id_direccion = wid_direccion AND id_usuario = wid_usuario;
    
    -- PASO 2: Verificar si la dirección existe
    IF NOT FOUND THEN
        RAISE NOTICE 'Error: Dirección no encontrada';
        RETURN 'Error: Dirección no encontrada';
    END IF;
    
    -- PASO 3: Determinar el nuevo estado
    v_estado_nuevo := wactivar;
    
    -- PASO 4: Verificar si ya está en el estado deseado
    IF v_estado_anterior = v_estado_nuevo THEN
        IF v_estado_nuevo THEN
            v_mensaje := 'La dirección ya está activa';
        ELSE
            v_mensaje := 'La dirección ya está desactivada';
        END IF;
        RAISE NOTICE '%', v_mensaje;
        RETURN v_mensaje;
    END IF;
    
    -- PASO 5: Actualizar el estado de la dirección
    UPDATE tab_direcciones_usuario SET 
        ind_activa = v_estado_nuevo,
        usr_update = wusr_operacion
    WHERE id_direccion = wid_direccion AND id_usuario = wid_usuario;

    IF FOUND THEN
        IF v_estado_nuevo THEN
            v_mensaje := 'Dirección activada correctamente';
            RAISE NOTICE 'Dirección activada exitosamente: % por usuario ID: %', wid_direccion, wusr_operacion;
        ELSE
            v_mensaje := 'Dirección desactivada correctamente';
            RAISE NOTICE 'Dirección desactivada exitosamente: % por usuario ID: %', wid_direccion, wusr_operacion;
        END IF;
        RETURN v_mensaje;
    ELSE
        RAISE NOTICE 'Error: No se pudo actualizar la dirección';
        RETURN 'Error: No se pudo actualizar la dirección';
    END IF;

    -- MANEJO DE ERRORES: Capturar excepciones inesperadas
    EXCEPTION
        WHEN OTHERS THEN
            RETURN 'Error inesperado: ' || SQLERRM;
            ROLLBACK;
END;
$$;


