--
-- Name: fun_deactivate_usuarios(numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_deactivate_usuarios(wid_usuario numeric, wusr_operacion numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
    BEGIN
        -- VALIDACIÓN 1: ID de usuario operación para auditoría
        IF wusr_operacion IS NULL OR wusr_operacion <= 0 THEN
            RETURN 'Error: El ID del usuario que realiza la operación es obligatorio y debe ser mayor a 0.';
        END IF;

        -- DESACTIVACIÓN: Cambiar estado del usuario a inactivo (eliminación lógica)
        UPDATE tab_usuarios SET 
            ind_activo = FALSE,             -- Marcar como inactivo
            usr_update = wusr_operacion,    -- ID del usuario que realiza la desactivación
            fec_update = NOW()              -- Actualizar timestamp
        WHERE id_usuario = wid_usuario AND ind_activo = TRUE;  -- Solo si está activo actualmente
        
        -- VERIFICACIÓN: Confirmar que la desactivación fue exitosa
        IF FOUND THEN
            RAISE NOTICE 'Usuario desactivado exitosamente - ID: % por usuario ID: %', wid_usuario, wusr_operacion;
            RETURN 'Usuario desactivado correctamente';
        ELSE
            RAISE NOTICE 'Usuario no encontrado o ya estaba inactivo - ID: %', wid_usuario;
            RETURN 'Error: Usuario no encontrado o ya estaba inactivo';
        END IF;

    -- MANEJO DE ERRORES: Capturar excepciones inesperadas
    EXCEPTION
        WHEN OTHERS THEN
            RETURN 'Error inesperado: ' || SQLERRM;
            ROLLBACK;
    END;
$$;


--
-- Name: fun_delete_categoria(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_delete_categoria(p_id numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_children INT;
    v_products INT;
BEGIN
    IF p_id IS NULL OR NOT EXISTS (SELECT 1 FROM tab_categories WHERE id = p_id) THEN
        RETURN json_build_object('success', false, 'message', 'La categoría no existe', 'id_categoria', p_id);
    END IF;

    SELECT COUNT(*) INTO v_children FROM tab_categories WHERE parent_id = p_id;
    IF v_children > 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'No se puede eliminar: tiene subcategorías asociadas',
            'id_categoria', p_id,
            'hijas', v_children
        );
    END IF;

    SELECT COUNT(*) INTO v_products FROM tab_products WHERE category_id = p_id;
    IF v_products > 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'No se puede eliminar: tiene productos asociados',
            'id_categoria', p_id,
            'productos', v_products
        );
    END IF;

    DELETE FROM tab_estadisticas_categorias WHERE category_id = p_id;
    DELETE FROM tab_category_attributes WHERE category_id = p_id;
    DELETE FROM tab_categories WHERE id = p_id;

    RETURN json_build_object('success', true, 'message', 'Categoría eliminada', 'id_categoria', p_id);
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object('success', false, 'message', 'Error: ' || SQLERRM, 'id_categoria', p_id);
END;
$$;


--
-- Name: fun_delete_content(character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_delete_content(wnom_cms_content character varying, wusr_operacion character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
    BEGIN
        -- VALIDACIÓN 1: Nombre del contenido
        IF wnom_cms_content IS NULL OR wnom_cms_content = '' THEN
            RETURN 'Error: El nombre del contenido es obligatorio para eliminación.';
        END IF;

        -- VALIDACIÓN 2: Usuario operación para auditoría
        IF wusr_operacion IS NULL OR wusr_operacion = '' THEN
            RETURN 'Error: El usuario que realiza la operación es obligatorio para auditoría.';
        END IF;

        -- ELIMINACIÓN: Remover contenido CMS por nombre
        DELETE FROM tab_cms_content WHERE nom_cms_content = wnom_cms_content;
        
        -- VERIFICACIÓN: Confirmar que se eliminó el contenido
        IF FOUND THEN
            RAISE NOTICE 'Contenido CMS eliminado exitosamente por usuario %: %', wusr_operacion, wnom_cms_content;
            RETURN 'Contenido CMS eliminado correctamente';
        ELSE
            RETURN 'Error: Contenido no encontrado o ya fue eliminado';
        END IF;
    END;
$$;


