--
-- Name: fun_delete_marca(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_delete_marca(p_id_marca integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count_productos INTEGER;
    v_result JSON;
    v_id_marca INTEGER := p_id_marca;
BEGIN
    -- Verificar si la marca existe
    IF NOT EXISTS (SELECT 1 FROM tab_marcas WHERE id_marca = p_id_marca) THEN
        RETURN json_build_object(
            'success', false,
            'message', 'La marca no existe',
            'id_marca', p_id_marca
        );
    END IF;

    -- Verificar si la marca tiene productos asociados
    SELECT COUNT(*) INTO v_count_productos 
    FROM tab_productos 
    WHERE id_marca = v_id_marca AND ind_activo = true;

    IF v_count_productos > 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'No se puede eliminar la marca porque tiene productos asociados',
            'productos_asociados', v_count_productos,
            'id_marca', p_id_marca
        );
    END IF;

    -- Eliminar la marca completamente
    DELETE FROM tab_marcas 
    WHERE id_marca = v_id_marca;

    RETURN json_build_object(
        'success', true,
        'message', 'Marca eliminada exitosamente',
        'id_marca', p_id_marca
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Error al eliminar la marca: ' || SQLERRM,
            'id_marca', p_id_marca
        );
END;
$$;


--
-- Name: fun_delete_producto(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_delete_producto(p_id numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_carrito INT;
    v_orden INT;
BEGIN
    IF p_id IS NULL OR NOT EXISTS (SELECT 1 FROM tab_products WHERE id = p_id) THEN
        RETURN json_build_object('success', false, 'message', 'Producto no encontrado', 'id_producto', p_id);
    END IF;
    SELECT COUNT(*) INTO v_carrito FROM tab_carrito_productos cp JOIN tab_product_variant_combinations pv ON cp.variant_id = pv.id JOIN tab_product_variant_groups g ON g.id = pv.group_id WHERE g.product_id = p_id;
    IF v_carrito > 0 THEN
        RETURN json_build_object('success', false, 'message', 'No se puede eliminar: hay ítems en carrito', 'id_producto', p_id);
    END IF;
    SELECT COUNT(*) INTO v_orden FROM tab_orden_productos op JOIN tab_product_variant_combinations pv ON op.variant_id = pv.id JOIN tab_product_variant_groups g ON g.id = pv.group_id WHERE g.product_id = p_id;
    IF v_orden > 0 THEN
        RETURN json_build_object('success', false, 'message', 'No se puede eliminar: hay ítems en órdenes', 'id_producto', p_id);
    END IF;

    DELETE FROM tab_product_variant_images WHERE variant_group_id IN (SELECT id FROM tab_product_variant_groups WHERE product_id = p_id);
    DELETE FROM tab_product_variant_combinations WHERE group_id IN (SELECT id FROM tab_product_variant_groups WHERE product_id = p_id);
    DELETE FROM tab_product_variant_groups WHERE product_id = p_id;
    DELETE FROM tab_estadisticas_productos WHERE product_id = p_id;
    DELETE FROM tab_favoritos WHERE product_id = p_id;
    DELETE FROM tab_comentarios WHERE product_id = p_id;
    DELETE FROM tab_products WHERE id = p_id;

    RETURN json_build_object('success', true, 'message', 'Producto eliminado', 'id_producto', p_id);
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object('success', false, 'message', 'Error: ' || SQLERRM, 'id_producto', p_id);
END;
$$;


--
-- Name: fun_delete_proveedor(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_delete_proveedor(p_id_proveedor integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count_productos INTEGER;
    v_count_ordenes_compra INTEGER;
    v_result JSON;
    v_id_proveedor INTEGER := p_id_proveedor;
BEGIN
    -- Verificar si el proveedor existe
    IF NOT EXISTS (SELECT 1 FROM tab_proveedores WHERE id_proveedor = p_id_proveedor) THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El proveedor no existe',
            'id_proveedor', p_id_proveedor
        );
    END IF;

    -- Verificar si el proveedor tiene productos asociados
    SELECT COUNT(*) INTO v_count_productos 
    FROM tab_productos 
    WHERE id_proveedor = v_id_proveedor AND ind_activo = true;

    IF v_count_productos > 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'No se puede eliminar el proveedor porque tiene productos asociados',
            'productos_asociados', v_count_productos,
            'id_proveedor', p_id_proveedor
        );
    END IF;

    -- Verificar si el proveedor tiene órdenes de compra asociadas
    SELECT COUNT(*) INTO v_count_ordenes_compra 
    FROM tab_orden_compra_proveedor 
    WHERE id_proveedor = v_id_proveedor;

    IF v_count_ordenes_compra > 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'No se puede eliminar el proveedor porque tiene órdenes de compra asociadas',
            'ordenes_compra_asociadas', v_count_ordenes_compra,
            'id_proveedor', p_id_proveedor
        );
    END IF;

    -- Eliminar el proveedor completamente
    DELETE FROM tab_proveedores 
    WHERE id_proveedor = v_id_proveedor;

    RETURN json_build_object(
        'success', true,
        'message', 'Proveedor eliminado exitosamente',
        'id_proveedor', p_id_proveedor
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Error al eliminar el proveedor: ' || SQLERRM,
            'id_proveedor', p_id_proveedor
        );
END;
$$;


