--
-- Name: fun_eliminar_metodo_pago(numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_eliminar_metodo_pago(p_id_usuario numeric, p_id_metodo_pago integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_deleted_rows INT;
BEGIN
    -- VALIDACIONES
    IF p_id_usuario IS NULL OR p_id_metodo_pago IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'ID de usuario y ID de método de pago son obligatorios');
    END IF;

    -- ELIMINACIÓN
    DELETE FROM tab_metodos_pago_usuario
    WHERE
        id_usuario = p_id_usuario AND id_metodo_pago = p_id_metodo_pago;
    
    GET DIAGNOSTICS v_deleted_rows = ROW_COUNT;

    -- RESPUESTA
    IF v_deleted_rows = 0 THEN
        RETURN json_build_object(
            'success', false, 
            'message', 'El método de pago no fue encontrado para este usuario.'
        );
    END IF;
    
    RETURN json_build_object(
        'success', true,
        'message', 'Método de pago eliminado exitosamente.'
    );

EXCEPTION 
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false, 
            'message', 'Error inesperado: ' || SQLERRM
        );
END;
$$;


--
-- Name: fun_eliminar_producto_carrito(numeric, character varying, numeric, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_eliminar_producto_carrito(p_id_usuario numeric, p_session_id character varying, p_variant_id numeric, p_cantidad integer, p_usr_operacion numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_carrito tab_carritos.id_carrito%TYPE;
    v_cantidad_actual tab_carrito_productos.cantidad%TYPE;
    v_cantidad_eliminar tab_carrito_productos.cantidad%TYPE;
    v_cantidad_restante tab_carrito_productos.cantidad%TYPE;
    v_usr_final tab_carrito_productos.usr_update%TYPE;
BEGIN
    IF p_id_usuario IS NULL AND p_session_id IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Debe proporcionar id_usuario o session_id');
    END IF;
    IF p_variant_id IS NULL OR p_variant_id <= 0 THEN
        RETURN json_build_object('success', false, 'message', 'variant_id es obligatorio');
    END IF;
    IF p_cantidad IS NOT NULL AND p_cantidad <= 0 THEN
        RETURN json_build_object('success', false, 'message', 'La cantidad a eliminar debe ser mayor a 0');
    END IF;

    v_usr_final := COALESCE(p_usr_operacion, p_id_usuario, ABS(hashtext(p_session_id))::DECIMAL(10));
    v_id_carrito := fun_obtener_carrito_usuario(p_id_usuario, p_session_id);

    SELECT cantidad INTO v_cantidad_actual
    FROM tab_carrito_productos
    WHERE id_carrito = v_id_carrito AND variant_id = p_variant_id;

    IF v_cantidad_actual IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'El producto no está en el carrito');
    END IF;

    IF p_cantidad IS NULL THEN
        v_cantidad_eliminar := v_cantidad_actual;
        v_cantidad_restante := 0;
    ELSIF p_cantidad >= v_cantidad_actual THEN
        v_cantidad_eliminar := v_cantidad_actual;
        v_cantidad_restante := 0;
    ELSE
        v_cantidad_eliminar := p_cantidad;
        v_cantidad_restante := v_cantidad_actual - p_cantidad;
    END IF;

    IF v_cantidad_restante = 0 THEN
        DELETE FROM tab_carrito_productos
        WHERE id_carrito = v_id_carrito AND variant_id = p_variant_id;
    ELSE
        UPDATE tab_carrito_productos
        SET cantidad = v_cantidad_restante, usr_update = v_usr_final, fec_update = NOW()
        WHERE id_carrito = v_id_carrito AND variant_id = p_variant_id;
    END IF;

    UPDATE tab_carritos SET fec_update = NOW(), usr_update = v_usr_final WHERE id_carrito = v_id_carrito;

    RETURN json_build_object(
        'success', true,
        'message', CASE WHEN v_cantidad_restante = 0 THEN 'Producto eliminado del carrito' ELSE 'Cantidad reducida' END,
        'id_carrito', v_id_carrito,
        'cantidad_eliminada', v_cantidad_eliminar,
        'cantidad_restante', v_cantidad_restante
    );
END;
$$;


--
-- Name: fun_filter_products(numeric, boolean, numeric, character varying, numeric, numeric, boolean, boolean, character varying, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_filter_products(p_category_id numeric DEFAULT NULL::numeric, p_include_subcategories boolean DEFAULT false, p_id_marca numeric DEFAULT NULL::numeric, p_nombre_producto character varying DEFAULT NULL::character varying, p_precio_min numeric DEFAULT NULL::numeric, p_precio_max numeric DEFAULT NULL::numeric, p_solo_con_stock boolean DEFAULT false, p_solo_en_oferta boolean DEFAULT false, p_ordenar_por character varying DEFAULT 'nombre'::character varying, p_orden character varying DEFAULT 'ASC'::character varying, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(product_id numeric, category_id numeric, nom_categoria character varying, nom_producto character varying, slug_producto character varying, description text, id_marca numeric, precio_min numeric, precio_max numeric, stock_total bigint, img_principal character varying, total_registros bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF p_limit > 1000 THEN p_limit := 1000; END IF;
    IF p_offset < 0 THEN p_offset := 0; END IF;
    IF UPPER(p_orden) NOT IN ('ASC', 'DESC') THEN p_orden := 'ASC'; END IF;
    IF p_ordenar_por NOT IN ('precio', 'nombre', 'stock', 'fecha') THEN p_ordenar_por := 'nombre'; END IF;

    RETURN QUERY
    WITH RECURSIVE tree AS (
        SELECT id FROM tab_categories WHERE id = COALESCE(p_category_id, 0)
        UNION ALL
        SELECT c.id FROM tab_categories c INNER JOIN tree t ON c.parent_id = t.id
    ),
    category_ids AS (
        SELECT id FROM tab_categories WHERE is_active = TRUE
        AND (
            p_category_id IS NULL
            OR (p_category_id IS NOT NULL AND NOT p_include_subcategories AND id = p_category_id)
            OR (p_category_id IS NOT NULL AND p_include_subcategories AND id IN (SELECT id FROM tree))
        )
    ),
    agg AS (
        SELECT
            p.id AS product_id,
            p.category_id,
            c.name AS nom_categoria,
            p.name AS nom_producto,
            p.slug AS slug_producto,
            p.description,
            p.id_marca,
            (SELECT MIN(cmb.price) FROM tab_product_variant_combinations cmb JOIN tab_product_variant_groups g ON g.id = cmb.group_id WHERE g.product_id = p.id AND cmb.is_active = TRUE) AS precio_min,
            (SELECT MAX(cmb.price) FROM tab_product_variant_combinations cmb JOIN tab_product_variant_groups g ON g.id = cmb.group_id WHERE g.product_id = p.id AND cmb.is_active = TRUE) AS precio_max,
            (SELECT COALESCE(SUM(cmb.stock), 0) FROM tab_product_variant_combinations cmb JOIN tab_product_variant_groups g ON g.id = cmb.group_id WHERE g.product_id = p.id AND cmb.is_active = TRUE) AS stock_total,
            COALESCE(
              (SELECT pvi.image_url FROM tab_product_variant_images pvi
               INNER JOIN tab_product_variant_groups g ON g.id = pvi.variant_group_id
               WHERE g.product_id = p.id
                 AND LOWER(TRIM(COALESCE(g.dominant_value, ''))) = 'sin color'
               ORDER BY pvi.is_primary DESC NULLS LAST, pvi.sort_order NULLS LAST, pvi.id
               LIMIT 1),
              (SELECT pvi.image_url FROM tab_product_variant_images pvi
               INNER JOIN tab_product_variant_groups g ON g.id = pvi.variant_group_id
               WHERE g.product_id = p.id
               ORDER BY g.id, pvi.sort_order, pvi.id
               LIMIT 1)
            ) AS img_principal
        FROM tab_products p
        JOIN tab_categories c ON c.id = p.category_id
        WHERE p.is_active = TRUE
        AND p.category_id IN (SELECT id FROM category_ids)
        AND (p_id_marca IS NULL OR p.id_marca = p_id_marca)
        AND (p_nombre_producto IS NULL OR trim(p_nombre_producto) = '' OR unaccent(lower(p.name)) LIKE '%' || unaccent(lower(trim(p_nombre_producto))) || '%')
    ),
    filt AS (
        SELECT 
            agg.product_id,
            agg.category_id,
            agg.nom_categoria,
            agg.nom_producto,
            agg.slug_producto,
            agg.description,
            agg.id_marca,
            agg.precio_min,
            agg.precio_max,
            agg.stock_total,
            agg.img_principal
        FROM agg
        WHERE (p_precio_min IS NULL OR agg.precio_min >= p_precio_min)
        AND (p_precio_max IS NULL OR agg.precio_min <= p_precio_max)
        AND (NOT p_solo_con_stock OR (agg.stock_total > 0))
        AND (
            NOT p_solo_en_oferta
            OR (
                agg.precio_min IS NOT NULL AND agg.precio_min > 0
                AND EXISTS (
                    SELECT 1 FROM tab_descuentos d
                    WHERE d.ind_activo = TRUE
                      AND COALESCE(d.ind_canjeable_puntos, FALSE) = FALSE
                      AND COALESCE(d.ind_es_para_cumpleanos, FALSE) = FALSE
                      AND COALESCE(d.solo_primera_compra, FALSE) = FALSE
                      AND COALESCE(d.requiere_codigo, FALSE) = FALSE
                      AND (d.fec_inicio IS NULL OR d.fec_inicio <= CURRENT_DATE)
                      AND (d.fec_fin IS NULL OR d.fec_fin >= CURRENT_DATE)
                      AND (d.max_usos_total IS NULL OR d.usos_actuales_total IS NULL OR d.usos_actuales_total < d.max_usos_total)
                      AND (
                          (d.tipo_calculo = TRUE AND COALESCE(d.val_porce_descuento, 0) > 0)
                          OR (d.tipo_calculo = FALSE AND COALESCE(d.val_monto_descuento, 0) > 0)
                      )
                      AND (
                          d.aplica_a IN ('todos', 'total_pedido')
                          OR (d.aplica_a = 'producto_especifico' AND d.product_id_aplica IS NOT NULL AND d.product_id_aplica = agg.product_id)
                          OR (d.aplica_a = 'categoria_especifica' AND d.category_id_aplica IS NOT NULL AND d.category_id_aplica = agg.category_id)
                          OR (d.aplica_a = 'marca_especifica' AND d.id_marca_aplica IS NOT NULL AND d.id_marca_aplica = agg.id_marca)
                          OR (d.aplica_a IN ('linea_especifica', 'sublinea_especifica') AND d.category_id_aplica IS NOT NULL AND d.category_id_aplica = agg.category_id)
                      )
                )
            )
        )
    ),
    total AS (SELECT COUNT(1) AS n FROM filt)
    SELECT
        f.product_id,
        f.category_id,
        f.nom_categoria,
        f.nom_producto,
        f.slug_producto,
        f.description,
        f.id_marca,
        f.precio_min,
        f.precio_max,
        f.stock_total::BIGINT,
        f.img_principal,
        (SELECT n FROM total) AS total_registros
    FROM filt f
    ORDER BY
        CASE WHEN p_ordenar_por = 'precio' AND UPPER(p_orden) = 'ASC' THEN f.precio_min END ASC NULLS LAST,
        CASE WHEN p_ordenar_por = 'precio' AND UPPER(p_orden) = 'DESC' THEN f.precio_min END DESC NULLS LAST,
        CASE WHEN p_ordenar_por = 'nombre' AND UPPER(p_orden) = 'ASC' THEN f.nom_producto END ASC,
        CASE WHEN p_ordenar_por = 'nombre' AND UPPER(p_orden) = 'DESC' THEN f.nom_producto END DESC,
        CASE WHEN p_ordenar_por = 'stock' AND UPPER(p_orden) = 'ASC' THEN f.stock_total END ASC NULLS LAST,
        CASE WHEN p_ordenar_por = 'stock' AND UPPER(p_orden) = 'DESC' THEN f.stock_total END DESC NULLS LAST,
        f.product_id
    LIMIT p_limit OFFSET p_offset;
EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Error en filtrado de productos: %', SQLERRM;
END;
$$;


--
-- Name: fun_generate_sku(numeric, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_generate_sku(p_product_id numeric, p_custom character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_sku VARCHAR;
    v_seq INT;
BEGIN
    IF p_custom IS NOT NULL AND length(trim(p_custom)) > 0 AND length(trim(p_custom)) < 120 THEN
        IF NOT EXISTS (SELECT 1 FROM tab_product_variant_combinations WHERE sku = trim(p_custom)) THEN
            RETURN trim(p_custom);
        END IF;
    END IF;
    SELECT COUNT(*) + 1 INTO v_seq
    FROM tab_product_variant_combinations c
    JOIN tab_product_variant_groups g ON g.id = c.group_id
    WHERE g.product_id = p_product_id;
    v_sku := 'SKU-' || p_product_id || '-' || v_seq;
    IF length(v_sku) >= 120 THEN
        RAISE EXCEPTION 'SKU generado excede longitud permitida';
    END IF;
    RETURN v_sku;
END;
$$;


--
-- Name: fun_generate_unique_slug(text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_generate_unique_slug(p_name text, p_table text, p_exclude_id numeric DEFAULT NULL::numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    base VARCHAR;
    candidate VARCHAR;
    i INT := 0;
    found BOOLEAN;
BEGIN
    IF p_name IS NULL OR trim(p_name) = '' THEN
        RETURN 'item';
    END IF;
    base := lower(trim(p_name));
    base := translate(base, 'áéíóúñüàèìòùäëïöüÁÉÍÓÚÑÜÀÈÌÒÙÄËÏÖÜ', 'aeiounuaeiouaeiouAEIOUNUAEIOUAEIOU');
    base := regexp_replace(base, '[^a-z0-9]+', '-', 'g');
    base := trim(both '-' from base);
    IF base = '' THEN
        base := 'item';
    END IF;
    candidate := base;
    LOOP
        IF p_table = 'tab_categories' THEN
            SELECT EXISTS(SELECT 1 FROM tab_categories WHERE slug = candidate AND (p_exclude_id IS NULL OR id != p_exclude_id)) INTO found;
        ELSIF p_table = 'tab_products' THEN
            SELECT EXISTS(SELECT 1 FROM tab_products WHERE slug = candidate AND (p_exclude_id IS NULL OR id != p_exclude_id)) INTO found;
        ELSE
            RAISE EXCEPTION 'fun_generate_unique_slug: tabla no soportada %', p_table;
        END IF;
        IF NOT found THEN
            RETURN candidate;
        END IF;
        i := i + 1;
        candidate := base || '-' || i;
        IF i > 9999 THEN
            RAISE EXCEPTION 'fun_generate_unique_slug: no se pudo generar slug único';
        END IF;
    END LOOP;
END;
$$;


--
-- Name: fun_get_all_products_admin(character varying, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_get_all_products_admin(p_ordenar_por character varying DEFAULT 'nombre'::character varying, p_orden character varying DEFAULT 'ASC'::character varying, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(product_id numeric, category_id numeric, nom_categoria character varying, nom_producto character varying, slug_producto character varying, description text, img_principal character varying, precio_min numeric, precio_max numeric, stock_total bigint, id_marca numeric, nom_marca character varying, id_proveedor numeric, nom_proveedor character varying, fec_insert timestamp without time zone, ind_activo_producto boolean, ind_activo_categoria boolean, ind_activo_marca boolean, total_registros bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF p_limit > 1000 THEN p_limit := 1000; END IF;
    IF p_offset < 0 THEN p_offset := 0; END IF;
    IF UPPER(p_orden) NOT IN ('ASC', 'DESC') THEN p_orden := 'ASC'; END IF;
    IF p_ordenar_por NOT IN ('precio', 'nombre', 'stock', 'fecha', 'categoria', 'marca') THEN
        p_ordenar_por := 'nombre';
    END IF;

    RETURN QUERY
    WITH agg AS (
        SELECT
            p.id AS product_id,
            p.category_id,
            c.name AS nom_categoria,
            p.name AS nom_producto,
            p.slug AS slug_producto,
            p.description,
            COALESCE(
              (SELECT pvi.image_url FROM tab_product_variant_images pvi
               INNER JOIN tab_product_variant_groups g ON g.id = pvi.variant_group_id
               WHERE g.product_id = p.id
                 AND LOWER(TRIM(COALESCE(g.dominant_value, ''))) = 'sin color'
               ORDER BY pvi.is_primary DESC NULLS LAST, pvi.sort_order NULLS LAST, pvi.id
               LIMIT 1),
              (SELECT pvi.image_url FROM tab_product_variant_images pvi
               INNER JOIN tab_product_variant_groups g ON g.id = pvi.variant_group_id
               WHERE g.product_id = p.id
               ORDER BY g.id, pvi.sort_order, pvi.id
               LIMIT 1)
            ) AS img_principal,
            -- Para admin: mostrar precio y stock incluso si las variantes están inactivas
            (SELECT MIN(c.price) FROM tab_product_variant_combinations c JOIN tab_product_variant_groups g ON g.id = c.group_id WHERE g.product_id = p.id) AS precio_min,
            (SELECT MAX(c.price) FROM tab_product_variant_combinations c JOIN tab_product_variant_groups g ON g.id = c.group_id WHERE g.product_id = p.id) AS precio_max,
            (SELECT COALESCE(SUM(c.stock), 0) FROM tab_product_variant_combinations c JOIN tab_product_variant_groups g ON g.id = c.group_id WHERE g.product_id = p.id) AS stock_total,
            p.id_marca,
            m.nom_marca,
            p.id_proveedor,
            pr.nom_proveedor,
            p.fec_insert,
            p.is_active AS ind_activo_producto,
            c.is_active AS ind_activo_categoria,
            m.ind_activo AS ind_activo_marca
        FROM tab_products p
        JOIN tab_categories c ON c.id = p.category_id
        LEFT JOIN tab_marcas m ON m.id_marca = p.id_marca
        LEFT JOIN tab_proveedores pr ON pr.id_proveedor = p.id_proveedor
    ),
    total AS (SELECT COUNT(1) AS n FROM agg)
    SELECT
        a.product_id,
        a.category_id,
        a.nom_categoria,
        a.nom_producto,
        a.slug_producto,
        a.description,
        a.img_principal,
        a.precio_min,
        a.precio_max,
        a.stock_total::BIGINT,
        a.id_marca,
        a.nom_marca,
        a.id_proveedor,
        a.nom_proveedor,
        a.fec_insert,
        a.ind_activo_producto,
        a.ind_activo_categoria,
        a.ind_activo_marca,
        (SELECT n FROM total)
    FROM agg a
    ORDER BY
        CASE WHEN p_ordenar_por = 'precio' AND UPPER(p_orden) = 'ASC' THEN a.precio_min END ASC NULLS LAST,
        CASE WHEN p_ordenar_por = 'precio' AND UPPER(p_orden) = 'DESC' THEN a.precio_min END DESC NULLS LAST,
        CASE WHEN p_ordenar_por = 'nombre' AND UPPER(p_orden) = 'ASC' THEN a.nom_producto END ASC,
        CASE WHEN p_ordenar_por = 'nombre' AND UPPER(p_orden) = 'DESC' THEN a.nom_producto END DESC,
        CASE WHEN p_ordenar_por = 'stock' AND UPPER(p_orden) = 'ASC' THEN a.stock_total END ASC NULLS LAST,
        CASE WHEN p_ordenar_por = 'stock' AND UPPER(p_orden) = 'DESC' THEN a.stock_total END DESC NULLS LAST,
        CASE WHEN p_ordenar_por = 'fecha' AND UPPER(p_orden) = 'ASC' THEN a.fec_insert END ASC NULLS LAST,
        CASE WHEN p_ordenar_por = 'fecha' AND UPPER(p_orden) = 'DESC' THEN a.fec_insert END DESC NULLS LAST,
        CASE WHEN p_ordenar_por = 'categoria' AND UPPER(p_orden) = 'ASC' THEN a.nom_categoria END ASC,
        CASE WHEN p_ordenar_por = 'categoria' AND UPPER(p_orden) = 'DESC' THEN a.nom_categoria END DESC,
        CASE WHEN p_ordenar_por = 'marca' AND UPPER(p_orden) = 'ASC' THEN a.nom_marca END ASC NULLS LAST,
        CASE WHEN p_ordenar_por = 'marca' AND UPPER(p_orden) = 'DESC' THEN a.nom_marca END DESC NULLS LAST,
        a.product_id
    LIMIT p_limit OFFSET p_offset;
EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Error en obtención de productos para admin: %', SQLERRM;
END;
$$;


--
-- Name: fun_get_categories_tree(numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_get_categories_tree(p_root_id numeric DEFAULT NULL::numeric, p_active_only boolean DEFAULT false) RETURNS TABLE(id numeric, name character varying, slug character varying, parent_id numeric, is_active boolean, level integer, path_ids numeric[])
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH RECURSIVE tree AS (
        SELECT c.id, c.name, c.slug, c.parent_id, c.is_active,
               0 AS level,
               ARRAY[c.id]::DECIMAL[] AS path_ids
        FROM tab_categories c
        WHERE (p_root_id IS NULL AND c.parent_id IS NULL)
           OR (p_root_id IS NOT NULL AND c.id = p_root_id)
        AND (NOT p_active_only OR c.is_active = TRUE)
        UNION ALL
        SELECT c.id, c.name, c.slug, c.parent_id, c.is_active,
               t.level + 1,
               t.path_ids || c.id
        FROM tab_categories c
        INNER JOIN tree t ON c.parent_id = t.id
        WHERE (NOT p_active_only OR c.is_active = TRUE)
    )
    SELECT t.id, t.name, t.slug, t.parent_id, t.is_active, t.level, t.path_ids
    FROM tree t
    ORDER BY t.path_ids;
END;
$$;


--
-- Name: fun_get_content(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_get_content(wnom_cms_content character varying) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- CONSULTA: Obtener contenido publicado por nombre
    RETURN (
        SELECT des_cms_content                                      -- Descripción del contenido
        FROM tab_cms_content 
        WHERE nom_cms_content = wnom_cms_content                    -- Contenido específico por nombre
          AND ind_publicado = true                                  -- Solo contenido publicado
    );
END;
$$;


--
-- Name: fun_get_productos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_get_productos() RETURNS TABLE(product_id numeric, category_id numeric, nom_categoria character varying, nom_producto character varying, slug_producto character varying, description text, id_marca numeric, is_active boolean, precio_min numeric, stock_total bigint, img_principal character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        p.id AS product_id,
        p.category_id,
        c.name AS nom_categoria,
        p.name AS nom_producto,
        p.slug AS slug_producto,
        p.description,
        p.id_marca,
        p.is_active,
        (SELECT MIN(c.price) FROM tab_product_variant_combinations c JOIN tab_product_variant_groups g ON g.id = c.group_id WHERE g.product_id = p.id AND c.is_active = TRUE) AS precio_min,
        (SELECT COALESCE(SUM(c.stock), 0) FROM tab_product_variant_combinations c JOIN tab_product_variant_groups g ON g.id = c.group_id WHERE g.product_id = p.id AND c.is_active = TRUE) AS stock_total,
        COALESCE(
          (SELECT pvi.image_url FROM tab_product_variant_images pvi
           INNER JOIN tab_product_variant_groups g ON g.id = pvi.variant_group_id
           WHERE g.product_id = p.id
             AND LOWER(TRIM(COALESCE(g.dominant_value, ''))) = 'sin color'
           ORDER BY pvi.is_primary DESC NULLS LAST, pvi.sort_order NULLS LAST, pvi.id
           LIMIT 1),
          (SELECT pvi.image_url FROM tab_product_variant_images pvi
           INNER JOIN tab_product_variant_groups g ON g.id = pvi.variant_group_id
           WHERE g.product_id = p.id
           ORDER BY g.id, pvi.sort_order, pvi.id
           LIMIT 1)
        ) AS img_principal
    FROM tab_products p
    JOIN tab_categories c ON c.id = p.category_id
    ORDER BY p.id;
END;
$$;


--
-- Name: fun_get_productos_activos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_get_productos_activos() RETURNS TABLE(product_id numeric, category_id numeric, nom_categoria character varying, nom_producto character varying, slug_producto character varying, description text, id_marca numeric, precio_min numeric, stock_total bigint, img_principal character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        p.id AS product_id,
        p.category_id,
        c.name AS nom_categoria,
        p.name AS nom_producto,
        p.slug AS slug_producto,
        p.description,
        p.id_marca,
        (SELECT MIN(c.price) FROM tab_product_variant_combinations c JOIN tab_product_variant_groups g ON g.id = c.group_id WHERE g.product_id = p.id AND c.is_active = TRUE) AS precio_min,
        (SELECT COALESCE(SUM(c.stock), 0) FROM tab_product_variant_combinations c JOIN tab_product_variant_groups g ON g.id = c.group_id WHERE g.product_id = p.id AND c.is_active = TRUE) AS stock_total,
        COALESCE(
          (SELECT pvi.image_url FROM tab_product_variant_images pvi
           INNER JOIN tab_product_variant_groups g ON g.id = pvi.variant_group_id
           WHERE g.product_id = p.id
             AND LOWER(TRIM(COALESCE(g.dominant_value, ''))) = 'sin color'
           ORDER BY pvi.is_primary DESC NULLS LAST, pvi.sort_order NULLS LAST, pvi.id
           LIMIT 1),
          (SELECT pvi.image_url FROM tab_product_variant_images pvi
           INNER JOIN tab_product_variant_groups g ON g.id = pvi.variant_group_id
           WHERE g.product_id = p.id
           ORDER BY g.id, pvi.sort_order, pvi.id
           LIMIT 1)
        ) AS img_principal
    FROM tab_products p
    JOIN tab_categories c ON c.id = p.category_id
    WHERE p.is_active = TRUE
    ORDER BY p.id;
END;
$$;


--
-- Name: fun_get_reviewed_products_in_order(numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_get_reviewed_products_in_order(wid_orden numeric, wid_usuario numeric) RETURNS TABLE(product_key character varying)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    IF wid_orden IS NULL OR wid_orden <= 0 THEN
        RAISE EXCEPTION 'El ID de orden es obligatorio y debe ser mayor a 0';
    END IF;
    IF wid_usuario IS NULL OR wid_usuario <= 0 THEN
        RAISE EXCEPTION 'El ID de usuario es obligatorio y debe ser mayor a 0';
    END IF;
    RETURN QUERY
    SELECT DISTINCT c.product_id::VARCHAR AS product_key
    FROM tab_comentarios c
    WHERE c.id_orden = wid_orden AND c.id_usuario = wid_usuario AND c.ind_activo = TRUE
    ORDER BY product_key;
EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Error al obtener productos reseñados: %', SQLERRM;
END;
$$;


--
-- Name: fun_insert_categoria(character varying, numeric, boolean, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_insert_categoria(p_name character varying, p_parent_id numeric DEFAULT NULL::numeric, p_is_active boolean DEFAULT true, p_usr_operacion numeric DEFAULT NULL::numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id DECIMAL(10);
    v_slug VARCHAR;
    v_usr DECIMAL(10);
BEGIN
    IF p_name IS NULL OR trim(p_name) = '' OR length(trim(p_name)) < 2 THEN
        RETURN 'Error: El nombre es obligatorio y debe tener al menos 2 caracteres.';
    END IF;
    IF p_parent_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM tab_categories WHERE id = p_parent_id) THEN
        RETURN 'Error: La categoría padre no existe.';
    END IF;
    v_usr := COALESCE(p_usr_operacion, 0);

    v_id := (SELECT COALESCE(MAX(id), 0) + 1 FROM tab_categories);
    v_slug := fun_generate_unique_slug(p_name, 'tab_categories', NULL);

    INSERT INTO tab_categories (id, name, slug, parent_id, is_active, usr_insert)
    VALUES (v_id, trim(p_name), v_slug, p_parent_id, COALESCE(p_is_active, TRUE), v_usr);

    IF FOUND THEN
        RETURN 'Categoría insertada correctamente. Id: ' || v_id;
    ELSE
        RETURN 'Error al insertar la categoría';
    END IF;
EXCEPTION
    WHEN unique_violation THEN
        RETURN 'Error: Slug duplicado.';
    WHEN foreign_key_violation THEN
        RETURN 'Error: Violación de integridad referencial.';
    WHEN OTHERS THEN
        RETURN 'Error: ' || SQLERRM;
END;
$$;


--
-- Name: fun_insert_comentarios(numeric, numeric, numeric, character varying, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_insert_comentarios(wid_producto numeric, wid_usuario numeric, wid_orden numeric, wcomentario character varying, wcalificacion integer, wusr_operacion numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_comentario DECIMAL(10);
BEGIN
    IF wusr_operacion IS NULL OR wusr_operacion <= 0 THEN
        RETURN 'Error: El usuario de operación es obligatorio.';
    END IF;
    IF wid_producto IS NULL OR wid_producto <= 0 THEN
        RETURN 'Error: El product_id es obligatorio.';
    END IF;
    IF wid_usuario IS NULL OR wid_usuario <= 0 THEN
        RETURN 'Error: El ID de usuario es obligatorio.';
    END IF;
    IF wcomentario IS NULL OR trim(wcomentario) = '' OR length(trim(wcomentario)) < 3 THEN
        RETURN 'Error: El comentario debe tener al menos 3 caracteres.';
    END IF;
    IF wcalificacion IS NULL OR wcalificacion < 1 OR wcalificacion > 5 THEN
        RETURN 'Error: La calificación debe estar entre 1 y 5.';
    END IF;
    IF wid_orden IS NULL OR wid_orden <= 0 THEN
        RETURN 'Error: El ID de orden es obligatorio.';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM tab_ordenes
        WHERE id_orden = wid_orden AND id_usuario = wid_usuario AND ind_estado IN (2, 3)
    ) THEN
        RETURN 'Error: La orden no existe, no te pertenece o no está en estado válido para reseñar';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM tab_orden_productos op
        JOIN tab_product_variant_combinations pv ON pv.id = op.variant_id
        JOIN tab_product_variant_groups g ON g.id = pv.group_id
        WHERE op.id_orden = wid_orden AND g.product_id = wid_producto
    ) THEN
        RETURN 'Error: El producto no está incluido en esta orden';
    END IF;

    IF EXISTS (
        SELECT 1 FROM tab_comentarios
        WHERE product_id = wid_producto AND id_usuario = wid_usuario AND id_orden = wid_orden AND ind_activo = TRUE
    ) THEN
        RETURN 'Error: Ya has reseñado este producto en esta orden';
    END IF;

    v_id_comentario := (SELECT COALESCE(MAX(id_comentario), 0) + 1 FROM tab_comentarios);
    INSERT INTO tab_comentarios (id_comentario, product_id, id_usuario, id_orden, comentario, calificacion, usr_insert, fec_insert)
    VALUES (v_id_comentario, wid_producto, wid_usuario, wid_orden, trim(wcomentario), wcalificacion, wusr_operacion, NOW());

    IF FOUND THEN
        RETURN 'Comentario insertado correctamente';
    ELSE
        RETURN 'Error al insertar el comentario';
    END IF;
EXCEPTION
    WHEN foreign_key_violation THEN
        RETURN 'Error: Referencia a producto o usuario inexistente';
    WHEN unique_violation THEN
        RETURN 'Error: Ya existe una reseña para este producto en esta orden';
    WHEN OTHERS THEN
        RETURN 'Error: ' || SQLERRM;
END;
$$;


--
-- Name: fun_insert_content(character varying, jsonb, integer, boolean, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_insert_content(wnom_cms_content character varying, wdes_cms_content jsonb, wnum_version integer, wind_publicado boolean, wusr_operacion numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
    BEGIN
        -- VALIDACIÓN 1: Nombre del contenido
        IF wnom_cms_content IS NULL OR wnom_cms_content = '' THEN
            RETURN 'Error: El nombre del contenido es obligatorio y no puede estar vacío.';
        END IF;

        -- VALIDACIÓN 2: Usuario operación para auditoría
        IF wusr_operacion IS NULL OR wusr_operacion = '' THEN
            RETURN 'Error: El usuario que realiza la operación es obligatorio para auditoría.';
        END IF;

        -- INSERCIÓN: Crear contenido CMS
        INSERT INTO tab_cms_content (
            nom_cms_content,            -- Nombre del contenido
            des_cms_content,            -- Descripción del contenido
            num_version,                -- Número de versión
            ind_publicado,              -- Indicador de publicación
            usr_insert                  -- Usuario que realiza la inserción
        )
        VALUES (wnom_cms_content, wdes_cms_content, wnum_version, wind_publicado, wusr_operacion);

        -- VERIFICACIÓN: Confirmar éxito de la inserción
        IF FOUND THEN
            RETURN 'Contenido CMS insertado correctamente';
        ELSE
            RETURN 'Error al insertar el contenido CMS';
        END IF;

    -- MANEJO DE ERRORES: Capturar excepciones específicas
    EXCEPTION
        WHEN SQLSTATE '23502' THEN
            RETURN 'Error: Faltan campos obligatorios del contenido.';
        WHEN OTHERS THEN
            RETURN 'Error inesperado: ' || SQLERRM;
            ROLLBACK;
    END;
$$;


--
-- Name: fun_insert_descuento(character varying, character varying, boolean, numeric, numeric, character varying, numeric, numeric, numeric, numeric, boolean, date, date, boolean, integer, integer, boolean, character varying, integer, character varying, time without time zone, time without time zone, boolean, numeric, integer, boolean, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_insert_descuento(p_nom_descuento character varying, p_des_descuento character varying, p_tipo_calculo boolean, p_val_porce_descuento numeric, p_val_monto_descuento numeric, p_aplica_a character varying, p_category_id_aplica numeric, p_product_id_aplica numeric, p_id_marca_aplica numeric, p_min_valor_pedido numeric, p_ind_es_para_cumpleanos boolean, p_fec_inicio date, p_fec_fin date, p_ind_activo boolean, p_max_usos_total integer, p_costo_puntos_canje integer, p_ind_canjeable_puntos boolean, p_codigo_descuento character varying, p_max_usos_por_usuario integer, p_dias_semana_aplica character varying, p_horas_inicio time without time zone, p_horas_fin time without time zone, p_solo_primera_compra boolean, p_monto_minimo_producto numeric, p_cantidad_minima_producto integer, p_requiere_codigo boolean, p_usr_operacion numeric, p_id_usuario_destino numeric DEFAULT NULL::numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_nuevo_id DECIMAL(10);
BEGIN
    IF p_nom_descuento IS NULL OR LENGTH(TRIM(p_nom_descuento)) < 3 THEN
        RETURN json_build_object('success', false, 'message', 'El nombre del descuento debe tener al menos 3 caracteres');
    END IF;
    IF (p_fec_inicio IS NULL AND p_fec_fin IS NOT NULL) OR (p_fec_inicio IS NOT NULL AND p_fec_fin IS NULL) THEN
        RETURN json_build_object('success', false, 'message', 'Debe especificar ambas fechas o ninguna');
    END IF;
    IF p_fec_inicio IS NOT NULL AND p_fec_fin IS NOT NULL AND p_fec_fin < p_fec_inicio THEN
        RETURN json_build_object('success', false, 'message', 'La fecha de fin debe ser mayor o igual a la fecha de inicio');
    END IF;
    IF p_codigo_descuento IS NOT NULL AND EXISTS (SELECT 1 FROM tab_descuentos WHERE codigo_descuento = p_codigo_descuento) THEN
        RETURN json_build_object('success', false, 'message', 'El código de descuento ya existe');
    END IF;
    IF (p_horas_inicio IS NOT NULL AND p_horas_fin IS NULL) OR (p_horas_inicio IS NULL AND p_horas_fin IS NOT NULL) THEN
        RETURN json_build_object('success', false, 'message', 'Si especifica horarios, debe incluir tanto hora de inicio como de fin');
    END IF;

    CASE p_aplica_a
        WHEN 'producto_especifico' THEN
            IF p_product_id_aplica IS NULL THEN
                RETURN json_build_object('success', false, 'message', 'Para descuentos de producto específico se requiere product_id_aplica');
            END IF;
        WHEN 'categoria_especifica' THEN
            IF p_category_id_aplica IS NULL THEN
                RETURN json_build_object('success', false, 'message', 'Para descuentos de categoría específica se requiere category_id_aplica');
            END IF;
        WHEN 'marca_especifica' THEN
            IF p_id_marca_aplica IS NULL THEN
                RETURN json_build_object('success', false, 'message', 'Para descuentos de marca específica se requiere id_marca_aplica');
            END IF;
        WHEN 'linea_especifica', 'sublinea_especifica' THEN
            IF p_category_id_aplica IS NULL THEN
                RETURN json_build_object('success', false, 'message', 'Para linea/sublinea use category_id_aplica (categoría)');
            END IF;
        WHEN 'total_pedido', 'costo_envio', 'envio_gratis', 'segunda_unidad', 'compra_minima' THEN
            NULL;
        ELSE
            RETURN json_build_object('success', false, 'message', 'Tipo de aplicación no válido: ' || p_aplica_a);
    END CASE;

    SELECT COALESCE(MAX(id_descuento), 0) + 1 INTO v_nuevo_id FROM tab_descuentos;

    INSERT INTO tab_descuentos (
        id_descuento, nom_descuento, des_descuento, tipo_calculo,
        val_porce_descuento, val_monto_descuento, aplica_a,
        category_id_aplica, product_id_aplica, id_marca_aplica,
        min_valor_pedido, ind_es_para_cumpleanos,
        fec_inicio, fec_fin, ind_activo,
        max_usos_total, costo_puntos_canje, ind_canjeable_puntos,
        codigo_descuento, max_usos_por_usuario, dias_semana_aplica,
        horas_inicio, horas_fin,
        solo_primera_compra, monto_minimo_producto, cantidad_minima_producto, requiere_codigo,
        id_usuario_destino,
        usr_insert, fec_insert
    ) VALUES (
        v_nuevo_id,
        p_nom_descuento,
        p_des_descuento,
        p_tipo_calculo,
        COALESCE(p_val_porce_descuento, 0),
        COALESCE(p_val_monto_descuento, 0),
        p_aplica_a,
        p_category_id_aplica,
        p_product_id_aplica,
        p_id_marca_aplica,
        COALESCE(p_min_valor_pedido, 0),
        COALESCE(p_ind_es_para_cumpleanos, FALSE),
        p_fec_inicio,
        p_fec_fin,
        COALESCE(p_ind_activo, TRUE),
        p_max_usos_total,
        p_costo_puntos_canje,
        COALESCE(p_ind_canjeable_puntos, FALSE),
        p_codigo_descuento,
        p_max_usos_por_usuario,
        p_dias_semana_aplica,
        p_horas_inicio,
        p_horas_fin,
        COALESCE(p_solo_primera_compra, FALSE),
        COALESCE(p_monto_minimo_producto, 0),
        COALESCE(p_cantidad_minima_producto, 1),
        COALESCE(p_requiere_codigo, FALSE),
        p_id_usuario_destino,
        p_usr_operacion,
        NOW()
    );

    RETURN json_build_object('success', true, 'message', 'Descuento creado exitosamente', 'id_descuento', v_nuevo_id);
EXCEPTION
    WHEN foreign_key_violation THEN
        RETURN json_build_object('success', false, 'message', 'Error: Referencia a categoría, producto o marca inexistente');
    WHEN check_violation THEN
        RETURN json_build_object('success', false, 'message', 'Error: Valores fuera de rango permitido');
    WHEN OTHERS THEN
        RETURN json_build_object('success', false, 'message', 'Error inesperado: ' || SQLERRM);
END;
$$;


--
-- Name: fun_insert_direcciones(numeric, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, boolean, boolean, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_insert_direcciones(wid_usuario numeric, wnom_direccion character varying, wcalle_direccion character varying, wciudad character varying, wdepartamento character varying, wcodigo_postal character varying, wbarrio character varying, wreferencias character varying, wcomplemento character varying, wind_principal boolean, wind_activa boolean, wusr_operacion numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- VALIDACIÓN 1: ID de usuario
    IF wid_usuario IS NULL OR wid_usuario = 0 THEN
        RETURN 'Error: El ID de usuario es obligatorio y debe ser mayor a 0.';
    END IF;

    -- VALIDACIÓN 2: Nombre de la dirección
    IF wnom_direccion IS NULL OR wnom_direccion = '' OR LENGTH(TRIM(wnom_direccion)) < 3 THEN
        RETURN 'Error: El nombre de la dirección es obligatorio y debe tener al menos 3 caracteres.';
    END IF;

    -- VALIDACIÓN 3: Dirección completa de la calle
    IF wcalle_direccion IS NULL OR wcalle_direccion = '' OR LENGTH(TRIM(wcalle_direccion)) < 5 THEN
        RETURN 'Error: La calle de la dirección es obligatoria y debe tener al menos 5 caracteres.';
    END IF;

    -- VALIDACIÓN 4: Ciudad
    IF wciudad IS NULL OR wciudad = '' OR LENGTH(TRIM(wciudad)) < 3 THEN
        RETURN 'Error: La ciudad es obligatoria y debe tener al menos 3 caracteres.';
    END IF;

    -- VALIDACIÓN 5: Departamento/Estado
    IF wdepartamento IS NULL OR wdepartamento = '' OR LENGTH(TRIM(wdepartamento)) < 3 THEN
        RETURN 'Error: El departamento/estado es obligatorio y debe tener al menos 3 caracteres.';
    END IF;

    -- VALIDACIÓN 6: Código postal
    IF wcodigo_postal IS NULL OR wcodigo_postal = '' OR LENGTH(TRIM(wcodigo_postal)) < 3 THEN
        RETURN 'Error: El código postal es obligatorio y debe tener al menos 3 caracteres.';
    END IF;

    -- VALIDACIÓN 7: Barrio/Sector
    IF wbarrio IS NULL OR wbarrio = '' OR LENGTH(TRIM(wbarrio)) < 3 THEN
        RETURN 'Error: El barrio/sector es obligatorio y debe tener al menos 3 caracteres.';
    END IF;

    -- VALIDACIÓN 8: usr_operacion
    IF wusr_operacion IS NULL OR wusr_operacion <= 0 THEN
        RETURN 'Error: El ID del usuario que realiza la operación es obligatorio y debe ser mayor a 0.';
    END IF;

    --INSERCIÓN: Crear nueva dirección de usuario con ID secuencial
    INSERT INTO tab_direcciones_usuario (
        id_direccion, id_usuario, nombre_direccion, calle_direccion, 
        ciudad, departamento, codigo_postal, barrio, referencias, 
        complemento, ind_principal, ind_activa, usr_insert
    )
    VALUES (
        (SELECT COALESCE(MAX(id_direccion), 0) + 1 FROM tab_direcciones_usuario),  -- id_direccion global único
        wid_usuario,                                                                    -- id_usuario
        wnom_direccion,                                                                -- nombre_direccion
        wcalle_direccion,                                                              -- calle_direccion
        wciudad,                                                                       -- ciudad
        wdepartamento,                                                                 -- departamento
        wcodigo_postal,                                                                -- codigo_postal
        wbarrio,                                                                       -- barrio
        wreferencias,                                                                  -- referencias
        wcomplemento,                                                                  -- complemento
        wind_principal,                                                                -- ind_principal
        wind_activa,                                                                  -- ind_activa
        wusr_operacion                                                                -- usr_insert
    );

    -- VERIFICACIÓN: Confirmar que la inserción fue exitosa
    IF FOUND THEN
        RAISE NOTICE 'Dirección insertada exitosamente: % por usuario ID: %', wnom_direccion, wusr_operacion;
        RETURN 'Dirección insertada correctamente';
    ELSE
        RAISE NOTICE 'Error: No se pudo insertar la dirección';
        RETURN 'Error al insertar la dirección';
    END IF;

    -- MANEJO DE ERRORES: Capturar excepciones específicas
EXCEPTION
    WHEN SQLSTATE '23503' THEN
        RETURN 'Error: El usuario especificado no existe o está inactivo.';
    WHEN OTHERS THEN
        RETURN 'Error inesperado: ' || SQLERRM;
        ROLLBACK;
END;
$$;


--
-- Name: fun_insert_favorito(numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_insert_favorito(p_id_usuario numeric, p_product_id numeric, p_usr_operacion numeric DEFAULT NULL::numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_usr DECIMAL(10);
BEGIN
    IF p_id_usuario IS NULL OR p_product_id IS NULL THEN
        RETURN 'Error: id_usuario y product_id son obligatorios.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM tab_products WHERE id = p_product_id) THEN
        RETURN 'Error: El producto no existe.';
    END IF;
    v_usr := COALESCE(p_usr_operacion, p_id_usuario);
    INSERT INTO tab_favoritos (id_usuario, product_id, usr_insert, fec_insert)
    VALUES (p_id_usuario, p_product_id, v_usr, NOW());
    RETURN 'Favorito agregado correctamente';
EXCEPTION
    WHEN unique_violation THEN
        RETURN 'Error: El producto ya está en favoritos.';
    WHEN foreign_key_violation THEN
        RETURN 'Error: Usuario o producto no existe.';
    WHEN OTHERS THEN
        RETURN 'Error: ' || SQLERRM;
END;
$$;


--
-- Name: fun_insert_marca(character varying, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_insert_marca(wnom_marca character varying, wusr_operacion numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
    BEGIN
        -- VALIDACIÓN 1: Nombre de marca obligatorio y con longitud mínima
        IF wnom_marca IS NULL OR wnom_marca = '' OR LENGTH(TRIM(wnom_marca)) < 1 THEN
            RETURN 'Error: El nombre de la marca es obligatorio y debe tener al menos 1 carácter.';
        END IF;

        -- VALIDACIÓN 2: ID de usuario operación para auditoría
        IF wusr_operacion IS NULL OR wusr_operacion <= 0 THEN
            RETURN 'Error: El ID del usuario que realiza la operación es obligatorio y debe ser mayor a 0.';
        END IF;

        -- INSERCIÓN: Crear nueva marca con ID secuencial automático
        INSERT INTO tab_marcas (id_marca, nom_marca, usr_insert)
        VALUES (
            (SELECT COALESCE(MAX(tm.id_marca), 0) + 1 FROM tab_marcas tm),  -- ID generado automáticamente
            wnom_marca,                                                    -- Nombre de la marca
            wusr_operacion                                                  -- ID del usuario que realiza la inserción
        );

        -- VERIFICACIÓN: Confirmar que la inserción fue exitosa
        IF FOUND THEN
            RAISE NOTICE 'Marca insertada exitosamente: % por usuario ID: %', wnom_marca, wusr_operacion;
            RETURN 'Marca insertada correctamente';
        ELSE
            RAISE NOTICE 'Error: No se pudo insertar la marca';
            RETURN 'Error al insertar la marca';
        END IF;

    -- MANEJO DE ERRORES: Capturar excepciones específicas
    EXCEPTION
        WHEN OTHERS THEN
            RETURN 'Error inesperado: ' || SQLERRM;
            ROLLBACK;
    END;
$$;


--
-- Name: fun_insert_orden_compra_proveedor(numeric, numeric, date, character varying, numeric, numeric, integer, integer, numeric, numeric, character varying, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_insert_orden_compra_proveedor(p_id_orden_compra numeric, p_id_proveedor numeric, p_fec_esperada_entrega date, p_observaciones_orden character varying, p_product_id numeric, p_variant_id numeric, p_cantidad_solicitada integer, p_cantidad_recibida integer, p_costo_unitario numeric, p_ind_estado_producto numeric, p_observaciones_producto character varying, p_usr_operacion numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_orden_compra tab_orden_compra_proveedor.id_orden_compra%TYPE;
    v_proveedor_existe BOOLEAN := FALSE;
    v_producto_existe BOOLEAN := FALSE;
    v_variant_valida BOOLEAN := TRUE;
    v_producto_nombre tab_products.name%TYPE;
    v_inicio_proceso TIMESTAMP := NOW();
BEGIN
    -- GENERACIÓN AUTOMÁTICA DE ID_ORDEN_COMPRA si no se proporciona
    IF p_id_orden_compra IS NULL THEN
        SELECT COALESCE(MAX(id_orden_compra), 0) + 1
        FROM tab_orden_compra_proveedor
        INTO v_id_orden_compra;
    ELSE
        v_id_orden_compra := p_id_orden_compra;
    END IF;

    -- VALIDACIÓN 1: Parámetros obligatorios
    IF v_id_orden_compra <= 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Error al generar ID de orden de compra',
            'campo_error', 'id_orden_compra'
        );
    END IF;

    IF p_id_proveedor IS NULL OR p_id_proveedor <= 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El ID del proveedor es obligatorio y debe ser mayor a 0',
            'campo_error', 'id_proveedor'
        );
    END IF;

    IF p_fec_esperada_entrega IS NULL OR p_fec_esperada_entrega <= CURRENT_DATE THEN
        RETURN json_build_object(
            'success', false,
            'message', 'La fecha esperada de entrega debe ser posterior a la fecha actual',
            'campo_error', 'fec_esperada_entrega'
        );
    END IF;

    IF p_product_id IS NULL OR p_product_id <= 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El ID del producto es obligatorio y debe ser mayor a 0',
            'campo_error', 'product_id'
        );
    END IF;

    IF p_cantidad_solicitada IS NULL OR p_cantidad_solicitada <= 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'La cantidad solicitada es obligatoria y debe ser mayor a 0',
            'campo_error', 'cantidad_solicitada'
        );
    END IF;

    IF p_costo_unitario IS NULL OR p_costo_unitario <= 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El costo unitario es obligatorio y debe ser mayor a 0',
            'campo_error', 'costo_unitario'
        );
    END IF;

    IF p_usr_operacion IS NULL THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El usuario que realiza la operación es obligatorio para auditoría',
            'campo_error', 'usr_operacion'
        );
    END IF;

    -- VALIDACIÓN 2: Verificar que el proveedor existe
    SELECT EXISTS(
        SELECT 1 FROM tab_proveedores
        WHERE id_proveedor = p_id_proveedor
          AND ind_activo = TRUE
    ) INTO v_proveedor_existe;

    IF NOT v_proveedor_existe THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El proveedor especificado no existe o está inactivo',
            'campo_error', 'id_proveedor',
            'id_proveedor', p_id_proveedor
        );
    END IF;

    -- VALIDACIÓN 3: Verificar que el producto existe (tabla tab_products)
    SELECT EXISTS(
        SELECT 1 FROM tab_products p
        WHERE p.id = p_product_id
          AND p.is_active = TRUE
    ) INTO v_producto_existe;

    IF v_producto_existe THEN
        SELECT p.name FROM tab_products p WHERE p.id = p_product_id INTO v_producto_nombre;
    END IF;

    -- Si se indicó variante, validar que exista y pertenezca al producto
    IF p_variant_id IS NOT NULL AND p_variant_id > 0 THEN
        SELECT EXISTS(
            SELECT 1 FROM tab_product_variant_combinations c
            JOIN tab_product_variant_groups g ON g.id = c.group_id
            WHERE c.id = p_variant_id
              AND g.product_id = p_product_id
              AND c.is_active = TRUE
        ) INTO v_variant_valida;
        IF NOT v_variant_valida THEN
            RETURN json_build_object(
                'success', false,
                'message', 'La variante no existe, no pertenece al producto o está inactiva',
                'campo_error', 'variant_id',
                'product_id', p_product_id,
                'variant_id', p_variant_id
            );
        END IF;
    END IF;

    -- SI EL PRODUCTO NO EXISTE: Retornar instrucciones
    IF NOT v_producto_existe THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El producto especificado no existe. Debe crearlo primero.',
            'producto_existe', false,
            'accion_requerida', 'CREAR_PRODUCTO_PRIMERO',
            'producto_solicitado', json_build_object('product_id', p_product_id),
            'instrucciones', 'Cree el producto en la tabla tab_products antes de generar la orden de compra'
        );
    END IF;

    -- VALIDACIÓN 4: Verificar que no exista duplicado (PK id_orden_compra)
    IF EXISTS(
        SELECT 1 FROM tab_orden_compra_proveedor
        WHERE id_orden_compra = v_id_orden_compra
    ) THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Ya existe una orden de compra con el ID especificado',
            'campo_error', 'orden_duplicada',
            'id_orden_compra', v_id_orden_compra
        );
    END IF;

    -- INSERCIÓN: Crear orden de compra a proveedor (schema: product_id, variant_id)
    INSERT INTO tab_orden_compra_proveedor (
        id_orden_compra,
        id_proveedor,
        fec_esperada_entrega,
        observaciones_orden,
        product_id,
        variant_id,
        cantidad_solicitada,
        cantidad_recibida,
        costo_unitario,
        ind_estado_producto,
        observaciones_producto,
        usr_insert
    ) VALUES (
        v_id_orden_compra,
        p_id_proveedor,
        p_fec_esperada_entrega,
        p_observaciones_orden,
        p_product_id,
        p_variant_id,
        p_cantidad_solicitada,
        COALESCE(p_cantidad_recibida, 0),
        p_costo_unitario,
        COALESCE(p_ind_estado_producto, 1),
        p_observaciones_producto,
        p_usr_operacion
    );

    -- RESULTADO EXITOSO
    RETURN json_build_object(
        'success', true,
        'message', 'Orden de compra a proveedor creada exitosamente',
        'id_orden_compra', v_id_orden_compra,
        'id_orden_compra_generado', CASE WHEN p_id_orden_compra IS NULL THEN true ELSE false END,
        'producto_existe', true,
        'producto_info', json_build_object(
            'product_id', p_product_id,
            'variant_id', p_variant_id,
            'nombre', v_producto_nombre,
            'cantidad_solicitada', p_cantidad_solicitada,
            'costo_unitario', p_costo_unitario,
            'subtotal', p_cantidad_solicitada * p_costo_unitario
        ),
        'tiempo_procesamiento', (NOW() - v_inicio_proceso),
        'timestamp', NOW()
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Error inesperado al crear orden de compra: ' || SQLERRM,
            'sql_state', SQLSTATE,
            'tiempo_procesamiento', (NOW() - v_inicio_proceso)
        );
END;
$$;


--
-- Name: fun_insert_product_image(numeric, character varying, boolean, integer, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_insert_product_image(p_product_id numeric, p_image_url character varying, p_is_main boolean DEFAULT false, p_sort_order integer DEFAULT 0, p_usr_operacion numeric DEFAULT NULL::numeric, p_variant_id numeric DEFAULT NULL::numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id BIGINT;
    v_group_id BIGINT;
BEGIN
    IF p_product_id IS NULL OR NOT EXISTS (SELECT 1 FROM tab_products WHERE id = p_product_id) THEN
        RETURN 'Error: product_id obligatorio y debe existir.';
    END IF;
    IF p_image_url IS NULL OR trim(p_image_url) = '' THEN
        RETURN 'Error: image_url obligatorio.';
    END IF;

    IF p_variant_id IS NOT NULL THEN
        SELECT group_id INTO v_group_id FROM tab_product_variant_combinations WHERE id = p_variant_id LIMIT 1;
        IF v_group_id IS NULL THEN
            RETURN 'Error: variant_id (combination) no existe.';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM tab_product_variant_groups WHERE id = v_group_id AND product_id = p_product_id) THEN
            RETURN 'Error: la combinación no pertenece al producto.';
        END IF;
    ELSE
        SELECT id INTO v_group_id FROM tab_product_variant_groups WHERE product_id = p_product_id AND dominant_value = 'Sin color' LIMIT 1;
        IF v_group_id IS NULL THEN
            INSERT INTO tab_product_variant_groups (product_id, dominant_attribute, dominant_value, is_active, usr_insert, fec_insert)
            VALUES (p_product_id, 'color', 'Sin color', TRUE, COALESCE(p_usr_operacion, 0), NOW())
            RETURNING id INTO v_group_id;
        END IF;
    END IF;

    IF p_is_main THEN
        UPDATE tab_product_variant_images SET is_primary = FALSE WHERE variant_group_id = v_group_id;
    END IF;

    INSERT INTO tab_product_variant_images (variant_group_id, image_url, is_primary, sort_order, usr_insert, fec_insert)
    VALUES (v_group_id, trim(p_image_url), COALESCE(p_is_main, FALSE), COALESCE(p_sort_order, 0), COALESCE(p_usr_operacion, 0), NOW())
    RETURNING id INTO v_id;
    RETURN 'OK:' || v_id;
EXCEPTION
    WHEN OTHERS THEN RETURN 'Error: ' || SQLERRM;
END;
$$;


--
-- Name: fun_insert_product_variant(numeric, numeric, integer, character varying, boolean, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_insert_product_variant(p_product_id numeric, p_price numeric, p_stock integer DEFAULT 0, p_sku character varying DEFAULT NULL::character varying, p_is_active boolean DEFAULT true, p_usr_operacion numeric DEFAULT NULL::numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_group_id BIGINT;
    v_id DECIMAL(10);
    v_sku VARCHAR;
    v_usr DECIMAL(10);
BEGIN
    v_usr := COALESCE(p_usr_operacion, 0);
    IF p_product_id IS NULL OR NOT EXISTS (SELECT 1 FROM tab_products WHERE id = p_product_id) THEN
        RETURN 'Error: product_id obligatorio y debe existir.';
    END IF;
    IF p_price IS NULL OR p_price < 0 THEN
        RETURN 'Error: price obligatorio y >= 0.';
    END IF;
    IF p_stock IS NULL OR p_stock < 0 THEN
        RETURN 'Error: stock debe ser >= 0.';
    END IF;

    INSERT INTO tab_product_variant_groups (product_id, dominant_attribute, dominant_value, is_active, usr_insert, fec_insert)
    VALUES (p_product_id, 'color', 'Sin color', TRUE, v_usr, NOW())
    ON CONFLICT (product_id, dominant_value) DO UPDATE SET is_active = TRUE, fec_update = NOW()
    RETURNING id INTO v_group_id;
    IF v_group_id IS NULL THEN
        SELECT id INTO v_group_id FROM tab_product_variant_groups WHERE product_id = p_product_id AND dominant_value = 'Sin color' LIMIT 1;
    END IF;

    v_sku := fun_generate_sku(p_product_id, nullif(trim(p_sku), ''));
    IF length(v_sku) >= 120 THEN
        RETURN 'Error: SKU no debe superar 119 caracteres.';
    END IF;

    v_id := (SELECT COALESCE(MAX(id), 0) + 1 FROM tab_product_variant_combinations);
    INSERT INTO tab_product_variant_combinations (id, group_id, sku, price, stock, attributes, is_active, usr_insert, fec_insert)
    VALUES (v_id, v_group_id, v_sku, p_price, COALESCE(p_stock, 0), '{}'::JSONB, COALESCE(p_is_active, TRUE), v_usr, NOW());

    RETURN 'OK:' || v_id;
EXCEPTION
    WHEN unique_violation THEN RETURN 'Error: SKU duplicado.';
    WHEN OTHERS THEN RETURN 'Error: ' || SQLERRM;
END;
$$;


--
-- Name: fun_insert_producto(numeric, character varying, text, numeric, boolean, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_insert_producto(p_category_id numeric, p_name character varying, p_description text DEFAULT NULL::text, p_id_marca numeric DEFAULT NULL::numeric, p_is_active boolean DEFAULT true, p_usr_operacion numeric DEFAULT NULL::numeric, p_id_proveedor numeric DEFAULT NULL::numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id DECIMAL(10);
    v_slug VARCHAR;
    v_usr DECIMAL(10);
BEGIN
    v_usr := COALESCE(p_usr_operacion, 0);
    IF p_category_id IS NULL OR NOT EXISTS (SELECT 1 FROM tab_categories WHERE id = p_category_id) THEN
        RETURN 'Error: category_id obligatorio y debe existir.';
    END IF;
    IF p_name IS NULL OR length(trim(p_name)) < 2 THEN
        RETURN 'Error: El nombre es obligatorio (mín. 2 caracteres).';
    END IF;
    IF p_id_marca IS NOT NULL AND NOT EXISTS (SELECT 1 FROM tab_marcas WHERE id_marca = p_id_marca) THEN
        RETURN 'Error: id_marca no existe.';
    END IF;
    IF p_id_proveedor IS NOT NULL AND NOT EXISTS (SELECT 1 FROM tab_proveedores WHERE id_proveedor = p_id_proveedor) THEN
        RETURN 'Error: id_proveedor no existe.';
    END IF;

    v_id := (SELECT COALESCE(MAX(id), 0) + 1 FROM tab_products);
    v_slug := fun_generate_unique_slug(p_name, 'tab_products', NULL);

    INSERT INTO tab_products (id, category_id, name, slug, description, id_marca, is_active, usr_insert, id_proveedor)
    VALUES (v_id, p_category_id, trim(p_name), v_slug, p_description, p_id_marca, COALESCE(p_is_active, TRUE), v_usr, p_id_proveedor);

    RETURN 'OK:' || v_id;
EXCEPTION
    WHEN unique_violation THEN RETURN 'Error: Slug duplicado.';
    WHEN OTHERS THEN RETURN 'Error: ' || SQLERRM;
END;
$$;


--
-- Name: fun_insert_proveedores(character varying, character varying, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_insert_proveedores(wnom_proveedor character varying, wemail character varying, wtel_proveedor numeric, wusr_operacion numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
    BEGIN
        -- VALIDACIÓN 1: Nombre del proveedor
        IF wnom_proveedor IS NULL OR wnom_proveedor = '' OR LENGTH(TRIM(wnom_proveedor)) < 3 THEN
            RETURN 'Error: El nombre del proveedor es obligatorio y debe tener al menos 3 caracteres.';
        END IF;

        -- VALIDACIÓN 2: Email del proveedor
        IF wemail IS NULL OR wemail = '' OR LENGTH(TRIM(wemail)) < 3 THEN
            RETURN 'Error: El email del proveedor es obligatorio y debe tener al menos 3 caracteres.';
        END IF;

        -- VALIDACIÓN 3: Teléfono del proveedor
        IF wtel_proveedor IS NULL OR wtel_proveedor = 0 THEN
            RETURN 'Error: El teléfono del proveedor es obligatorio y debe ser mayor a 0.';
        END IF;

        -- VALIDACIÓN 4: ID de usuario operación para auditoría
        IF wusr_operacion IS NULL OR wusr_operacion <= 0 THEN
            RETURN 'Error: El ID del usuario que realiza la operación es obligatorio y debe ser mayor a 0.';
        END IF;

        -- INSERCIÓN: Crear nuevo proveedor con ID secuencial
        INSERT INTO tab_proveedores (id_proveedor, nom_proveedor, email, tel_proveedor, usr_insert)
        VALUES (
            (SELECT COALESCE(MAX(tp.id_proveedor), 0) + 1 FROM tab_proveedores tp),  -- ID secuencial automático
            wnom_proveedor,                                     -- Nombre del proveedor
            wemail,                                             -- Email del proveedor
            wtel_proveedor,                                     -- Teléfono del proveedor
            wusr_operacion                                      -- ID del usuario que realiza la inserción
        );
        
        -- VERIFICACIÓN: Confirmar que la inserción fue exitosa
        IF FOUND THEN
            RAISE NOTICE 'Proveedor insertado exitosamente: % por usuario ID: %', wnom_proveedor, wusr_operacion;
            RETURN 'Proveedor insertado correctamente';
        ELSE
            RAISE NOTICE 'Error: No se pudo insertar el proveedor';
            RETURN 'Error al insertar el proveedor';
        END IF;
        
    -- MANEJO DE ERRORES: Capturar excepciones específicas
    EXCEPTION
        WHEN SQLSTATE '23505' THEN
            RETURN 'Error: El email del proveedor ya existe en el sistema.';
        WHEN OTHERS THEN
            RETURN 'Error inesperado: ' || SQLERRM;
            ROLLBACK;
    END;
$$;


--
-- Name: fun_insert_roles(character varying, character varying, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_insert_roles(wnom_rol character varying, wdes_rol character varying, wusr_operacion numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- VALIDACIÓN 1: Nombre del rol
    IF wnom_rol IS NULL OR wnom_rol = '' OR LENGTH(TRIM(wnom_rol)) < 3 THEN
        RETURN 'Error: El nombre del rol es obligatorio y debe tener al menos 3 caracteres.';
    END IF;

    -- VALIDACIÓN 2: ID de usuario operación para auditoría
    IF wusr_operacion IS NULL OR wusr_operacion <= 0 THEN
        RETURN 'Error: El ID del usuario que realiza la operación es obligatorio y debe ser mayor a 0.';
    END IF;

    -- INSERCIÓN: Crear nuevo rol con ID automático
    INSERT INTO tab_roles (id_rol, nom_rol, des_rol, usr_insert)
    VALUES (
        (SELECT COALESCE(MAX(id_rol), 0) + 1 FROM tab_roles),  -- ID generado automáticamente
        wnom_rol,                                               -- Nombre del rol
        wdes_rol,                                               -- Descripción del rol
        wusr_operacion                                          -- ID del usuario que realiza la inserción
    );

    -- VERIFICACIÓN: Confirmar éxito de la inserción
    IF FOUND THEN
        RAISE NOTICE 'Rol insertado exitosamente: % por usuario ID: %', wnom_rol, wusr_operacion;
        RETURN 'Rol insertado correctamente';
    ELSE
        RAISE NOTICE 'Error: No se pudo insertar el rol';
        RETURN 'Error al insertar el rol';
    END IF;

-- MANEJO DE ERRORES: Capturar excepciones específicas
EXCEPTION
    WHEN SQLSTATE '23503' THEN
        RETURN 'Error: Violación de integridad referencial.';
    WHEN OTHERS THEN
        RETURN 'Error inesperado: ' || SQLERRM;
        ROLLBACK;
END;
$$;


--
-- Name: fun_insert_usuarios(numeric, character varying, character varying, character varying, character varying, boolean, character varying, date, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_insert_usuarios(wid_usuario numeric, wnom_usuario character varying, wape_usuario character varying, wemail_usuario character varying, wpassword_usuario character varying, wind_genero boolean, wcel_usuario character varying, wfec_nacimiento date, usr_insert numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
    BEGIN
        -- VALIDACIÓN 1: Nombre del usuario
        IF wnom_usuario IS NULL OR wnom_usuario = '' OR LENGTH(TRIM(wnom_usuario)) < 3 THEN
            RETURN 'Error: El nombre del usuario es obligatorio y debe tener al menos 3 caracteres.';
        END IF;

        -- VALIDACIÓN 2: Apellido del usuario
        IF wape_usuario IS NULL OR wape_usuario = '' OR LENGTH(TRIM(wape_usuario)) < 3 THEN
            RETURN 'Error: El apellido del usuario es obligatorio y debe tener al menos 3 caracteres.';
        END IF;

        -- VALIDACIÓN 3: Email del usuario
        IF wemail_usuario IS NULL OR wemail_usuario = '' OR LENGTH(TRIM(wemail_usuario)) < 3 THEN
            RETURN 'Error: El email del usuario es obligatorio y debe tener al menos 3 caracteres.';
        END IF;

        -- VALIDACIÓN 4: Contraseña del usuario
        IF wpassword_usuario IS NULL OR wpassword_usuario = '' OR LENGTH(TRIM(wpassword_usuario)) < 3 THEN
            RETURN 'Error: La contraseña es obligatoria y debe tener al menos 3 caracteres.';
        END IF;

        -- VALIDACIÓN 5: Indicador de género
        IF wind_genero IS NULL THEN
            RETURN 'Error: El indicador de género es obligatorio.';
        END IF;

        -- VALIDACIÓN 6: Número de celular
        IF wcel_usuario IS NULL OR wcel_usuario = '' OR LENGTH(TRIM(wcel_usuario)) < 3 THEN
            RETURN 'Error: El número de celular es obligatorio y debe tener al menos 3 caracteres.';
        END IF;

        -- fec_nacimiento es opcional (puede ser NULL)

        -- INSERCIÓN: Crear nuevo usuario en la base de datos
        INSERT INTO tab_usuarios (
            id_usuario,       -- Identificación única
            nom_usuario,      -- Nombre
            ape_usuario,      -- Apellido
            email_usuario,    -- Correo electrónico
            password_usuario, -- Contraseña
            ind_genero,       -- Género
            cel_usuario,      -- Celular
            fec_nacimiento,  -- Fecha de nacimiento
            usr_insert        -- Usuario que insertó    
        )
        VALUES (
            wid_usuario, wnom_usuario, wape_usuario, wemail_usuario, wpassword_usuario,
            wind_genero, wcel_usuario, wfec_nacimiento, usr_insert
        );
        
        -- VERIFICACIÓN: Confirmar que la inserción fue exitosa
        IF FOUND THEN
            RAISE NOTICE 'Usuario insertado exitosamente: %', wnom_usuario;
            RETURN 'Usuario insertado correctamente';
        ELSE
            RAISE NOTICE 'Error: No se pudo insertar el usuario';
            RETURN 'Error al insertar el usuario';
        END IF;
    END;
$$;


--
-- Name: fun_insert_variant_combination(bigint, character varying, numeric, integer, jsonb, boolean, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_insert_variant_combination(p_group_id bigint, p_sku character varying DEFAULT NULL::character varying, p_price numeric DEFAULT 0, p_stock integer DEFAULT 0, p_attributes jsonb DEFAULT '{}'::jsonb, p_is_active boolean DEFAULT true, p_tipo_clasificacion character varying DEFAULT NULL::character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id DECIMAL(10);
    v_sku VARCHAR;
    v_product_id DECIMAL(10);
BEGIN
    IF p_group_id IS NULL OR NOT EXISTS (SELECT 1 FROM tab_product_variant_groups WHERE id = p_group_id) THEN
        RETURN 'Error: group_id obligatorio y debe existir.';
    END IF;
    SELECT product_id INTO v_product_id FROM tab_product_variant_groups WHERE id = p_group_id LIMIT 1;
    IF p_price IS NULL OR p_price < 0 THEN
        RETURN 'Error: price obligatorio y >= 0.';
    END IF;
    IF p_stock IS NULL OR p_stock < 0 THEN
        RETURN 'Error: stock debe ser >= 0.';
    END IF;
    v_sku := fun_generate_sku(v_product_id, nullif(trim(p_sku), ''));
    IF length(v_sku) >= 120 THEN
        RETURN 'Error: SKU no debe superar 119 caracteres.';
    END IF;
    v_id := (SELECT COALESCE(MAX(id), 0) + 1 FROM tab_product_variant_combinations);
    INSERT INTO tab_product_variant_combinations (id, group_id, sku, price, stock, attributes, is_active, tipo_clasificacion, usr_insert, fec_insert)
    VALUES (v_id, p_group_id, v_sku, p_price, COALESCE(p_stock, 0), COALESCE(p_attributes, '{}'::JSONB), COALESCE(p_is_active, TRUE), nullif(trim(p_tipo_clasificacion), ''), 0, NOW());
    RETURN 'OK:' || v_id;
EXCEPTION
    WHEN unique_violation THEN RETURN 'Error: SKU duplicado.';
    WHEN OTHERS THEN RETURN 'Error: ' || SQLERRM;
END;
$$;


--
-- Name: fun_insert_variant_group(numeric, character varying, character varying, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_insert_variant_group(p_product_id numeric, p_dominant_attribute character varying, p_dominant_value character varying, p_is_active boolean DEFAULT true) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id BIGINT;
BEGIN
    IF p_product_id IS NULL OR NOT EXISTS (SELECT 1 FROM tab_products WHERE id = p_product_id) THEN
        RETURN 'Error: product_id obligatorio y debe existir.';
    END IF;
    IF trim(p_dominant_attribute) = '' OR trim(p_dominant_value) = '' THEN
        RETURN 'Error: dominant_attribute y dominant_value obligatorios.';
    END IF;
    INSERT INTO tab_product_variant_groups (product_id, dominant_attribute, dominant_value, is_active, usr_insert, fec_insert)
    VALUES (p_product_id, trim(p_dominant_attribute), trim(p_dominant_value), COALESCE(p_is_active, TRUE), 0, NOW())
    ON CONFLICT (product_id, dominant_value) DO UPDATE SET
        is_active = EXCLUDED.is_active,
        fec_update = NOW()
    RETURNING id INTO v_id;
    RETURN 'OK:' || v_id;
EXCEPTION
    WHEN OTHERS THEN RETURN 'Error: ' || SQLERRM;
END;
$$;


--
-- Name: fun_insert_variant_group_image(bigint, character varying, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_insert_variant_group_image(p_variant_group_id bigint, p_image_url character varying, p_is_primary boolean DEFAULT false, p_sort_order integer DEFAULT 0) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id BIGINT;
BEGIN
    IF p_variant_group_id IS NULL OR NOT EXISTS (SELECT 1 FROM tab_product_variant_groups WHERE id = p_variant_group_id) THEN
        RETURN 'Error: variant_group_id obligatorio y debe existir.';
    END IF;
    IF p_image_url IS NULL OR trim(p_image_url) = '' THEN
        RETURN 'Error: image_url obligatorio.';
    END IF;
    IF p_is_primary THEN
        UPDATE tab_product_variant_images SET is_primary = FALSE WHERE variant_group_id = p_variant_group_id;
    END IF;
    INSERT INTO tab_product_variant_images (variant_group_id, image_url, is_primary, sort_order, usr_insert, fec_insert)
    VALUES (p_variant_group_id, trim(p_image_url), COALESCE(p_is_primary, FALSE), COALESCE(p_sort_order, 0), 0, NOW())
    ON CONFLICT (variant_group_id, image_url)
    DO UPDATE SET
        is_primary = EXCLUDED.is_primary,
        sort_order = EXCLUDED.sort_order,
        usr_update = 0,
        fec_update = NOW()
    RETURNING id INTO v_id;
    RETURN 'OK:' || v_id;
EXCEPTION
    WHEN OTHERS THEN RETURN 'Error: ' || SQLERRM;
END;
$$;


--
-- Name: fun_limpiar_carrito_pagado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_limpiar_carrito_pagado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_carrito_record RECORD;
    v_count_productos_eliminados INT := 0;
    v_count_carritos_limpiados INT := 0;
BEGIN
    -- VALIDACIÓN: El trigger solo se dispara en UPDATE (cuando orden pasa a Pagada).
    -- Las órdenes creadas ya como Pagada (INSERT ind_estado=2) no disparan este trigger;
    -- la limpieza del carrito en ese caso la hace fun_crear_orden_desde_carrito (PASO 12b).
    IF TG_OP != 'UPDATE' OR OLD.ind_estado = 2 OR NEW.ind_estado != 2 THEN
        RETURN NULL;
    END IF;
    
    -- LOG: Iniciar proceso de limpieza
    RAISE NOTICE 'Iniciando limpieza de carrito para orden PAGADA #% del usuario %', 
        NEW.id_orden, NEW.id_usuario;
    
    -- PASO 1: Obtener todos los carritos del usuario (puede tener múltiples)
    FOR v_carrito_record IN
        SELECT id_carrito
        FROM tab_carritos 
        WHERE id_usuario = NEW.id_usuario
    LOOP
        -- PASO 2: Contar productos antes de eliminar (para log)
        SELECT COUNT(*) INTO v_count_productos_eliminados
        FROM tab_carrito_productos 
        WHERE id_carrito = v_carrito_record.id_carrito;
        
        -- PASO 3: Solo proceder si el carrito tiene productos
        IF v_count_productos_eliminados > 0 THEN
            
            -- PASO 4: Eliminar todos los productos del carrito
            DELETE FROM tab_carrito_productos 
            WHERE id_carrito = v_carrito_record.id_carrito;
            
            -- PASO 5: Actualizar fecha de modificación del carrito (INSERT suele tener usr_update NULL)
            UPDATE tab_carritos 
            SET usr_update = COALESCE(NEW.usr_update, NEW.usr_insert)
            WHERE id_carrito = v_carrito_record.id_carrito;
            
            -- LOG: Registro por carrito limpiado
            RAISE NOTICE 'Carrito #% limpiado tras PAGO: % productos eliminados', 
                v_carrito_record.id_carrito, v_count_productos_eliminados;
                
            -- Contador de carritos procesados
            v_count_carritos_limpiados := v_count_carritos_limpiados + 1;
        ELSE
            -- LOG: Carrito ya estaba vacío
            RAISE NOTICE 'Carrito #% ya estaba vacío - no requiere limpieza', 
                v_carrito_record.id_carrito;
        END IF;
        
    END LOOP;
    
    -- VERIFICACIÓN: Si no se encontraron carritos, crear uno vacío para el usuario
    IF v_count_carritos_limpiados = 0 THEN
        -- Crear carrito vacío para futuras compras
        INSERT INTO tab_carritos (id_usuario, usr_insert)
        VALUES (NEW.id_usuario, COALESCE(NEW.usr_update, NEW.usr_insert));
        
        RAISE NOTICE 'Carrito vacío creado para usuario % tras PAGAR orden #%', 
            NEW.id_usuario, NEW.id_orden;
    END IF;
    
    -- LOG: Resumen final
    IF v_count_carritos_limpiados > 0 THEN
        RAISE NOTICE 'Limpieza completada tras PAGO: % carritos procesados para usuario % - orden #%', 
            v_count_carritos_limpiados, NEW.id_usuario, NEW.id_orden;
    ELSE
        RAISE NOTICE 'No se requirió limpieza de carrito para usuario % - orden PAGADA #%', 
            NEW.id_usuario, NEW.id_orden;
    END IF;
    
    -- RETORNO: NULL estándar para triggers AFTER
    RETURN NULL;

-- MANEJO DE ERRORES: Capturar excepciones y hacer rollback automático
EXCEPTION 
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Error en limpieza automática de carrito tras PAGO para usuario % - orden #%: %', 
            NEW.id_usuario, NEW.id_orden, SQLERRM;
END;
$$;


--
-- Name: fun_listar_descuentos(boolean, boolean, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_listar_descuentos(p_activos_solamente boolean DEFAULT NULL::boolean, p_incluir_vencidos boolean DEFAULT true, p_busqueda_texto character varying DEFAULT NULL::character varying, p_tipo_aplicacion character varying DEFAULT NULL::character varying, p_limit integer DEFAULT 20) RETURNS TABLE(id_descuento numeric, nom_descuento character varying, des_descuento character varying, tipo_calculo_texto character varying, valor_mostrar character varying, aplica_a character varying, fec_inicio date, fec_fin date, ind_activo boolean, codigo_descuento character varying, max_usos_total integer, usos_actuales_total integer, max_usos_por_usuario integer, estado_descuento character varying, porcentaje_uso character varying, cantidad_minima_producto integer, requiere_codigo boolean)
    LANGUAGE plpgsql
    AS $_$
BEGIN
    -- CONSULTA: Obtener descuentos con información calculada y filtros
    RETURN QUERY
    SELECT 
        d.id_descuento,                                         -- ID del descuento
        d.nom_descuento,                                        -- Nombre del descuento
        d.des_descuento,                                        -- Descripción del descuento
        CASE 
            WHEN d.tipo_calculo THEN 'Porcentaje'
            ELSE 'Monto Fijo'
        END AS tipo_calculo_texto,                              -- Tipo de cálculo legible
        CASE 
            WHEN d.tipo_calculo THEN 
                CONCAT(d.val_porce_descuento::TEXT, '%')
            ELSE 
                CONCAT('$', d.val_monto_descuento::TEXT)
        END AS valor_mostrar,                                   -- Valor formateado para mostrar
        d.aplica_a,                                             -- Tipo de aplicación
        d.fec_inicio,                                           -- Fecha de inicio
        d.fec_fin,                                              -- Fecha de fin
        d.ind_activo,                                           -- Indicador activo
        d.codigo_descuento,                                     -- Código del descuento
        d.max_usos_total,                                       -- Máximo usos total
        d.usos_actuales_total,                                  -- Usos actuales total
        d.max_usos_por_usuario,                                 -- Máximo usos por usuario
        CASE 
            WHEN NOT d.ind_activo THEN 'Inactivo'
            WHEN CURRENT_DATE < d.fec_inicio THEN 'Programado'
            WHEN CURRENT_DATE > d.fec_fin THEN 'Vencido'
            WHEN d.max_usos_total IS NOT NULL AND d.usos_actuales_total >= d.max_usos_total THEN 'Agotado'
            ELSE 'Activo'
        END AS estado_descuento,                                -- Estado calculado dinámicamente
        CASE 
            WHEN d.max_usos_total IS NOT NULL AND d.max_usos_total > 0 THEN
                CONCAT(ROUND((d.usos_actuales_total::DECIMAL / d.max_usos_total::DECIMAL) * 100, 1)::TEXT, '%')
            ELSE 'Ilimitado'
        END AS porcentaje_uso,                                   -- Porcentaje de uso calculado
        d.cantidad_minima_producto,                               -- Cantidad mínima del producto
        d.requiere_codigo                                          -- Requiere código
    FROM tab_descuentos d
    WHERE 
        -- FILTRO 1: Estado activo/inactivo
        (p_activos_solamente IS NULL OR d.ind_activo = p_activos_solamente)
        -- FILTRO 2: Incluir o excluir vencidos
        AND (p_incluir_vencidos = TRUE OR d.fec_fin >= CURRENT_DATE)
        -- FILTRO 3: Búsqueda de texto en nombre, descripción o código
        AND (p_busqueda_texto IS NULL OR 
            LOWER(d.nom_descuento) LIKE LOWER('%' || p_busqueda_texto || '%') OR
            LOWER(d.des_descuento) LIKE LOWER('%' || p_busqueda_texto || '%') OR
            LOWER(d.codigo_descuento) LIKE LOWER('%' || p_busqueda_texto || '%'))
        -- FILTRO 4: Tipo de aplicación específico
        AND (p_tipo_aplicacion IS NULL OR d.aplica_a = p_tipo_aplicacion)
    ORDER BY 
        -- ORDENAMIENTO: Por prioridad de estado (activos primero)
        CASE 
            WHEN d.ind_activo AND CURRENT_DATE BETWEEN d.fec_inicio AND d.fec_fin 
                AND (d.max_usos_total IS NULL OR d.usos_actuales_total < d.max_usos_total) THEN 1  -- Activos válidos
            WHEN d.ind_activo AND CURRENT_DATE < d.fec_inicio THEN 2                              -- Programados
            WHEN NOT d.ind_activo THEN 3                                                          -- Inactivos
            WHEN CURRENT_DATE > d.fec_fin THEN 4                                                  -- Vencidos
            ELSE 5                                                                                 -- Otros
        END,
        d.fec_insert DESC                                       -- Más recientes primero
    LIMIT p_limit;
END;
$_$;


--
-- Name: fun_listar_descuentos_canjeables(numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_listar_descuentos_canjeables(p_id_usuario numeric, p_limit integer DEFAULT 20) RETURNS TABLE(id_descuento numeric, nom_descuento character varying, des_descuento character varying, costo_puntos_canje integer, tipo_calculo_texto text, valor_descuento text, aplica_a character varying, fec_inicio date, fec_fin date, puede_canjear boolean, puntos_usuario integer)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_puntos_usuario INT := 0;
BEGIN
    -- PASO 1: Obtener puntos disponibles del usuario (si se especifica)
    IF p_id_usuario IS NOT NULL THEN
        -- Usar COALESCE para manejar casos donde el usuario no existe en tab_puntos_usuario
        SELECT COALESCE(
            (SELECT puntos_disponibles FROM tab_puntos_usuario WHERE id_usuario = p_id_usuario),
            0
        ) INTO v_puntos_usuario;
    END IF;
    
    -- CONSULTA: Obtener descuentos canjeables con validación de puntos
    RETURN QUERY
    SELECT 
        d.id_descuento,                                         -- ID del descuento
        d.nom_descuento,                                        -- Nombre del descuento
        d.des_descuento,                                        -- Descripción del descuento
        d.costo_puntos_canje,                                   -- Puntos requeridos para canje
        CASE 
            WHEN d.tipo_calculo THEN 'Porcentaje'
            ELSE 'Monto Fijo'
        END AS tipo_calculo_texto,                              -- Tipo de cálculo legible
        CASE 
            WHEN d.tipo_calculo THEN 
                CONCAT(d.val_porce_descuento::TEXT, '%')
            ELSE 
                CONCAT('$', d.val_monto_descuento::TEXT)
        END AS valor_descuento,                                 -- Valor del descuento formateado
        d.aplica_a,                                             -- Tipo de aplicación
        d.fec_inicio,                                           -- Fecha de inicio
        d.fec_fin,                                              -- Fecha de fin
        CASE 
            WHEN p_id_usuario IS NULL THEN NULL
            ELSE (v_puntos_usuario >= d.costo_puntos_canje)
        END AS puede_canjear,                                   -- Si el usuario puede canjearlo
        CASE 
            WHEN p_id_usuario IS NULL THEN NULL
            ELSE v_puntos_usuario
        END AS puntos_usuario                                   -- Puntos disponibles del usuario
    FROM tab_descuentos d
    WHERE d.ind_canjeable_puntos = TRUE                         -- Solo descuentos canjeables por puntos
      AND ( (d.fec_inicio IS NULL AND d.fec_fin IS NULL) OR (d.fec_inicio IS NOT NULL AND d.fec_fin IS NOT NULL AND CURRENT_DATE BETWEEN d.fec_inicio AND d.fec_fin) )
    ORDER BY d.costo_puntos_canje ASC, d.fec_insert DESC;       -- Más baratos primero, más recientes después                 -- Paginación
END;
$_$;


--
-- Name: fun_listar_metodos_pago(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_listar_metodos_pago(p_id_usuario numeric) RETURNS TABLE(id_metodo_pago integer, provider_name character varying, brand character varying, last_four_digits character varying, expiration_month integer, expiration_year integer, is_default boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        mpu.id_metodo_pago,
        mpu.provider_name,
        mpu.brand,
        mpu.last_four_digits,
        mpu.expiration_month,
        mpu.expiration_year,
        mpu.is_default
    FROM
        tab_metodos_pago_usuario mpu
    WHERE
        mpu.id_usuario = p_id_usuario
    ORDER BY
        mpu.is_default DESC, mpu.fec_insert DESC;
END;
$$;


--
-- Name: fun_marcar_orden_completada(numeric, character varying, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_marcar_orden_completada(p_id_orden numeric, p_observaciones character varying, p_usr_operacion numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_orden_record RECORD;
    v_estado_anterior tab_ordenes.ind_estado%TYPE;
BEGIN
    -- PASO 1: Validar y obtener información de la orden
    SELECT 
        id_orden, id_usuario, ind_estado, val_total_pedido,
        metodo_pago, fec_pedido
    INTO v_orden_record
    FROM tab_ordenes 
    WHERE id_orden = p_id_orden;
    
    -- Verificar que la orden existe
    IF v_orden_record.id_orden IS NULL THEN
        RETURN json_build_object(
            'success', false,
            'message', 'La orden especificada no existe',
            'id_orden', p_id_orden,
            'codigo_error', 'ORDEN_NO_ENCONTRADA'
        );
    END IF;
    
    v_estado_anterior := v_orden_record.ind_estado;
    
    -- PASO 2: Verificar que la orden esté en estado PAGADA
    IF v_orden_record.ind_estado != 2 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'La orden debe estar en estado PAGADA para poder completarse',
            'id_orden', p_id_orden,
            'estado_actual', v_orden_record.ind_estado,
            'estado_requerido', 2,
            'codigo_error', 'ESTADO_INVALIDO'
        );
    END IF;
    
    -- PASO 3: Marcar orden como completada
    UPDATE tab_ordenes 
    SET 
        ind_estado = 3,                              -- Estado COMPLETADA
        des_observaciones = COALESCE(p_observaciones, des_observaciones),
        usr_update = p_usr_operacion,
        fec_update = NOW()
    WHERE id_orden = p_id_orden;
    
    -- PASO 4: Respuesta exitosa
    RETURN json_build_object(
        'success', true,
        'message', 'Orden marcada como completada exitosamente',
        'id_orden', p_id_orden,
        'estado_anterior', v_estado_anterior,
        'estado_actual', 3,
        'usuario_operacion', p_usr_operacion,

        'informacion_orden', json_build_object(
            'id_usuario', v_orden_record.id_usuario,
            'total_pagado', v_orden_record.val_total_pedido,
            'fecha_pedido', v_orden_record.fec_pedido,
            'metodo_pago', v_orden_record.metodo_pago
        ),
        'nota', 'Los procesos críticos (puntos, stock, estadísticas) se ejecutaron cuando se marcó como PAGADA',
        'timestamp', NOW()
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Error al procesar completación de orden: ' || SQLERRM,
            'id_orden', p_id_orden,
            'sql_state', SQLSTATE,
            'codigo_error', 'ERROR_INTERNO'
        );
END;
$$;


--
-- Name: fun_marcar_orden_pagada(numeric, character varying, character varying, numeric, numeric, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_marcar_orden_pagada(p_id_orden numeric, p_metodo_pago character varying, p_referencia_pago character varying, p_monto_pagado numeric, p_usr_operacion numeric, p_observaciones character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_orden_record RECORD;
    v_estado_anterior tab_ordenes.ind_estado%TYPE;
    v_diferencia_monto tab_ordenes.val_total_pedido%TYPE;
    v_procesos_ejecutados JSON[] := ARRAY[]::JSON[];
    v_descuentos_usados JSON;
    v_resultado_puntos JSON;
    v_resultado_estadisticas JSON;
    v_inicio_proceso TIMESTAMP := NOW();
BEGIN
    -- PASO 1: Validar y obtener información de la orden
    SELECT 
        id_orden, id_usuario, ind_estado, val_total_pedido,
        val_total_productos, val_total_descuentos,
        detalle_descuentos_aplicados
    INTO v_orden_record
    FROM tab_ordenes 
    WHERE id_orden = p_id_orden;
    
    -- Verificar que la orden existe
    IF v_orden_record.id_orden IS NULL THEN
        RETURN json_build_object(
            'success', false,
            'message', 'La orden especificada no existe',
            'id_orden', p_id_orden
        );
    END IF;
    
    v_estado_anterior := v_orden_record.ind_estado;
    
    -- Verificar que la orden esté en estado válido para pago
    IF v_orden_record.ind_estado NOT IN (1, 2) THEN  -- 1=Pendiente, 2=Pagada (reproceso)
        RETURN json_build_object(
            'success', false,
            'message', 'La orden no está en estado válido para procesamiento de pago',
            'id_orden', p_id_orden,
            'estado_actual', v_orden_record.ind_estado,
            'estados_validos', 'Solo se pueden procesar órdenes Pendientes (1)'
        );
    END IF;
    
    -- PASO 2: Validar monto pagado
    v_diferencia_monto := ABS(p_monto_pagado - v_orden_record.val_total_pedido);
    
    IF v_diferencia_monto > 0.01 THEN  -- Tolerancia de 1 centavo
        RETURN json_build_object(
            'success', false,
            'message', 'El monto pagado no coincide con el total de la orden',
            'id_orden', p_id_orden,
            'monto_esperado', v_orden_record.val_total_pedido,
            'monto_pagado', p_monto_pagado,
            'diferencia', v_diferencia_monto
        );
    END IF;
    
    DECLARE
        v_resultado_cambio_estado JSON;
    BEGIN
        -- PASO 3: Marcar orden como pagada usando función centralizada
        SELECT fun_cambiar_estado_orden(
            p_id_orden,
            2,  -- Estado: Pagada
            CONCAT('Pago confirmado - Método: ', p_metodo_pago, 
                   ' - Referencia: ', COALESCE(p_referencia_pago, 'N/A')),
            p_usr_operacion
        ) INTO v_resultado_cambio_estado;
        
        -- Verificar que el cambio de estado fue exitoso
        IF NOT (v_resultado_cambio_estado->>'success')::BOOLEAN THEN
            RETURN json_build_object(
                'success', false,
                'message', 'Error al cambiar estado de orden: ' || 
                          (v_resultado_cambio_estado->>'message')::TEXT,
                'id_orden', p_id_orden,
                'detalle_error', v_resultado_cambio_estado
            );
        END IF;
        
        v_procesos_ejecutados := v_procesos_ejecutados || 
            json_build_object(
                'proceso', 'MARCAR_ORDEN_PAGADA',
                'resultado', 'exitoso',
                'estado_anterior', v_estado_anterior,
                'estado_nuevo', 2,
                'timestamp', NOW(),
                'detalle_cambio', v_resultado_cambio_estado
            );
        
        -- PASO 4: El registro del pago se maneja a través de tab_pagos por el sistema de pagos
        -- Esta función se enfoca en marcar la orden como pagada una vez confirmado el pago
        v_procesos_ejecutados := v_procesos_ejecutados || 
            json_build_object(
                'proceso', 'REGISTRAR_PAGO',
                'resultado', 'gestionado_por_sistema_pagos',
                'metodo', p_metodo_pago,
                'referencia', p_referencia_pago,
                'nota', 'El registro del pago se maneja automáticamente por tab_pagos'
            );
        
    EXCEPTION
        WHEN OTHERS THEN
            RETURN json_build_object(
                'success', false,
                'message', 'Error al marcar orden como pagada: ' || SQLERRM,
                'id_orden', p_id_orden,
                'sql_state', SQLSTATE
            );
    END;
    
    -- PASO 5: Procesar descuentos usados automáticamente
    BEGIN
        IF v_orden_record.detalle_descuentos_aplicados IS NOT NULL THEN
            -- Extraer descuentos del JSON y procesarlos
            SELECT fun_procesar_descuentos_usados_orden(
                p_id_orden, 
                v_orden_record.id_usuario,
                v_orden_record.detalle_descuentos_aplicados,
                p_usr_operacion
            ) INTO v_descuentos_usados;
            
            v_procesos_ejecutados := v_procesos_ejecutados || 
                json_build_object(
                    'proceso', 'PROCESAR_DESCUENTOS',
                    'resultado', 'exitoso',
                    'descuentos_procesados', v_descuentos_usados
                );
        ELSE
            v_procesos_ejecutados := v_procesos_ejecutados || 
                json_build_object(
                    'proceso', 'PROCESAR_DESCUENTOS',
                    'resultado', 'omitido',
                    'razon', 'sin_descuentos_aplicados'
                );
        END IF;
        
    EXCEPTION
        WHEN OTHERS THEN
            -- Log error pero continuar con otros procesos
            v_procesos_ejecutados := v_procesos_ejecutados || 
                json_build_object(
                    'proceso', 'PROCESAR_DESCUENTOS',
                    'resultado', 'error',
                    'error', SQLERRM
                );
    END;
    
    -- PASO 6: Activar acumulación de puntos
    BEGIN
        SELECT fun_acumular_puntos_compra(
            v_orden_record.id_usuario,
            p_id_orden,
            v_orden_record.val_total_productos,
            p_usr_operacion
        ) INTO v_resultado_puntos;
        
        v_procesos_ejecutados := v_procesos_ejecutados || 
            json_build_object(
                'proceso', 'ACUMULAR_PUNTOS',
                'resultado', 'exitoso',
                'puntos_otorgados', v_resultado_puntos
            );
            
    EXCEPTION
        WHEN OTHERS THEN
            v_procesos_ejecutados := v_procesos_ejecutados || 
                json_build_object(
                    'proceso', 'ACUMULAR_PUNTOS',
                    'resultado', 'error',
                    'error', SQLERRM
                );
    END;
    
    -- PASO 7: Actualizar estadísticas de ventas automáticamente
    -- NOTA: Esto se ejecutará automáticamente por el trigger cuando se complete la orden
    -- Aquí solo registramos que las estadísticas se activarán
    v_procesos_ejecutados := v_procesos_ejecutados || 
        json_build_object(
            'proceso', 'ESTADISTICAS_VENTAS',
            'resultado', 'programado',
            'nota', 'Se actualizarán automáticamente al completar la orden'
        );
    
    -- RESPUESTA EXITOSA
    RETURN json_build_object(
        'success', true,
        'message', 'Orden marcada como pagada exitosamente',
        'id_orden', p_id_orden,
        'estado_anterior', v_estado_anterior,
        'estado_actual', 2,
        'metodo_pago', p_metodo_pago,
        'referencia_pago', p_referencia_pago,
        'monto_pagado', p_monto_pagado,
        'tiempo_procesamiento', (NOW() - v_inicio_proceso),
        'procesos_ejecutados', array_to_json(v_procesos_ejecutados),
        'resumen', json_build_object(
            'orden_actualizada', true,
            'pago_registrado', true,
            'descuentos_procesados', (v_descuentos_usados IS NOT NULL),
            'puntos_acumulados', (v_resultado_puntos IS NOT NULL),
            'estadisticas_programadas', true
        ),
        'timestamp', NOW()
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Error general al procesar pago: ' || SQLERRM,
            'id_orden', p_id_orden,
            'tiempo_procesamiento', (NOW() - v_inicio_proceso),
            'procesos_ejecutados', array_to_json(v_procesos_ejecutados),
            'sql_state', SQLSTATE
        );
END;
$$;


--
-- Name: fun_migrar_carrito_anonimo_a_usuario(integer, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_migrar_carrito_anonimo_a_usuario(p_id_carrito_anonimo integer, p_id_usuario numeric, p_usr_operacion numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_carrito_usuario tab_carritos.id_carrito%TYPE;
    v_item RECORD;
    v_precio DECIMAL(12,2);
    v_carrito_es_anonimo BOOLEAN;
BEGIN
    -- Verificar que el carrito origen sea anónimo (id_usuario IS NULL).
    -- Si ya es del usuario, no migrar ni eliminar (evita borrar carrito de checkout en curso).
    SELECT (c.id_usuario IS NULL) INTO v_carrito_es_anonimo
    FROM tab_carritos c
    WHERE c.id_carrito = p_id_carrito_anonimo;

    IF NOT FOUND OR NOT v_carrito_es_anonimo THEN
        RETURN json_build_object('success', true, 'message', 'Carrito ya pertenece al usuario o no existe');
    END IF;

    v_id_carrito_usuario := fun_obtener_carrito_usuario(p_id_usuario, NULL);

    FOR v_item IN
        SELECT variant_id, cantidad, precio_unitario_carrito, COALESCE(opciones_elegidas, '{}'::JSONB) AS opciones_elegidas
        FROM tab_carrito_productos
        WHERE id_carrito = p_id_carrito_anonimo
    LOOP
        SELECT price INTO v_precio
        FROM tab_product_variant_combinations
        WHERE id = v_item.variant_id AND is_active = TRUE;
        v_precio := COALESCE(v_precio, v_item.precio_unitario_carrito);

        INSERT INTO tab_carrito_productos (id_carrito, variant_id, cantidad, precio_unitario_carrito, opciones_elegidas, usr_insert)
        VALUES (v_id_carrito_usuario, v_item.variant_id, v_item.cantidad, v_precio, v_item.opciones_elegidas, COALESCE(p_usr_operacion, p_id_usuario))
        ON CONFLICT (id_carrito, variant_id)
        DO UPDATE SET
            cantidad = tab_carrito_productos.cantidad + v_item.cantidad,
            precio_unitario_carrito = v_precio,
            opciones_elegidas = COALESCE(EXCLUDED.opciones_elegidas, tab_carrito_productos.opciones_elegidas, '{}'::JSONB),
            usr_update = p_usr_operacion,
            fec_update = NOW();
    END LOOP;

    DELETE FROM tab_carrito_productos WHERE id_carrito = p_id_carrito_anonimo;
    DELETE FROM tab_carritos WHERE id_carrito = p_id_carrito_anonimo;

    RETURN json_build_object('success', true, 'message', 'Carrito migrado exitosamente');
END;
$$;


--
-- Name: fun_obtener_carrito_detalle(numeric, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_obtener_carrito_detalle(p_id_usuario numeric, p_session_id character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_carrito INT;
    v_resultado JSON;
BEGIN
    v_id_carrito := fun_obtener_carrito_usuario(p_id_usuario, p_session_id);

    SELECT json_build_object(
        'id_carrito', v_id_carrito,
        'total_productos', COALESCE(COUNT(cp.id_carrito_producto), 0),
        'subtotal_carrito', COALESCE(SUM(cp.cantidad * cp.precio_unitario_carrito), 0),
        'productos', COALESCE(
            json_agg(
                json_build_object(
                    'id_carrito_producto', cp.id_carrito_producto,
                    'variant_id', cp.variant_id,
                    'product_id', p.id,
                    'nombre_producto', p.name,
                    'cantidad', cp.cantidad,
                    'precio_unitario', cp.precio_unitario_carrito,
                    'subtotal', (cp.cantidad * cp.precio_unitario_carrito),
                    'stock_disponible', pv.stock,
                    'opciones_elegidas', COALESCE(cp.opciones_elegidas, '{}'::JSONB),
                    'imagen_producto', (SELECT pvi.image_url FROM tab_product_variant_images pvi WHERE pvi.variant_group_id = g.id ORDER BY pvi.sort_order, pvi.id LIMIT 1)
                ) ORDER BY cp.fec_insert DESC
            ),
            '[]'::json
        )
    ) INTO v_resultado
    FROM tab_carrito_productos cp
    JOIN tab_product_variant_combinations pv ON pv.id = cp.variant_id AND pv.is_active = TRUE
    JOIN tab_product_variant_groups g ON g.id = pv.group_id
    JOIN tab_products p ON p.id = g.product_id AND p.is_active = TRUE
    WHERE cp.id_carrito = v_id_carrito;

    RETURN v_resultado;
END;
$$;


--
-- Name: fun_obtener_carrito_usuario(numeric, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_obtener_carrito_usuario(p_id_usuario numeric, p_session_id character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Variable para almacenar el ID del carrito encontrado o creado
    v_id_carrito INT;
    v_usr_insert DECIMAL(10);
BEGIN
    -- Validar que al menos un parámetro no sea NULL
    IF p_id_usuario IS NULL AND p_session_id IS NULL THEN
        RAISE EXCEPTION 'Al menos uno de los parámetros (p_id_usuario o p_session_id) debe ser proporcionado';
    END IF;
    
    -- Determinar el usuario para auditoría
    IF p_id_usuario IS NOT NULL THEN
        v_usr_insert := p_id_usuario;
    ELSE
        -- Para usuarios anónimos, usar un ID temporal basado en el hash del session_id
        v_usr_insert := ABS(hashtext(p_session_id))::DECIMAL(10);
    END IF;
    
    -- Buscar carrito existente según el tipo de usuario
    IF p_id_usuario IS NOT NULL THEN
        -- CASO 1: Usuario registrado - buscar por ID de usuario
        SELECT id_carrito INTO v_id_carrito 
        FROM tab_carritos 
        WHERE id_usuario = p_id_usuario
        ORDER BY fec_update DESC    -- Obtener el más reciente
        LIMIT 1;
        
    ELSIF p_session_id IS NOT NULL THEN 
        -- CASO 2: Usuario anónimo - buscar por session_id
        SELECT id_carrito INTO v_id_carrito
        FROM tab_carritos
        WHERE session_id = p_session_id
        AND id_usuario IS NULL                   -- Asegurar que es carrito anónimo
        ORDER BY fec_update DESC    -- Obtener el más reciente
        LIMIT 1;
    END IF;
    
    -- Si no existe carrito, crear uno nuevo
    IF v_id_carrito IS NULL THEN
        INSERT INTO tab_carritos (id_usuario, session_id, usr_insert)
        VALUES (
            p_id_usuario, 
            p_session_id,
            v_usr_insert  -- Usuario para auditoría (sin COALESCE)
        )
        RETURNING id_carrito INTO v_id_carrito;
    END IF;
    
    -- Retornar ID del carrito (existente o recién creado)
    RETURN v_id_carrito;
END;
$$;


--
-- Name: fun_obtener_dashboard_completo(integer, boolean, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_obtener_dashboard_completo(p_id_dashboard integer, p_calcular_valores boolean DEFAULT true, p_id_usuario numeric DEFAULT NULL::numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_dashboard_info RECORD;
    v_widgets_array JSONB := '[]';
    v_widget_record RECORD;
    v_kpi_valor JSON;
    v_tiene_acceso BOOLEAN;
BEGIN
    -- VERIFICAR: Acceso al dashboard
    SELECT 
        d.id_dashboard,
        d.id_usuario,
        d.nom_dashboard,
        d.descripcion,
        d.tipo_layout,
        d.columnas_grid,
        d.tema_color,
        d.mostrar_filtros,
        d.es_publico,
        d.es_dashboard_principal,
        d.auto_refresh_segundos,
        d.notificaciones_cambios,
        d.fecha_ultimo_acceso,
        d.numero_accesos,
        d.ind_activo,
        d.fec_creacion,
        d.fec_update,
        u.nom_usuario as propietario,
        EXISTS(
            SELECT 1 FROM tab_compartir_dashboards cd
            WHERE cd.id_dashboard = d.id_dashboard
              AND (cd.id_usuario_destino = p_id_usuario OR cd.id_usuario_destino IS NULL)
              AND cd.ind_activo = TRUE
        ) as dashboard_compartido
    INTO v_dashboard_info
    FROM tab_dashboards_usuarios d
    JOIN tab_usuarios u ON d.id_usuario = u.id_usuario
    WHERE d.id_dashboard = p_id_dashboard AND d.ind_activo = TRUE;
    
    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Dashboard no encontrado',
            'id_dashboard', p_id_dashboard
        );
    END IF;
    
    -- Verificar permisos de acceso
    v_tiene_acceso := (
        v_dashboard_info.id_usuario = p_id_usuario OR  -- Es el propietario
        v_dashboard_info.es_publico OR                  -- Es público
        v_dashboard_info.dashboard_compartido           -- Está compartido con el usuario
    );
    
    IF NOT v_tiene_acceso AND p_id_usuario IS NOT NULL THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Sin permisos para acceder al dashboard',
            'id_dashboard', p_id_dashboard
        );
    END IF;
    
    -- OBTENER: Todos los widgets del dashboard
    FOR v_widget_record IN 
        SELECT 
            w.id_widget,
            w.id_dashboard,
            w.id_kpi,
            w.posicion_x,
            w.posicion_y,
            w.ancho_columnas,
            w.alto_filas,
            w.orden_z,
            w.titulo_personalizado,
            w.mostrar_titulo,
            w.tipo_grafico,
            w.color_personalizado,
            w.mostrar_valor_anterior,
            w.mostrar_porcentaje_cambio,
            w.parametros_kpi,
            w.periodo_comparacion,
            w.filtros_adicionales,
            w.ind_activo,
            w.fec_creacion,
            w.fec_update,
            k.nom_kpi,
            k.descripcion_kpi,
            k.unidad_medida,
            k.formato_numero,
            k.tipo_grafico_sugerido,
            k.color_primario,
            k.mostrar_tendencia,
            t.nom_tipo_kpi,
            t.color_categoria,
            t.icono
        FROM tab_widgets_dashboard w
        JOIN tab_kpis_maestros k ON w.id_kpi = k.id_kpi
        JOIN tab_tipos_kpi t ON k.id_tipo_kpi = t.id_tipo_kpi
        WHERE w.id_dashboard = p_id_dashboard 
          AND w.ind_activo = TRUE
          AND k.ind_activo = TRUE
        ORDER BY w.posicion_y, w.posicion_x
    LOOP
        -- CALCULAR: Valor del KPI si se solicita
        v_kpi_valor := '{}';
        IF p_calcular_valores THEN
            SELECT fun_calcular_kpi(
                v_widget_record.id_kpi,
                v_widget_record.parametros_kpi,
                FALSE  -- No forzar recálculo
            ) INTO v_kpi_valor;
        END IF;
        
        -- AGREGAR: Widget al array
        v_widgets_array := v_widgets_array || jsonb_build_object(
            'id_widget', v_widget_record.id_widget,
            'id_kpi', v_widget_record.id_kpi,
            'posicion', json_build_object(
                'x', v_widget_record.posicion_x,
                'y', v_widget_record.posicion_y,
                'ancho', v_widget_record.ancho_columnas,
                'alto', v_widget_record.alto_filas,
                'z_index', v_widget_record.orden_z
            ),
            'configuracion_visual', json_build_object(
                'titulo', COALESCE(v_widget_record.titulo_personalizado, v_widget_record.nom_kpi),
                'mostrar_titulo', v_widget_record.mostrar_titulo,
                'tipo_grafico', COALESCE(v_widget_record.tipo_grafico, v_widget_record.tipo_grafico_sugerido),
                'color', COALESCE(v_widget_record.color_personalizado, v_widget_record.color_primario),
                'mostrar_valor_anterior', v_widget_record.mostrar_valor_anterior,
                'mostrar_porcentaje_cambio', v_widget_record.mostrar_porcentaje_cambio
            ),
            'kpi_info', json_build_object(
                'nombre', v_widget_record.nom_kpi,
                'descripcion', v_widget_record.descripcion_kpi,
                'tipo_kpi', v_widget_record.nom_tipo_kpi,
                'unidad_medida', v_widget_record.unidad_medida,
                'formato_numero', v_widget_record.formato_numero,
                'icono_categoria', v_widget_record.icono,
                'color_categoria', v_widget_record.color_categoria
            ),
            'configuracion_datos', json_build_object(
                'parametros_kpi', v_widget_record.parametros_kpi,
                'periodo_comparacion', v_widget_record.periodo_comparacion,
                'filtros_adicionales', v_widget_record.filtros_adicionales
            ),
            'valor_calculado', v_kpi_valor,
            'fecha_creacion', v_widget_record.fec_creacion,
            'fecha_actualizacion', v_widget_record.fec_update
        );
    END LOOP;
    
    -- ACTUALIZAR: Estadísticas de acceso al dashboard
    UPDATE tab_dashboards_usuarios 
    SET fecha_ultimo_acceso = NOW(),
        numero_accesos = numero_accesos + 1
    WHERE id_dashboard = p_id_dashboard;
    
    -- RESPUESTA: Dashboard completo
    RETURN json_build_object(
        'success', true,
        'dashboard', json_build_object(
            'id_dashboard', v_dashboard_info.id_dashboard,
            'nombre', v_dashboard_info.nom_dashboard,
            'descripcion', v_dashboard_info.descripcion,
            'propietario', v_dashboard_info.propietario,
            'configuracion_visual', json_build_object(
                'tipo_layout', v_dashboard_info.tipo_layout,
                'columnas_grid', v_dashboard_info.columnas_grid,
                'tema_color', v_dashboard_info.tema_color,
                'mostrar_filtros', v_dashboard_info.mostrar_filtros,
                'auto_refresh_segundos', v_dashboard_info.auto_refresh_segundos
            ),
            'configuracion_acceso', json_build_object(
                'es_publico', v_dashboard_info.es_publico,
                'es_principal', v_dashboard_info.es_dashboard_principal,
                'notificaciones_cambios', v_dashboard_info.notificaciones_cambios
            ),
            'estadisticas_uso', json_build_object(
                'numero_accesos', v_dashboard_info.numero_accesos,
                'fecha_ultimo_acceso', v_dashboard_info.fecha_ultimo_acceso,
                'fecha_creacion', v_dashboard_info.fec_creacion
            )
        ),
        'widgets', v_widgets_array,
        'total_widgets', jsonb_array_length(v_widgets_array),
        'fecha_consulta', NOW(),
        'valores_calculados', p_calcular_valores
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Error obteniendo dashboard: ' || SQLERRM,
            'sql_state', SQLSTATE,
            'id_dashboard', p_id_dashboard
        );
END;
$$;


--
-- Name: fun_obtener_descuento(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_obtener_descuento(p_id_descuento numeric) RETURNS json
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_descuento RECORD;
    v_resultado JSON;
BEGIN
    -- CONSULTA: Obtener descuento completo con información calculada
    SELECT 
        d.id_descuento,
        d.nom_descuento,
        d.des_descuento,
        d.tipo_calculo,
        d.val_porce_descuento,
        d.val_monto_descuento,
        d.aplica_a,
        d.category_id_aplica AS id_categoria_aplica,
        d.product_id_aplica,
        d.id_marca_aplica,
        d.min_valor_pedido,
        d.ind_es_para_cumpleanos,
        d.fec_inicio,
        d.fec_fin,
        d.ind_activo,
        d.max_usos_total,
        d.usos_actuales_total,
        d.costo_puntos_canje,
        d.ind_canjeable_puntos,
        d.codigo_descuento,
        d.max_usos_por_usuario,
        d.dias_semana_aplica,
        d.horas_inicio,
        d.horas_fin,
        d.solo_primera_compra,
        d.monto_minimo_producto,
        d.cantidad_minima_producto,
        d.requiere_codigo,
        d.usr_insert,
        d.fec_insert,
        d.usr_update,
        d.fec_update,
        CASE 
            WHEN d.tipo_calculo THEN 'Porcentaje'
            ELSE 'Monto Fijo'
        END AS tipo_calculo_texto,                              -- Tipo de cálculo legible
        CASE 
            WHEN d.tipo_calculo THEN 
                CONCAT(d.val_porce_descuento::TEXT, '%')
            ELSE 
                CONCAT('$', d.val_monto_descuento::TEXT)
        END AS valor_mostrar,                                   -- Valor formateado
        CASE 
            WHEN NOT d.ind_activo THEN 'Inactivo'
            WHEN CURRENT_DATE < d.fec_inicio THEN 'Programado'
            WHEN CURRENT_DATE > d.fec_fin THEN 'Vencido'
            WHEN d.max_usos_total IS NOT NULL AND d.usos_actuales_total >= d.max_usos_total THEN 'Agotado'
            ELSE 'Activo'
        END AS estado_descuento,                                -- Estado calculado
        CASE 
            WHEN d.max_usos_total IS NOT NULL AND d.max_usos_total > 0 THEN
                ROUND((d.usos_actuales_total::DECIMAL / d.max_usos_total::DECIMAL) * 100, 1)
            ELSE NULL
        END AS porcentaje_uso,                                  -- Porcentaje de uso
        -- RESOLUCIÓN: Nombres de entidades relacionadas según tipo de aplicación
        CASE 
            WHEN d.aplica_a = 'producto_especifico' THEN
                (SELECT p.name FROM tab_products p 
                 WHERE p.id = d.product_id_aplica)
            ELSE NULL
        END AS nombre_producto_aplica,                          -- Nombre del producto específico
        CASE 
            WHEN d.aplica_a = 'categoria_especifica' THEN
                (SELECT c.name FROM tab_categories c WHERE c.id = d.category_id_aplica)
            ELSE NULL
        END AS nombre_categoria_aplica,                         -- Nombre de categoría específica
        CASE 
            WHEN d.aplica_a = 'marca_especifica' THEN
                (SELECT m.nom_marca FROM tab_marcas m WHERE m.id_marca = d.id_marca_aplica)
            ELSE NULL
        END AS nombre_marca_aplica                              -- Nombre de marca específica
    INTO v_descuento
    FROM tab_descuentos d
    WHERE d.id_descuento = p_id_descuento;

    -- Si no se encuentra el descuento
    IF v_descuento IS NULL THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Descuento no encontrado'
        );
    END IF;

    -- Construir el JSON de respuesta
    v_resultado := json_build_object(
        'success', true,
        'descuento', json_build_object(
            'id_descuento', v_descuento.id_descuento,
            'nom_descuento', v_descuento.nom_descuento,
            'des_descuento', v_descuento.des_descuento,
            'tipo_calculo', v_descuento.tipo_calculo,
            'tipo_calculo_texto', v_descuento.tipo_calculo_texto,
            'val_porce_descuento', v_descuento.val_porce_descuento,
            'val_monto_descuento', v_descuento.val_monto_descuento,
            'valor_mostrar', v_descuento.valor_mostrar,
            'aplica_a', v_descuento.aplica_a,
            'min_valor_pedido', v_descuento.min_valor_pedido,
            'ind_es_para_cumpleanos', v_descuento.ind_es_para_cumpleanos,
            'fec_inicio', v_descuento.fec_inicio,
            'fec_fin', v_descuento.fec_fin,
            'ind_activo', v_descuento.ind_activo,
            'estado_descuento', v_descuento.estado_descuento,
            -- Configuración de uso
            'max_usos_total', v_descuento.max_usos_total,
            'usos_actuales_total', v_descuento.usos_actuales_total,
            'porcentaje_uso', v_descuento.porcentaje_uso,
            'max_usos_por_usuario', v_descuento.max_usos_por_usuario,
            -- Nuevos campos
            'codigo_descuento', v_descuento.codigo_descuento,
            'dias_semana_aplica', v_descuento.dias_semana_aplica,
            'horas_inicio', v_descuento.horas_inicio,
            'horas_fin', v_descuento.horas_fin,
            'solo_primera_compra', v_descuento.solo_primera_compra,
            'monto_minimo_producto', v_descuento.monto_minimo_producto,
            'cantidad_minima_producto', v_descuento.cantidad_minima_producto,
            'requiere_codigo', v_descuento.requiere_codigo,
            -- Referencias de aplicación
            'id_producto_aplica', v_descuento.product_id_aplica,
            'nombre_producto_aplica', v_descuento.nombre_producto_aplica,
            'id_categoria_aplica', v_descuento.id_categoria_aplica,
            'nombre_categoria_aplica', v_descuento.nombre_categoria_aplica,
            'id_marca_aplica', v_descuento.id_marca_aplica,
            'nombre_marca_aplica', v_descuento.nombre_marca_aplica,
            -- Auditoría
            'usr_insert', v_descuento.usr_insert,
            'fec_insert', v_descuento.fec_insert,
            'usr_update', v_descuento.usr_update,
            'fec_update', v_descuento.fec_update
        )
    );

    RETURN v_resultado;

EXCEPTION 
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Error: ' || SQLERRM
        );
END;
$_$;


--
-- Name: fun_obtener_historial_puntos(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_obtener_historial_puntos(p_id_usuario numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_historial_json JSON;
BEGIN
    -- Construir el array JSON de movimientos
    SELECT json_agg(
        json_build_object(
            'id_movimiento_puntos', mp.id_movimiento_puntos,
            'tipo_movimiento_codigo', mp.tipo_movimiento,
            'tipo_movimiento_descripcion', CASE mp.tipo_movimiento
                WHEN 1 THEN 'Acumulación'
                WHEN 2 THEN 'Canje'
                WHEN 3 THEN 'Expiración'
                ELSE 'Tipo Desconocido'
            END,
            'cantidad_puntos', mp.cantidad_puntos,
            'puntos_disponibles_anterior', mp.puntos_disponibles_anterior,
            'puntos_disponibles_actual', mp.puntos_disponibles_actual,
            'descripcion', mp.descripcion,
            'fec_movimiento', mp.fec_insert,
            'id_orden_origen', mp.id_orden_origen,
            'id_descuento_canjeado', mp.id_descuento_canjeado,
            'nombre_descuento', d.nom_descuento
        ) ORDER BY mp.fec_insert DESC, mp.id_movimiento_puntos DESC
    )
    INTO v_historial_json
    FROM tab_movimientos_puntos mp
    LEFT JOIN tab_descuentos d ON mp.id_descuento_canjeado = d.id_descuento
    WHERE mp.id_usuario = p_id_usuario;

    -- Envolver el array en un objeto de respuesta
    RETURN json_build_object(
        'success', true,
        'id_usuario', p_id_usuario,
        'historial', COALESCE(v_historial_json, '[]'::JSON)
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Error al obtener el historial de puntos: ' || SQLERRM,
            'error_code', SQLSTATE
        );
END;
$$;


--
-- Name: fun_obtener_ordenes_usuario(numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_obtener_ordenes_usuario(p_id_usuario numeric, p_limite integer DEFAULT 10) RETURNS TABLE(id_orden numeric, fecha_pedido timestamp without time zone, total_productos numeric, total_descuentos numeric, total_pedido numeric, estado_orden text, metodo_pago text, cantidad_productos bigint, descuentos_aplicados json)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- CONSULTA: Obtener órdenes del usuario con información detallada
    RETURN QUERY
    SELECT 
        o.id_orden,                                                 -- ID de la orden
        o.fec_pedido,                                               -- Fecha del pedido
        COALESCE(o.val_total_productos, o.val_total_pedido) as total_productos,  -- Compatibilidad con datos legacy
        COALESCE(o.val_total_descuentos, 0) as total_descuentos,    -- Total de descuentos (0 si es NULL)
        o.val_total_pedido,                                         -- Valor total final del pedido
        CASE 
            WHEN o.ind_estado = 1 THEN 'Pendiente'
            WHEN o.ind_estado = 2 THEN 'Completada'
            WHEN o.ind_estado = 3 THEN 'Cancelada'
            ELSE 'Desconocido'
        END AS estado,
        o.metodo_pago,                                     -- Método de pago legible
        o.json_descuentos_aplicados
    FROM 
        tab_ordenes o
    WHERE 
        o.id_usuario = p_id_usuario
    GROUP BY 
        o.id_orden, o.fec_pedido, o.val_total_pedido, o.ind_estado, o.metodo_pago, o.json_descuentos_aplicados
    ORDER BY 
        o.fec_pedido DESC
    LIMIT p_limite;                                                -- Limitar resultados
END;
$$;


--
-- Name: fun_obtener_pago(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_obtener_pago(p_id_orden numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_pago_info RECORD;
BEGIN
    -- VALIDACIÓN
    IF p_id_orden IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'El ID de la orden es obligatorio.');
    END IF;

    -- CONSULTA
    SELECT * INTO v_pago_info
    FROM tab_pagos
    WHERE id_orden = p_id_orden
    ORDER BY fec_insert DESC
    LIMIT 1;

    -- RESPUESTA
    IF NOT FOUND THEN
        RETURN json_build_object('success', false, 'message', 'No se encontró información de pago para la orden especificada.');
    END IF;

    RETURN json_build_object(
        'success', true,
        'pago', row_to_json(v_pago_info)
    );

EXCEPTION 
    WHEN OTHERS THEN
        RETURN json_build_object('success', false, 'message', 'Error inesperado: ' || SQLERRM);
END;
$$;


--
-- Name: fun_obtener_resumen_puntos_usuario(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_obtener_resumen_puntos_usuario(p_id_usuario numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_puntos_usuario RECORD;
    v_canjes_disponibles INT;
    v_config_puntos DECIMAL(10,2);
BEGIN
    -- CONSULTA: Obtener información completa de puntos del usuario
    SELECT 
        pu.id_usuario,
        pu.puntos_disponibles,
        pu.puntos_totales_ganados,
        pu.puntos_totales_canjeados,
        pu.fec_ultimo_canje,
        pu.usr_insert,
        pu.fec_insert,
        pu.usr_update,
        pu.fec_update,
        u.nom_usuario,
        u.ape_usuario
    INTO v_puntos_usuario
    FROM tab_puntos_usuario pu
    JOIN tab_usuarios u ON pu.id_usuario = u.id_usuario                -- JOIN para obtener nombre
    WHERE pu.id_usuario = p_id_usuario;
    
    -- PREPARACIÓN: Crear registro básico si no existe
    IF NOT FOUND THEN
        INSERT INTO tab_puntos_usuario (id_usuario, usr_insert)
        VALUES (p_id_usuario, p_usr_operacion)
        ON CONFLICT (id_usuario) DO NOTHING;                           -- No duplicar si ya existe
        
        -- Re-consultar información después de crear registro
        SELECT 
            pu.id_usuario,
            pu.puntos_disponibles,
            pu.puntos_totales_ganados,
            pu.puntos_totales_canjeados,
            pu.fec_ultimo_canje,
            pu.usr_insert,
            pu.fec_insert,
            pu.usr_update,
            pu.fec_update,
            u.nom_usuario,
            u.ape_usuario
        INTO v_puntos_usuario
        FROM tab_puntos_usuario pu
        JOIN tab_usuarios u ON pu.id_usuario = u.id_usuario
        WHERE pu.id_usuario = p_id_usuario;
    END IF;
    
    -- CONSULTA: Contar canjes disponibles (no utilizados y no vencidos)
    SELECT COUNT(1) INTO v_canjes_disponibles
    FROM tab_canjes_puntos_descuentos
    WHERE id_usuario = p_id_usuario                                    -- Del usuario específico
      AND ind_utilizado = FALSE                                        -- No utilizados
      AND (fec_expiracion_canje IS NULL OR fec_expiracion_canje >= CURRENT_DATE); -- No vencidos
    
    -- CONSULTA: Obtener configuración actual de puntos
    SELECT pesos_por_punto INTO v_config_puntos
    FROM tab_config_puntos_empresa
    WHERE ind_activo = TRUE
        AND fec_inicio_vigencia <= CURRENT_DATE
        AND (fec_fin_vigencia IS NULL OR fec_fin_vigencia >= CURRENT_DATE)
    ORDER BY fec_inicio_vigencia DESC
    LIMIT 1;
    
    -- VALIDACIÓN: Verificar que existe una configuración activa
    IF v_config_puntos IS NULL THEN
        v_config_puntos := 1000; -- Valor por defecto si no hay configuración
    END IF;
    
    -- CONSTRUCCIÓN: Crear respuesta JSON estructurada
    RETURN json_build_object(
        'usuario', json_build_object(                                  -- Información del usuario
            'id_usuario', v_puntos_usuario.id_usuario,
            'nombre_completo', v_puntos_usuario.nom_usuario || ' ' || v_puntos_usuario.ape_usuario
        ),
        'puntos', json_build_object(                                   -- Información de puntos
            'disponibles', v_puntos_usuario.puntos_disponibles,
            'totales_ganados', v_puntos_usuario.puntos_totales_ganados,
            'totales_canjeados', v_puntos_usuario.puntos_totales_canjeados,
            'valor_estimado_pesos', v_puntos_usuario.puntos_disponibles * v_config_puntos
        ),
        'fechas', json_build_object(                                   -- Fechas importantes
            'ultima_acumulacion', v_puntos_usuario.fec_ultima_acumulacion,
            'ultimo_canje', v_puntos_usuario.fec_ultimo_canje
        ),
        'canjes_disponibles', v_canjes_disponibles,                    -- Canjes no utilizados
        'configuracion', json_build_object(                            -- Configuración del sistema
            'pesos_por_punto', v_config_puntos
        )
    );
END;
$$;


--
-- Name: fun_reactivate_usuario(numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_reactivate_usuario(p_id_usuario numeric, p_usr_update numeric DEFAULT NULL::numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Verificar existencia
    IF NOT EXISTS (SELECT 1 FROM tab_usuarios WHERE id_usuario = p_id_usuario) THEN
        RETURN 'Error: Usuario no encontrado';
    END IF;

    UPDATE tab_usuarios
    SET ind_activo = TRUE,
        deleted_at = NULL,
        usr_update = COALESCE(p_usr_update, usr_update),
        fec_update = NOW()
    WHERE id_usuario = p_id_usuario;

    RETURN 'Usuario reactivado correctamente';
END;
$$;


--
-- Name: fun_recalcular_estadisticas_batch(boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_recalcular_estadisticas_batch(p_solo_categorias_activas boolean DEFAULT true, p_incluir_productos_inactivos boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_inicio_proceso TIMESTAMP := NOW();
    v_resultado_productos JSON;
    v_resultado_categorias JSON;
    v_categoria_record RECORD;
    v_total_productos INT := 0;
    v_total_categorias INT := 0;
BEGIN
    RAISE NOTICE 'Iniciando recálculo batch de estadísticas...';
    
    -- RECALCULAR: Todas las estadísticas de productos
    SELECT fun_actualizar_resumen_ventas(NULL, NULL, TRUE) 
    INTO v_resultado_productos;
    
    v_total_productos := (v_resultado_productos->>'productos_actualizados')::INT;
    
    -- RECALCULAR: Todas las estadísticas de categorías
    SELECT fun_actualizar_resumen_categoria(NULL, TRUE) 
    INTO v_resultado_categorias;
    
    v_total_categorias := (v_resultado_categorias->>'categorias_actualizadas')::INT;
    
    RAISE NOTICE 'Recálculo batch completado: % productos, % categorías en %',
        v_total_productos, v_total_categorias, (NOW() - v_inicio_proceso);
    
    -- RESPUESTA: Resultado consolidado
    RETURN json_build_object(
        'success', true,
        'tipo_operacion', 'RECALCULO_BATCH_COMPLETO',
        'tiempo_total_procesamiento', (NOW() - v_inicio_proceso),
        'productos_recalculados', v_total_productos,
        'categorias_recalculadas', v_total_categorias,
        'resultado_productos', v_resultado_productos,
        'resultado_categorias', v_resultado_categorias,
        'timestamp', NOW()
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Error en recálculo batch: ' || SQLERRM,
            'productos_procesados', v_total_productos,
            'categorias_procesadas', v_total_categorias,
            'tiempo_procesamiento', (NOW() - v_inicio_proceso),
            'sql_state', SQLSTATE
        );
END;
$$;


--
-- Name: fun_registrar_uso_descuento(numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_registrar_uso_descuento(p_id_descuento numeric, p_id_usuario numeric, p_usr_operacion numeric) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_existe_registro BOOLEAN := FALSE;
BEGIN
    -- VERIFICACIÓN: Comprobar si ya existe registro del usuario usando este descuento
    SELECT EXISTS(
        SELECT 1 FROM tab_descuentos_usuarios 
        WHERE id_descuento = p_id_descuento AND id_usuario = p_id_usuario
    ) INTO v_existe_registro;
    
    IF v_existe_registro THEN
        -- ACTUALIZACIÓN: Incrementar contador existente
        UPDATE tab_descuentos_usuarios 
        SET veces_usado = veces_usado + 1,                      -- Incrementar contador de usos
            usr_update = p_usr_operacion,                       -- Usuario que actualiza
            fec_update = NOW()                                  -- Fecha de actualización
        WHERE id_descuento = p_id_descuento AND id_usuario = p_id_usuario;
    ELSE
        -- INSERCIÓN: Crear nuevo registro de uso
        INSERT INTO tab_descuentos_usuarios (
            id_descuento,                                       -- ID del descuento
            id_usuario,                                         -- ID del usuario
            veces_usado,                                        -- Iniciar en 1
            usr_insert                                          -- Usuario que crea el registro
        ) VALUES (
            p_id_descuento, 
            p_id_usuario, 
            1, 
            p_usr_operacion
        );
    END IF;
    
    -- ACTUALIZACIÓN: Incrementar contador total de usos del descuento
    UPDATE tab_descuentos 
    SET usos_actuales_total = usos_actuales_total + 1,         -- Incrementar contador total
        usr_update = p_usr_operacion,                           -- Usuario que actualiza
        fec_update = NOW()                                      -- Actualizar timestamp
    WHERE id_descuento = p_id_descuento;
    
    RETURN TRUE;
    
-- MANEJO DE ERRORES: Capturar cualquier excepción
EXCEPTION 
    WHEN OTHERS THEN
        RETURN FALSE;
END;
$$;


--
-- Name: fun_restaurar_stock_cancelacion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_restaurar_stock_cancelacion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_record       RECORD;
    v_stock_actual INT;
    v_stock_nuevo  INT;
    v_costo        DECIMAL(12, 2);
    v_usr          DECIMAL(10);
    v_saldo_actual DECIMAL(14, 2);
BEGIN
    IF OLD.ind_estado = 4 OR NEW.ind_estado != 4 THEN
        RETURN NULL;
    END IF;

    v_usr := COALESCE(NEW.usr_update, 1000000000);

    FOR v_record IN
        SELECT op.id_orden_producto, op.variant_id, op.cant_producto, p.name AS nom_producto
        FROM tab_orden_productos op
        JOIN tab_product_variant_combinations pv ON pv.id = op.variant_id
        JOIN tab_product_variant_groups g ON g.id = pv.group_id
        JOIN tab_products p ON p.id = g.product_id
        WHERE op.id_orden = NEW.id_orden
    LOOP
        SELECT stock INTO v_stock_actual
        FROM tab_product_variant_combinations
        WHERE id = v_record.variant_id
        FOR UPDATE;

        v_stock_nuevo := v_stock_actual + v_record.cant_producto;

        UPDATE tab_product_variant_combinations
        SET stock = v_stock_nuevo, usr_update = v_usr, fec_update = NOW()
        WHERE id = v_record.variant_id;

        -- Costo de la devolución = COGS con el que salió esa venta (balancea costo).
        SELECT costo_unitario_movimiento INTO v_costo
        FROM tab_movimientos_inventario
        WHERE variant_id = v_record.variant_id
          AND id_orden_usuario_detalle = v_record.id_orden_producto
          AND tipo_movimiento = 'salida_venta'
        ORDER BY id_movimiento DESC
        LIMIT 1;
        v_costo := COALESCE(v_costo, 0);

        -- Reingresa como lote nuevo (capa más reciente).
        INSERT INTO tab_lotes_inventario (
            variant_id, costo_unitario, cantidad_inicial, cantidad_restante, origen, fec_entrada, usr_insert
        ) VALUES (
            v_record.variant_id, v_costo, v_record.cant_producto, v_record.cant_producto,
            'devolucion_usuario', NOW(), v_usr
        );

        v_saldo_actual := fun_saldo_costo_inventario(v_record.variant_id);

        INSERT INTO tab_movimientos_inventario (
            variant_id, tipo_movimiento, cantidad, costo_unitario_movimiento,
            stock_anterior, stock_actual, saldo_costo_total_actual_mov,
            id_orden_usuario_detalle, descripcion, usr_insert
        ) VALUES (
            v_record.variant_id,
            'devolucion_usuario',
            v_record.cant_producto,
            v_costo,
            v_stock_actual,
            v_stock_nuevo,
            v_saldo_actual,
            v_record.id_orden_producto,
            'Devolución por cancelación (FIFO) - Orden #' || NEW.id_orden || ' - ' || v_record.nom_producto,
            v_usr
        );
    END LOOP;

    RETURN NULL;
EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Error en restauración de stock para orden #%: %', NEW.id_orden, SQLERRM;
END;
$$;


--
-- Name: fun_saldo_costo_inventario(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_saldo_costo_inventario(p_variant_id numeric) RETURNS numeric
    LANGUAGE sql
    AS $$
    SELECT COALESCE(SUM(cantidad_restante * costo_unitario), 0)::DECIMAL(14, 2)
    FROM tab_lotes_inventario
    WHERE variant_id = p_variant_id;
$$;


--
-- Name: fun_select_favoritos_usuario(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_select_favoritos_usuario(p_id_usuario numeric) RETURNS TABLE(id_usuario numeric, product_id numeric, fec_insert timestamp without time zone, nom_producto character varying, img_principal character varying, precio_min numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        id_usuario,
        product_id,
        fec_insert,
        nom_producto,
        img_principal,
        precio_min
    FROM fun_select_favoritos_usuario_con_detalles(p_id_usuario);
END;
$$;


--
-- Name: fun_select_favoritos_usuario_con_detalles(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_select_favoritos_usuario_con_detalles(p_id_usuario numeric) RETURNS TABLE(id_usuario numeric, product_id numeric, fec_insert timestamp without time zone, nom_producto character varying, img_principal character varying, precio_min numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        tf.id_usuario,
        tf.product_id,
        tf.fec_insert,
        p.name AS nom_producto,
        COALESCE(
          (SELECT pvi.image_url FROM tab_product_variant_images pvi
           INNER JOIN tab_product_variant_groups g ON g.id = pvi.variant_group_id
           WHERE g.product_id = p.id
             AND LOWER(TRIM(COALESCE(g.dominant_value, ''))) = 'sin color'
           ORDER BY pvi.is_primary DESC NULLS LAST, pvi.sort_order NULLS LAST, pvi.id
           LIMIT 1),
          (SELECT pvi.image_url FROM tab_product_variant_images pvi
           INNER JOIN tab_product_variant_groups g ON g.id = pvi.variant_group_id
           WHERE g.product_id = p.id
           ORDER BY g.id, pvi.sort_order, pvi.id
           LIMIT 1)
        ) AS img_principal,
        (SELECT MIN(c.price) FROM tab_product_variant_combinations c JOIN tab_product_variant_groups g ON g.id = c.group_id WHERE g.product_id = p.id AND c.is_active = TRUE) AS precio_min
    FROM tab_favoritos tf
    JOIN tab_products p ON p.id = tf.product_id
    WHERE tf.id_usuario = p_id_usuario
    ORDER BY tf.fec_insert DESC;
END;
$$;


--
-- Name: fun_semantic_search_product_embeddings(public.vector, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_semantic_search_product_embeddings(p_query_embedding public.vector, p_top_k integer) RETURNS TABLE(product_id numeric, score double precision)
    LANGUAGE sql
    AS $$
  SELECT
    e.product_id,
    (1 - (e.embedding <=> p_query_embedding))::double precision AS score
  FROM tab_product_embeddings e
  ORDER BY e.embedding <=> p_query_embedding ASC
  LIMIT GREATEST(p_top_k, 0);
$$;


--
-- Name: fun_sincronizar_estadisticas_completas(numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_sincronizar_estadisticas_completas(p_id_categoria numeric DEFAULT NULL::numeric, p_forzar_recalculo boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_inicio_proceso TIMESTAMP := NOW();
    v_resultado_productos JSON;
    v_resultado_categorias JSON;
    v_productos_actualizados INT := 0;
    v_categorias_actualizadas INT := 0;
BEGIN
    -- PASO 1: Actualizar estadísticas de productos
    SELECT fun_actualizar_resumen_ventas(
        p_id_categoria, NULL, p_forzar_recalculo
    ) INTO v_resultado_productos;
    
    -- Extraer contador de productos actualizados
    v_productos_actualizados := (v_resultado_productos->>'productos_actualizados')::INT;
    
    -- PASO 2: Actualizar estadísticas de categorías
    SELECT fun_actualizar_resumen_categoria(
        p_id_categoria, p_forzar_recalculo
    ) INTO v_resultado_categorias;
    
    -- Extraer contador de categorías actualizadas
    v_categorias_actualizadas := (v_resultado_categorias->>'categorias_actualizadas')::INT;
    
    -- RESPUESTA: Resultado consolidado
    RETURN json_build_object(
        'success', true,
        'tipo_sincronizacion', CASE 
            WHEN p_forzar_recalculo THEN 'RECALCULO_FORZADO'
            WHEN p_id_categoria IS NOT NULL THEN 'CATEGORIA_ESPECIFICA'
            ELSE 'SINCRONIZACION_COMPLETA'
        END,
        'tiempo_total_procesamiento', (NOW() - v_inicio_proceso),
        'productos_actualizados', v_productos_actualizados,
        'categorias_actualizadas', v_categorias_actualizadas,
        'resultado_productos', v_resultado_productos,
        'resultado_categorias', v_resultado_categorias,
        'timestamp', NOW()
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Error en sincronización completa: ' || SQLERRM,
            'productos_actualizados', v_productos_actualizados,
            'categorias_actualizadas', v_categorias_actualizadas,
            'tiempo_procesamiento', (NOW() - v_inicio_proceso),
            'sql_state', SQLSTATE
        );
END;
$$;


--
-- Name: fun_soft_delete_usuario(numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_soft_delete_usuario(p_id_usuario numeric, p_usr_update numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Verificar existencia
    IF NOT EXISTS (SELECT 1 FROM tab_usuarios WHERE id_usuario = p_id_usuario) THEN
        RETURN 'Error: Usuario no encontrado';
    END IF;

    UPDATE tab_usuarios
    SET ind_activo = FALSE,
        deleted_at = NOW(),
        usr_update = p_usr_update,
        fec_update = NOW()
    WHERE id_usuario = p_id_usuario;

    RETURN 'Usuario desactivado correctamente';
END;
$$;


--
-- Name: fun_trigger_actualizar_estadisticas_orden(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_trigger_actualizar_estadisticas_orden() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_categoria_actual DECIMAL(10);
    v_categoria_record RECORD;
    v_resultado JSON;
    v_productos_afectados INT := 0;
    v_categorias_afectadas INT := 0;
    v_inicio_proceso TIMESTAMP := NOW();
BEGIN
    -- VALIDAR: Solo procesar órdenes PAGADAS
    -- Lógica: Las estadísticas se actualizan cuando se confirma la venta (pago)
    IF NEW.ind_estado != 2 THEN
        RETURN NEW; -- No es orden pagada, no hacer nada
    END IF;
    
    -- VALIDAR: Solo procesar si el estado cambió a PAGADA
    IF TG_OP = 'UPDATE' AND OLD.ind_estado = 2 THEN
        RETURN NEW; -- Ya era pagada, no procesar de nuevo
    END IF;
    
    -- LOG: Inicio del proceso
    RAISE NOTICE 'Iniciando actualización de estadísticas para orden PAGADA ID: %', NEW.id_orden;
    
    BEGIN
        -- OBTENER: Categorías afectadas por esta orden (vía variant -> product -> category_id)
        FOR v_categoria_record IN 
            SELECT DISTINCT p.category_id AS id_categoria
            FROM tab_orden_productos op
            JOIN tab_product_variant_combinations pv ON pv.id = op.variant_id
            JOIN tab_product_variant_groups g ON g.id = pv.group_id
            JOIN tab_products p ON p.id = g.product_id
            WHERE op.id_orden = NEW.id_orden
        LOOP
            -- ACTUALIZAR: Estadísticas de productos de la categoría
            SELECT fun_actualizar_resumen_ventas(
                v_categoria_record.id_categoria, NULL, FALSE
            ) INTO v_resultado;
            
            -- Verificar resultado de productos
            IF (v_resultado->>'success')::BOOLEAN THEN
                v_productos_afectados := v_productos_afectados + 
                    (v_resultado->>'productos_actualizados')::INT;
                    
                RAISE NOTICE 'Productos actualizados en categoría %: %', 
                    v_categoria_record.id_categoria, 
                    (v_resultado->>'productos_actualizados')::INT;
            ELSE
                RAISE WARNING 'Error actualizando productos categoría %: %', 
                    v_categoria_record.id_categoria, 
                    (v_resultado->>'error')::TEXT;
            END IF;
            
            -- ACTUALIZAR: Estadísticas de la categoría
            SELECT fun_actualizar_resumen_categoria(
                v_categoria_record.id_categoria, FALSE
            ) INTO v_resultado;
            
            -- Verificar resultado de categoría
            IF (v_resultado->>'success')::BOOLEAN THEN
                v_categorias_afectadas := v_categorias_afectadas + 
                    (v_resultado->>'categorias_actualizadas')::INT;
                    
                RAISE NOTICE 'Categoría actualizada: %', v_categoria_record.id_categoria;
            ELSE
                RAISE WARNING 'Error actualizando categoría %: %', 
                    v_categoria_record.id_categoria, 
                    (v_resultado->>'error')::TEXT;
            END IF;
            
        END LOOP;
        
        -- LOG: Resumen final
        RAISE NOTICE 'Estadísticas actualizadas - Orden: %, Productos: %, Categorías: %, Tiempo: %', 
            NEW.id_orden, 
            v_productos_afectados, 
            v_categorias_afectadas,
            (NOW() - v_inicio_proceso);
            
    EXCEPTION
        WHEN OTHERS THEN
            -- MANEJO DE ERRORES: Log pero no fallar la transacción principal
            RAISE WARNING 'Error en actualización de estadísticas para orden %: % (SQL State: %)', 
                NEW.id_orden, SQLERRM, SQLSTATE;
    END;
    
    RETURN NEW;
END;
$$;


--
-- Name: fun_trigger_actualizar_estadisticas_producto_orden(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_trigger_actualizar_estadisticas_producto_orden() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_orden_pagada BOOLEAN := FALSE;
    v_resultado JSON;
    v_category_id DECIMAL(10);
BEGIN
    IF TG_OP = 'DELETE' THEN
        SELECT (o.ind_estado IN (2, 3)) INTO v_orden_pagada FROM tab_ordenes o WHERE o.id_orden = OLD.id_orden;
        SELECT p.category_id INTO v_category_id FROM tab_product_variant_combinations pv JOIN tab_product_variant_groups g ON g.id = pv.group_id JOIN tab_products p ON p.id = g.product_id WHERE pv.id = OLD.variant_id;
    ELSE
        SELECT (o.ind_estado IN (2, 3)) INTO v_orden_pagada FROM tab_ordenes o WHERE o.id_orden = NEW.id_orden;
        SELECT p.category_id INTO v_category_id FROM tab_product_variant_combinations pv JOIN tab_product_variant_groups g ON g.id = pv.group_id JOIN tab_products p ON p.id = g.product_id WHERE pv.id = NEW.variant_id;
    END IF;

    IF v_orden_pagada AND v_category_id IS NOT NULL THEN
        BEGIN
            SELECT fun_actualizar_resumen_ventas(v_category_id, NULL, FALSE) INTO v_resultado;
            SELECT fun_actualizar_resumen_categoria(v_category_id, FALSE) INTO v_resultado;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'Error actualizando estadísticas por cambio producto orden: %', SQLERRM;
        END;
    END IF;

    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;


--
-- Name: fun_trigger_actualizar_stock_compra_proveedor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_trigger_actualizar_stock_compra_proveedor() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_variant_id     DECIMAL(10);
    v_stock_anterior INT;
    v_stock_nuevo    INT;
    v_saldo_anterior DECIMAL(14, 2);
    v_saldo_nuevo    DECIMAL(14, 2);
    v_usr            DECIMAL(10);
BEGIN
    IF NEW.ind_estado_producto != 3 OR (OLD.ind_estado_producto IS NOT NULL AND OLD.ind_estado_producto = 3) THEN
        RETURN NEW;
    END IF;

    v_variant_id := NEW.variant_id;
    IF v_variant_id IS NULL THEN
        RAISE NOTICE 'Orden compra %: variant_id NULL, no se actualiza stock. Asigne variant_id.', NEW.id_orden_compra;
        RETURN NEW;
    END IF;

    v_usr := COALESCE(NEW.usr_update, NEW.usr_insert);

    -- Bloqueo de fila (serializa con ventas/compras concurrentes de la variante).
    SELECT stock INTO v_stock_anterior
    FROM tab_product_variant_combinations
    WHERE id = v_variant_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Combinación % no encontrada.', v_variant_id;
    END IF;

    v_stock_nuevo := v_stock_anterior + NEW.cantidad_recibida;

    UPDATE tab_product_variant_combinations
    SET stock = v_stock_nuevo, usr_update = v_usr, fec_update = NOW()
    WHERE id = v_variant_id;

    -- Lote FIFO con el costo de compra.
    INSERT INTO tab_lotes_inventario (
        variant_id, costo_unitario, cantidad_inicial, cantidad_restante, origen, id_orden_compra, fec_entrada, usr_insert
    ) VALUES (
        v_variant_id, NEW.costo_unitario, NEW.cantidad_recibida, NEW.cantidad_recibida,
        'entrada_compra', NEW.id_orden_compra, NOW(), v_usr
    );

    v_saldo_nuevo := fun_saldo_costo_inventario(v_variant_id);
    v_saldo_anterior := v_saldo_nuevo - (NEW.cantidad_recibida * NEW.costo_unitario);

    INSERT INTO tab_movimientos_inventario (
        variant_id, tipo_movimiento, cantidad, costo_unitario_movimiento,
        stock_anterior, stock_actual,
        saldo_costo_total_anterior_mov, saldo_costo_total_actual_mov,
        id_orden_compra, descripcion, observaciones, usr_insert
    ) VALUES (
        v_variant_id, 'entrada_compra', NEW.cantidad_recibida, NEW.costo_unitario,
        v_stock_anterior, v_stock_nuevo,
        v_saldo_anterior, v_saldo_nuevo,
        NEW.id_orden_compra,
        'Entrada por compra a proveedor (FIFO) - Orden compra #' || NEW.id_orden_compra || ' - Variante: ' || v_variant_id,
        'Lote FIFO creado automáticamente por trigger de compras',
        v_usr
    );

    RETURN NEW;
END;
$$;


--
-- Name: fun_trigger_marcar_orden_pagada_auto(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_trigger_marcar_orden_pagada_auto() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_resultado JSON;
    v_orden_record RECORD;
BEGIN
    -- VERIFICAR: Solo procesar cuando el pago cambia a 'approved'
    IF NEW.mp_status = 'approved' AND (OLD.mp_status IS NULL OR OLD.mp_status != 'approved') THEN
        
        -- OBTENER: Información de la orden relacionada
        SELECT id_orden, ind_estado, val_total_pedido 
        INTO v_orden_record
        FROM tab_ordenes 
        WHERE id_orden = NEW.id_orden;
        
            -- VALIDAR: Solo procesar órdenes pendientes o pagadas
    IF v_orden_record.ind_estado IN (1, 2) THEN  -- 1=Pendiente, 2=Pagada
            
            BEGIN
                -- EJECUTAR: Marcar orden como pagada automáticamente
                SELECT fun_marcar_orden_pagada(
                    NEW.id_orden,                                        -- ID de la orden
                    'MERCADOPAGO',                                       -- Método de pago
                    NEW.mp_payment_id::TEXT,                            -- Referencia del pago
                    NEW.mp_transaction_amount,                          -- Monto pagado
                    CONCAT('Pago automático MP - ID: ', NEW.mp_payment_id, 
                        ' - Estado: ', NEW.mp_status),               -- Observaciones
                    COALESCE(NEW.usr_update, NEW.usr_insert)            -- Usuario operación
                ) INTO v_resultado;
                
                -- LOG: Resultado del proceso
                IF (v_resultado->>'success')::BOOLEAN THEN
                    RAISE NOTICE 'Orden % marcada como pagada automáticamente - MP Payment: %', 
                        NEW.id_orden, NEW.mp_payment_id;
                ELSE
                    RAISE WARNING 'Error al marcar orden % como pagada automáticamente: %', 
                        NEW.id_orden, (v_resultado->>'message')::TEXT;
                END IF;
                
            EXCEPTION
                WHEN OTHERS THEN
                    -- Log error pero no fallar la transacción del pago
                    RAISE WARNING 'Excepción al marcar orden % como pagada: % (SQL State: %)', 
                        NEW.id_orden, SQLERRM, SQLSTATE;
            END;
            
        ELSE
            RAISE NOTICE 'Orden % no marcada como pagada - Estado actual: %', 
                NEW.id_orden, v_orden_record.ind_estado;
        END IF;
        
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: fun_trigger_validar_producto_compra_proveedor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_trigger_validar_producto_compra_proveedor() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_ok BOOLEAN := FALSE;
BEGIN
    IF NEW.product_id IS NULL THEN
        RAISE EXCEPTION 'product_id es obligatorio en tab_orden_compra_proveedor.';
    END IF;

    SELECT EXISTS(SELECT 1 FROM tab_products WHERE id = NEW.product_id) INTO v_ok;
    IF NOT v_ok THEN
        RAISE EXCEPTION 'PRODUCTO_NO_EXISTE: El producto id % no existe en tab_products.', NEW.product_id;
    END IF;

    IF NEW.variant_id IS NOT NULL THEN
        SELECT EXISTS(
            SELECT 1
            FROM tab_product_variant_combinations c
            JOIN tab_product_variant_groups g ON g.id = c.group_id
            WHERE c.id = NEW.variant_id AND g.product_id = NEW.product_id
        ) INTO v_ok;
        IF NOT v_ok THEN
            RAISE EXCEPTION 'Variant_id % no pertenece al product_id %.', NEW.variant_id, NEW.product_id;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: fun_update_categoria(numeric, character varying, numeric, boolean, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_update_categoria(p_id numeric, p_name character varying, p_parent_id numeric DEFAULT NULL::numeric, p_is_active boolean DEFAULT NULL::boolean, p_usr_operacion numeric DEFAULT NULL::numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_slug VARCHAR;
BEGIN
    IF p_id IS NULL OR NOT EXISTS (SELECT 1 FROM tab_categories WHERE id = p_id) THEN
        RETURN 'Error: Categoría no encontrada.';
    END IF;
    IF p_name IS NULL OR trim(p_name) = '' OR length(trim(p_name)) < 2 THEN
        RETURN 'Error: El nombre es obligatorio y debe tener al menos 2 caracteres.';
    END IF;
    IF p_parent_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM tab_categories WHERE id = p_parent_id) THEN
        RETURN 'Error: La categoría padre no existe.';
    END IF;
    IF p_parent_id IS NOT NULL AND p_parent_id = p_id THEN
        RETURN 'Error: Una categoría no puede ser padre de sí misma.';
    END IF;

    v_slug := fun_generate_unique_slug(p_name, 'tab_categories', p_id);

    UPDATE tab_categories SET
        name = trim(p_name),
        slug = v_slug,
        parent_id = p_parent_id,
        is_active = COALESCE(p_is_active, is_active),
        usr_update = p_usr_operacion,
        fec_update = CURRENT_TIMESTAMP
    WHERE id = p_id;

    IF FOUND THEN
        RETURN 'Categoría actualizada correctamente';
    ELSE
        RETURN 'Error al actualizar la categoría';
    END IF;
EXCEPTION
    WHEN unique_violation THEN
        RETURN 'Error: Slug duplicado.';
    WHEN OTHERS THEN
        RETURN 'Error: ' || SQLERRM;
END;
$$;


--
-- Name: fun_update_content(character varying, jsonb, integer, boolean, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_update_content(wnom_cms_content character varying, wdes_cms_content jsonb, wnum_version integer, wind_publicado boolean, wusr_operacion numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
    BEGIN
        -- VALIDACIÓN 1: Nombre del contenido
        IF wnom_cms_content IS NULL OR wnom_cms_content = '' THEN
            RETURN 'Error: El nombre del contenido es obligatorio para la actualización.';
        END IF;

        -- VALIDACIÓN 2: Usuario operación para auditoría
        IF wusr_operacion IS NULL OR wusr_operacion = '' THEN
            RETURN 'Error: El usuario que realiza la operación es obligatorio para auditoría.';
        END IF;

        -- ACTUALIZACIÓN: Modificar contenido CMS existente
        UPDATE tab_cms_content SET 
            des_cms_content = wdes_cms_content,     -- Nueva descripción
            num_version = wnum_version,             -- Nuevo número de versión
            ind_publicado = wind_publicado,         -- Nuevo estado de publicación
            usr_update = wusr_operacion,            -- Usuario que actualiza
            fec_update = NOW()                      -- Timestamp de actualización
        WHERE nom_cms_content = wnom_cms_content;
        
        -- VERIFICACIÓN: Confirmar que la actualización fue exitosa
        IF FOUND THEN
            RETURN 'Contenido CMS actualizado correctamente';
        ELSE
            RETURN 'Error: Contenido no encontrado o no se pudo actualizar';
        END IF;

    -- MANEJO DE ERRORES: Capturar excepciones específicas
    EXCEPTION
        WHEN SQLSTATE '23502' THEN
            RETURN 'Error: Faltan campos obligatorios del contenido.';
        WHEN OTHERS THEN
            RETURN 'Error inesperado: ' || SQLERRM;
            ROLLBACK;
    END;
$$;


--
-- Name: fun_update_descuento(numeric, character varying, character varying, boolean, numeric, numeric, character varying, numeric, numeric, numeric, numeric, boolean, date, date, integer, integer, boolean, character varying, integer, character varying, time without time zone, time without time zone, boolean, numeric, integer, boolean, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_update_descuento(p_id_descuento numeric, p_nom_descuento character varying, p_des_descuento character varying, p_tipo_calculo boolean, p_val_porce_descuento numeric, p_val_monto_descuento numeric, p_aplica_a character varying, p_category_id_aplica numeric, p_product_id_aplica numeric, p_id_marca_aplica numeric, p_min_valor_pedido numeric, p_ind_es_para_cumpleanos boolean, p_fec_inicio date, p_fec_fin date, p_max_usos_total integer, p_costo_puntos_canje integer, p_ind_canjeable_puntos boolean, p_codigo_descuento character varying, p_max_usos_por_usuario integer, p_dias_semana_aplica character varying, p_horas_inicio time without time zone, p_horas_fin time without time zone, p_solo_primera_compra boolean, p_monto_minimo_producto numeric, p_cantidad_minima_producto integer, p_requiere_codigo boolean, p_usr_operacion numeric, p_id_usuario_destino numeric DEFAULT NULL::numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_existe BOOLEAN := FALSE;
BEGIN
    SELECT EXISTS(SELECT 1 FROM tab_descuentos WHERE id_descuento = p_id_descuento) INTO v_existe;
    IF NOT v_existe THEN
        RETURN json_build_object('success', false, 'message', 'El descuento especificado no existe');
    END IF;

    IF p_nom_descuento IS NULL OR LENGTH(TRIM(p_nom_descuento)) < 3 THEN
        RETURN json_build_object('success', false, 'message', 'El nombre del descuento debe tener al menos 3 caracteres');
    END IF;
    IF (p_fec_inicio IS NULL AND p_fec_fin IS NOT NULL) OR (p_fec_inicio IS NOT NULL AND p_fec_fin IS NULL) THEN
        RETURN json_build_object('success', false, 'message', 'Debe especificar ambas fechas o ninguna');
    END IF;
    IF p_fec_inicio IS NOT NULL AND p_fec_fin IS NOT NULL AND p_fec_fin < p_fec_inicio THEN
        RETURN json_build_object('success', false, 'message', 'La fecha de fin debe ser mayor o igual a la fecha de inicio');
    END IF;
    IF p_codigo_descuento IS NOT NULL AND EXISTS (SELECT 1 FROM tab_descuentos WHERE codigo_descuento = p_codigo_descuento AND id_descuento != p_id_descuento) THEN
        RETURN json_build_object('success', false, 'message', 'El código de descuento ya existe');
    END IF;
    IF (p_horas_inicio IS NOT NULL AND p_horas_fin IS NULL) OR (p_horas_inicio IS NULL AND p_horas_fin IS NOT NULL) THEN
        RETURN json_build_object('success', false, 'message', 'Si especifica horarios, debe incluir tanto hora de inicio como de fin');
    END IF;

    CASE p_aplica_a
        WHEN 'producto_especifico' THEN
            IF p_product_id_aplica IS NULL THEN
                RETURN json_build_object('success', false, 'message', 'Para descuentos de producto específico se requiere product_id_aplica');
            END IF;
        WHEN 'categoria_especifica' THEN
            IF p_category_id_aplica IS NULL THEN
                RETURN json_build_object('success', false, 'message', 'Para descuentos de categoría específica se requiere category_id_aplica');
            END IF;
        WHEN 'marca_especifica' THEN
            IF p_id_marca_aplica IS NULL THEN
                RETURN json_build_object('success', false, 'message', 'Para descuentos de marca específica se requiere id_marca_aplica');
            END IF;
        WHEN 'linea_especifica', 'sublinea_especifica' THEN
            IF p_category_id_aplica IS NULL THEN
                RETURN json_build_object('success', false, 'message', 'Para linea/sublinea use category_id_aplica (categoría)');
            END IF;
        WHEN 'total_pedido', 'costo_envio', 'envio_gratis', 'segunda_unidad', 'compra_minima' THEN
            NULL;
        ELSE
            RETURN json_build_object('success', false, 'message', 'Tipo de aplicación no válido: ' || p_aplica_a);
    END CASE;

    UPDATE tab_descuentos SET
        nom_descuento = p_nom_descuento,
        des_descuento = p_des_descuento,
        tipo_calculo = p_tipo_calculo,
        val_porce_descuento = p_val_porce_descuento,
        val_monto_descuento = p_val_monto_descuento,
        aplica_a = p_aplica_a,
        category_id_aplica = p_category_id_aplica,
        product_id_aplica = p_product_id_aplica,
        id_marca_aplica = p_id_marca_aplica,
        min_valor_pedido = COALESCE(p_min_valor_pedido, min_valor_pedido),
        ind_es_para_cumpleanos = COALESCE(p_ind_es_para_cumpleanos, ind_es_para_cumpleanos),
        fec_inicio = p_fec_inicio,
        fec_fin = p_fec_fin,
        max_usos_total = p_max_usos_total,
        costo_puntos_canje = p_costo_puntos_canje,
        ind_canjeable_puntos = COALESCE(p_ind_canjeable_puntos, ind_canjeable_puntos),
        codigo_descuento = p_codigo_descuento,
        max_usos_por_usuario = p_max_usos_por_usuario,
        dias_semana_aplica = p_dias_semana_aplica,
        horas_inicio = p_horas_inicio,
        horas_fin = p_horas_fin,
        solo_primera_compra = COALESCE(p_solo_primera_compra, solo_primera_compra),
        monto_minimo_producto = COALESCE(p_monto_minimo_producto, monto_minimo_producto),
        cantidad_minima_producto = COALESCE(p_cantidad_minima_producto, cantidad_minima_producto),
        requiere_codigo = COALESCE(p_requiere_codigo, requiere_codigo),
        id_usuario_destino = p_id_usuario_destino,
        usr_update = p_usr_operacion,
        fec_update = CURRENT_TIMESTAMP
    WHERE id_descuento = p_id_descuento;

    RETURN json_build_object('success', true, 'message', 'Descuento actualizado exitosamente', 'id_descuento', p_id_descuento);
EXCEPTION
    WHEN foreign_key_violation THEN
        RETURN json_build_object('success', false, 'message', 'Error: Referencia a categoría, producto o marca inexistente');
    WHEN check_violation THEN
        RETURN json_build_object('success', false, 'message', 'Error: Valores fuera de rango permitido');
    WHEN OTHERS THEN
        RETURN json_build_object('success', false, 'message', 'Error inesperado: ' || SQLERRM);
END;
$$;


--
-- Name: fun_update_direcciones(numeric, numeric, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, boolean, boolean, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_update_direcciones(wid_direccion numeric, wid_usuario numeric, wnom_direccion character varying, wcalle_direccion character varying, wciudad character varying, wdepartamento character varying, wcodigo_postal character varying, wbarrio character varying, wreferencias character varying, wcomplemento character varying, wind_principal boolean, wind_activa boolean, wusr_operacion numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
    BEGIN
        -- VALIDACIÓN 1: ID de dirección
        IF wid_direccion IS NULL OR wid_direccion = 0 THEN
            RETURN 'Error: El ID de dirección es obligatorio y debe ser mayor a 0.';
        END IF;

        -- VALIDACIÓN 2: ID de usuario
        IF wid_usuario IS NULL OR wid_usuario = 0 THEN
            RETURN 'Error: El ID de usuario es obligatorio y debe ser mayor a 0.';
        END IF;

        -- VALIDACIÓN 3: Nombre de la dirección
        IF wnom_direccion IS NULL OR wnom_direccion = '' OR LENGTH(TRIM(wnom_direccion)) < 3 THEN
            RETURN 'Error: El nombre de la dirección es obligatorio y debe tener al menos 3 caracteres.';
        END IF;

        -- VALIDACIÓN 4: Dirección completa de la calle
        IF wcalle_direccion IS NULL OR wcalle_direccion = '' OR LENGTH(TRIM(wcalle_direccion)) < 5 THEN
            RETURN 'Error: La dirección completa de la calle es obligatoria y debe tener al menos 5 caracteres.';
        END IF;

        -- VALIDACIÓN 5: Ciudad
        IF wciudad IS NULL OR wciudad = '' OR LENGTH(TRIM(wciudad)) < 3 THEN
            RETURN 'Error: La ciudad es obligatoria y debe tener al menos 3 caracteres.';
        END IF;

        -- VALIDACIÓN 6: Departamento/Estado
        IF wdepartamento IS NULL OR wdepartamento = '' OR LENGTH(TRIM(wdepartamento)) < 3 THEN
            RETURN 'Error: El departamento/estado es obligatorio y debe tener al menos 3 caracteres.';
        END IF;

        -- VALIDACIÓN 7: Código postal
        IF wcodigo_postal IS NULL OR wcodigo_postal = '' OR LENGTH(TRIM(wcodigo_postal)) < 3 THEN
            RETURN 'Error: El código postal es obligatorio y debe tener al menos 3 caracteres.';
        END IF;

        -- VALIDACIÓN 8: Barrio/Sector
        IF wbarrio IS NULL OR wbarrio = '' OR LENGTH(TRIM(wbarrio)) < 3 THEN
            RETURN 'Error: El barrio/sector es obligatorio y debe tener al menos 3 caracteres.';
        END IF;

        -- VALIDACIÓN 9: usr_operacion
        IF wusr_operacion IS NULL OR wusr_operacion <= 0 THEN
            RETURN 'Error: El ID del usuario que realiza la operación es obligatorio y debe ser mayor a 0.';
        END IF;

        --ACTUALIZACIÓN: Modificar información de la dirección específica
        UPDATE tab_direcciones_usuario
        SET nombre_direccion = wnom_direccion,
            calle_direccion = wcalle_direccion,
            ciudad = wciudad,
            departamento = wdepartamento,
            codigo_postal = wcodigo_postal,
            barrio = wbarrio,
            referencias = wreferencias,
            complemento = wcomplemento,
            ind_principal = COALESCE(wind_principal, ind_principal),
            ind_activa = COALESCE(wind_activa, ind_activa),
            usr_update = wusr_operacion
        WHERE id_direccion = wid_direccion AND id_usuario = wid_usuario;

        -- VERIFICACIÓN: Confirmar que la actualización fue exitosa
        IF FOUND THEN
            RAISE NOTICE 'Dirección actualizada exitosamente: % por usuario ID: %', wnom_direccion, wusr_operacion;
            RETURN 'Dirección actualizada correctamente';
        ELSE
            RAISE NOTICE 'Error: Dirección no encontrada o no se pudo actualizar';
            RETURN 'Error: Dirección no encontrada o no se pudo actualizar';
        END IF;
        
    -- MANEJO DE ERRORES: Capturar excepciones inesperadas
    EXCEPTION
        WHEN SQLSTATE '23503' THEN
            RETURN 'Error: El usuario especificado no existe o está inactivo.';
        WHEN OTHERS THEN
            RETURN 'Error inesperado: ' || SQLERRM;
            ROLLBACK;
    END;
$$;


--
-- Name: fun_update_marca(numeric, character varying, boolean, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_update_marca(wid_marca numeric, wnom_marca character varying, wind_activo boolean, wusr_operacion numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
    BEGIN
        -- VALIDACIÓN 1: Nombre de la marca
        IF wnom_marca IS NULL OR wnom_marca = '' OR LENGTH(TRIM(wnom_marca)) < 1 THEN
            RETURN 'Error: El nombre de la marca es obligatorio y debe tener al menos 1 carácter.';
        END IF;

        -- VALIDACIÓN 2: ID de usuario operación para auditoría
        IF wusr_operacion IS NULL OR wusr_operacion <= 0 THEN
            RETURN 'Error: El ID del usuario que realiza la operación es obligatorio y debe ser mayor a 0.';
        END IF;

        -- ACTUALIZACIÓN: Modificar información de la marca
        UPDATE tab_marcas SET 
            nom_marca = wnom_marca,                                 -- Nuevo nombre
            ind_activo = COALESCE(wind_activo, ind_activo),         -- Nuevo estado (mantiene actual si NULL)
            usr_update = wusr_operacion,                            -- ID del usuario que actualiza
            fec_update = NOW()                                      -- Timestamp de actualización
        WHERE id_marca = wid_marca;
        
        -- VERIFICACIÓN: Confirmar que la actualización fue exitosa
        IF FOUND THEN
            RAISE NOTICE 'Marca actualizada exitosamente: % por usuario ID: %', wnom_marca, wusr_operacion;
            RETURN 'Marca actualizada correctamente';
        ELSE
            RAISE NOTICE 'Error: Marca no encontrada o no se pudo actualizar';
            RETURN 'Error: Marca no encontrada o no se pudo actualizar';
        END IF;

    -- MANEJO DE ERRORES: Capturar excepciones inesperadas
    EXCEPTION
        WHEN OTHERS THEN
            RETURN 'Error inesperado: ' || SQLERRM;
            ROLLBACK;
    END;
$$;


--
-- Name: fun_update_orden_compra_proveedor(numeric, date, character varying, integer, integer, numeric, numeric, character varying, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_update_orden_compra_proveedor(p_id_orden_compra numeric, p_fec_esperada_entrega date, p_observaciones_orden character varying, p_cantidad_solicitada integer, p_cantidad_recibida integer, p_costo_unitario numeric, p_ind_estado_producto numeric, p_observaciones_producto character varying, p_usr_operacion numeric) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro_actual RECORD;
    v_cambios_realizados JSON := '{}'::JSON;
    v_hay_cambios BOOLEAN := FALSE;
    v_estado_anterior INTEGER;
    v_estado_nuevo INTEGER;
    v_inicio_proceso TIMESTAMP := NOW();
    v_fec_recepcion_completa TIMESTAMP;
BEGIN
    -- VALIDACIÓN 1: Usuario operación obligatorio
    IF p_usr_operacion IS NULL THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El usuario que realiza la operación es obligatorio para auditoría',
            'campo_error', 'usr_operacion'
        );
    END IF;
    
    -- VALIDACIÓN 2: Verificar que el registro existe
    SELECT 
        id_orden_compra, id_proveedor,
        fec_orden_compra, fec_esperada_entrega, observaciones_orden,
        product_id, variant_id,
        cantidad_solicitada, cantidad_recibida, costo_unitario,
        ind_estado_producto, fec_recepcion_completa, observaciones_producto
    INTO v_registro_actual
    FROM tab_orden_compra_proveedor 
    WHERE id_orden_compra = p_id_orden_compra;
    
    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'No se encontró el registro de orden de compra especificado',
            'campo_error', 'id_orden_compra',
            'id_buscado', p_id_orden_compra
        );
    END IF;
    
    -- Guardar estado anterior para comparación
    v_estado_anterior := v_registro_actual.ind_estado_producto;
    v_estado_nuevo := COALESCE(p_ind_estado_producto, v_estado_anterior);
    
    -- VALIDACIONES ESPECÍFICAS
    
    -- Validar fecha esperada de entrega
    IF p_fec_esperada_entrega IS NOT NULL AND p_fec_esperada_entrega < v_registro_actual.fec_orden_compra THEN
        RETURN json_build_object(
            'success', false,
            'message', 'La fecha esperada de entrega no puede ser anterior a la fecha de la orden',
            'campo_error', 'fec_esperada_entrega',
            'fec_orden_compra', v_registro_actual.fec_orden_compra
        );
    END IF;
    
    -- Validar cantidad solicitada
    IF p_cantidad_solicitada IS NOT NULL AND p_cantidad_solicitada <= 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'La cantidad solicitada debe ser mayor a 0',
            'campo_error', 'cantidad_solicitada'
        );
    END IF;
    
    -- Validar cantidad recibida
    IF p_cantidad_recibida IS NOT NULL THEN
        IF p_cantidad_recibida < 0 THEN
            RETURN json_build_object(
                'success', false,
                'message', 'La cantidad recibida no puede ser negativa',
                'campo_error', 'cantidad_recibida'
            );
        END IF;
        
        -- No puede recibir más de lo solicitado
        IF p_cantidad_recibida > COALESCE(p_cantidad_solicitada, v_registro_actual.cantidad_solicitada) THEN
            RETURN json_build_object(
                'success', false,
                'message', 'La cantidad recibida no puede ser mayor a la cantidad solicitada',
                'campo_error', 'cantidad_recibida',
                'cantidad_solicitada', COALESCE(p_cantidad_solicitada, v_registro_actual.cantidad_solicitada)
            );
        END IF;
    END IF;
    
    -- Validar costo unitario
    IF p_costo_unitario IS NOT NULL AND p_costo_unitario <= 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El costo unitario debe ser mayor a 0',
            'campo_error', 'costo_unitario'
        );
    END IF;
    
    -- Validar estado del producto
    IF p_ind_estado_producto IS NOT NULL AND p_ind_estado_producto NOT BETWEEN 1 AND 4 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'El estado del producto debe estar entre 1 (Solicitado) y 4 (Cancelado)',
            'campo_error', 'ind_estado_producto',
            'estados_validos', json_build_object(
                '1', 'Solicitado',
                '2', 'Parcial', 
                '3', 'Recibido',
                '4', 'Cancelado'
            )
        );
    END IF;
    
    -- Determinar fecha de recepción completa
    IF v_estado_nuevo = 3 THEN
        v_fec_recepcion_completa := NOW();
    ELSE
        v_fec_recepcion_completa := NULL;
    END IF;
    
    -- CONSTRUIR JSON DE CAMBIOS
    v_cambios_realizados := json_build_object();
    
    IF p_fec_esperada_entrega IS NOT NULL AND p_fec_esperada_entrega != v_registro_actual.fec_esperada_entrega THEN
        v_cambios_realizados := v_cambios_realizados || json_build_object(
            'fec_esperada_entrega', json_build_object(
                'anterior', v_registro_actual.fec_esperada_entrega,
                'nuevo', p_fec_esperada_entrega
            )
        );
        v_hay_cambios := TRUE;
    END IF;
    
    IF p_cantidad_solicitada IS NOT NULL AND p_cantidad_solicitada != v_registro_actual.cantidad_solicitada THEN
        v_cambios_realizados := v_cambios_realizados || json_build_object(
            'cantidad_solicitada', json_build_object(
                'anterior', v_registro_actual.cantidad_solicitada,
                'nuevo', p_cantidad_solicitada
            )
        );
        v_hay_cambios := TRUE;
    END IF;
    
    IF p_cantidad_recibida IS NOT NULL AND p_cantidad_recibida != v_registro_actual.cantidad_recibida THEN
        v_cambios_realizados := v_cambios_realizados || json_build_object(
            'cantidad_recibida', json_build_object(
                'anterior', v_registro_actual.cantidad_recibida,
                'nuevo', p_cantidad_recibida
            )
        );
        v_hay_cambios := TRUE;
    END IF;
    
    IF p_costo_unitario IS NOT NULL AND p_costo_unitario != v_registro_actual.costo_unitario THEN
        v_cambios_realizados := v_cambios_realizados || json_build_object(
            'costo_unitario', json_build_object(
                'anterior', v_registro_actual.costo_unitario,
                'nuevo', p_costo_unitario
            )
        );
        v_hay_cambios := TRUE;
    END IF;
    
    IF p_ind_estado_producto IS NOT NULL AND p_ind_estado_producto != v_registro_actual.ind_estado_producto THEN
        v_cambios_realizados := v_cambios_realizados || json_build_object(
            'ind_estado_producto', json_build_object(
                'anterior', v_registro_actual.ind_estado_producto,
                'nuevo', p_ind_estado_producto
            )
        );
        v_hay_cambios := TRUE;
    END IF;
    
    -- Verificar si hay cambios
    IF NOT v_hay_cambios AND p_observaciones_orden IS NULL AND p_observaciones_producto IS NULL THEN
        RETURN json_build_object(
            'success', false,
            'message', 'No se especificaron cambios para realizar',
            'registro_actual', json_build_object(
                'id_orden_compra', v_registro_actual.id_orden_compra
            )
        );
    END IF;
    
    -- ACTUALIZACIÓN: Aplicar cambios
    UPDATE tab_orden_compra_proveedor 
    SET 
        fec_esperada_entrega = COALESCE(p_fec_esperada_entrega, fec_esperada_entrega),
        observaciones_orden = COALESCE(p_observaciones_orden, observaciones_orden),
        cantidad_solicitada = COALESCE(p_cantidad_solicitada, cantidad_solicitada),
        cantidad_recibida = COALESCE(p_cantidad_recibida, cantidad_recibida),
        costo_unitario = COALESCE(p_costo_unitario, costo_unitario),
        ind_estado_producto = COALESCE(p_ind_estado_producto, ind_estado_producto),
        fec_recepcion_completa = v_fec_recepcion_completa,
        observaciones_producto = COALESCE(p_observaciones_producto, observaciones_producto),
        usr_update = p_usr_operacion
    WHERE id_orden_compra = p_id_orden_compra;
    
    -- RESULTADO EXITOSO
    RETURN json_build_object(
        'success', true,
        'message', 'Orden de compra a proveedor actualizada exitosamente',
        'id_orden_compra', p_id_orden_compra,
        'cambios_realizados', v_cambios_realizados,
        'estado_anterior', v_estado_anterior,
        'estado_nuevo', v_estado_nuevo,
        'stock_sera_actualizado', (v_estado_anterior != 3 AND v_estado_nuevo = 3),
        'fec_recepcion_completa', v_fec_recepcion_completa,
        'tiempo_procesamiento', (NOW() - v_inicio_proceso),
        'nota_trigger', CASE 
            WHEN v_estado_anterior != 3 AND v_estado_nuevo = 3 
            THEN 'El trigger actualizará automáticamente el stock del producto'
            ELSE 'No se actualizará stock (estado no cambió a Recibido)'
        END
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Error inesperado al actualizar orden de compra: ' || SQLERRM,
            'sql_state', SQLSTATE,
            'tiempo_procesamiento', (NOW() - v_inicio_proceso)
        );
END;
$$;


--
-- Name: fun_update_password_usuario(numeric, character varying, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_update_password_usuario(p_id_usuario numeric, p_nueva_password character varying, p_usr_operacion numeric) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Actualiza la contraseña solo si el usuario existe y está activo
    UPDATE tab_usuarios
    SET password_usuario = p_nueva_password,
        usr_update = p_usr_operacion
    WHERE id_usuario = p_id_usuario;

    -- Verifica si se actualizó alguna fila
    IF FOUND THEN
        RETURN TRUE;
    ELSE
        RETURN FALSE;
    END IF;
END;
$$;


--
-- Name: fun_update_producto(numeric, numeric, character varying, text, numeric, boolean, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_update_producto(p_id numeric, p_category_id numeric DEFAULT NULL::numeric, p_name character varying DEFAULT NULL::character varying, p_description text DEFAULT NULL::text, p_id_marca numeric DEFAULT NULL::numeric, p_is_active boolean DEFAULT NULL::boolean, p_usr_operacion numeric DEFAULT NULL::numeric, p_id_proveedor numeric DEFAULT NULL::numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_slug VARCHAR;
BEGIN
    IF p_id IS NULL OR NOT EXISTS (SELECT 1 FROM tab_products WHERE id = p_id) THEN
        RETURN 'Error: Producto no encontrado.';
    END IF;
    IF p_category_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM tab_categories WHERE id = p_category_id) THEN
        RETURN 'Error: category_id no existe.';
    END IF;
    IF p_id_marca IS NOT NULL AND NOT EXISTS (SELECT 1 FROM tab_marcas WHERE id_marca = p_id_marca) THEN
        RETURN 'Error: id_marca no existe.';
    END IF;
    IF p_id_proveedor IS NOT NULL AND NOT EXISTS (SELECT 1 FROM tab_proveedores WHERE id_proveedor = p_id_proveedor) THEN
        RETURN 'Error: id_proveedor no existe.';
    END IF;
    IF p_name IS NOT NULL AND length(trim(p_name)) < 2 THEN
        RETURN 'Error: Nombre debe tener al menos 2 caracteres.';
    END IF;

    IF p_name IS NOT NULL THEN
        v_slug := fun_generate_unique_slug(trim(p_name), 'tab_products', p_id);
    ELSE
        SELECT slug INTO v_slug FROM tab_products WHERE id = p_id;
    END IF;

    UPDATE tab_products SET
        category_id = COALESCE(p_category_id, category_id),
        name = COALESCE(trim(p_name), name),
        slug = v_slug,
        description = CASE WHEN p_description IS NOT NULL THEN p_description ELSE description END,
        id_marca = CASE WHEN p_id_marca IS NOT NULL THEN p_id_marca ELSE id_marca END,
        is_active = COALESCE(p_is_active, is_active),
        usr_update = p_usr_operacion,
        fec_update = CURRENT_TIMESTAMP,
        id_proveedor = p_id_proveedor
    WHERE id = p_id;

    IF FOUND THEN RETURN 'Producto actualizado correctamente'; ELSE RETURN 'Error al actualizar'; END IF;
EXCEPTION
    WHEN unique_violation THEN RETURN 'Error: Slug duplicado.';
    WHEN OTHERS THEN RETURN 'Error: ' || SQLERRM;
END;
$$;


--
-- Name: fun_update_proveedores(numeric, character varying, character varying, numeric, boolean, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_update_proveedores(wid_proveedor numeric, wnom_proveedor character varying, wemail character varying, wtel_proveedor numeric, wind_activo boolean, wusr_operacion numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
    BEGIN
        -- VALIDACIÓN 1: ID del proveedor
        IF wid_proveedor IS NULL OR wid_proveedor = 0 THEN
            RETURN 'Error: El ID del proveedor es obligatorio y debe ser mayor a 0.';
        END IF;

        -- VALIDACIÓN 2: Nombre del proveedor
        IF wnom_proveedor IS NULL OR wnom_proveedor = '' OR LENGTH(TRIM(wnom_proveedor)) < 3 THEN
            RETURN 'Error: El nombre del proveedor es obligatorio y debe tener al menos 3 caracteres.';
        END IF;

        -- VALIDACIÓN 3: Email del proveedor
        IF wemail IS NULL OR wemail = '' OR LENGTH(TRIM(wemail)) < 3 THEN
            RETURN 'Error: El email del proveedor es obligatorio y debe tener al menos 3 caracteres.';
        END IF;

        -- VALIDACIÓN 4: Teléfono del proveedor
        IF wtel_proveedor IS NULL OR wtel_proveedor = 0 THEN
            RETURN 'Error: El teléfono del proveedor es obligatorio y debe ser mayor a 0.';
        END IF;
        
        -- VALIDACIÓN 5: ID de usuario operación para auditoría
        IF wusr_operacion IS NULL OR wusr_operacion <= 0 THEN
            RETURN 'Error: El ID del usuario que realiza la operación es obligatorio y debe ser mayor a 0.';
        END IF;
        
        -- ACTUALIZACIÓN: Modificar información del proveedor existente
        UPDATE tab_proveedores SET 
            nom_proveedor = wnom_proveedor,                         -- Nuevo nombre
            email = wemail,                                         -- Nuevo email
            tel_proveedor = wtel_proveedor,                         -- Nuevo teléfono
            ind_activo = COALESCE(wind_activo, ind_activo),         -- Nuevo estado (mantiene actual si NULL)
            usr_update = wusr_operacion,                            -- ID del usuario que actualiza
            fec_update = NOW()                                      -- Timestamp de actualización
        WHERE id_proveedor = wid_proveedor;
        
        -- VERIFICACIÓN: Confirmar que la actualización fue exitosa
        IF FOUND THEN
            RAISE NOTICE 'Proveedor actualizado exitosamente: % por usuario ID: %', wnom_proveedor, wusr_operacion;
            RETURN 'Proveedor actualizado correctamente';
        ELSE
            RAISE NOTICE 'Error: Proveedor no encontrado o no se pudo actualizar';
            RETURN 'Error: Proveedor no encontrado o no se pudo actualizar';
        END IF;

    -- MANEJO DE ERRORES: Capturar excepciones inesperadas
    EXCEPTION
        WHEN OTHERS THEN
            RETURN 'Error inesperado: ' || SQLERRM;
            ROLLBACK;
    END;
$$;


--
-- Name: fun_update_roles(numeric, character varying, character varying, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_update_roles(wid_rol numeric, wnom_rol character varying, wdes_rol character varying, wusr_operacion numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
    BEGIN
        -- VALIDACIÓN 1: Nombre del rol
        IF wnom_rol IS NULL OR wnom_rol = '' OR LENGTH(TRIM(wnom_rol)) < 3 THEN
            RETURN 'Error: El nombre del rol es obligatorio y debe tener al menos 3 caracteres.';
        END IF;

        -- VALIDACIÓN 2: Usuario operación para auditoría
        IF wusr_operacion IS NULL OR wusr_operacion = '' THEN
            RETURN 'Error: El usuario que realiza la operación es obligatorio para auditoría.';
        END IF;

        -- ACTUALIZACIÓN: Modificar rol existente
        UPDATE tab_roles SET 
            nom_rol = wnom_rol,             -- Nuevo nombre del rol
            des_rol = wdes_rol,             -- Nueva descripción del rol
            usr_update = wusr_operacion,    -- Usuario que actualiza
            fec_update = NOW()              -- Timestamp de actualización
        WHERE id_rol = wid_rol;

        -- VERIFICACIÓN: Confirmar que la actualización fue exitosa
        IF FOUND THEN
            RAISE NOTICE 'Rol actualizado exitosamente: %', wnom_rol;
            RETURN 'Rol actualizado correctamente';
        ELSE
            RAISE NOTICE 'Error: Rol no encontrado';
            RETURN 'Error: Rol no encontrado o no se pudo actualizar';
        END IF;
    END;
$$;


--
-- Name: fun_update_usuarios(numeric, character varying, character varying, character varying, character varying, boolean, character varying, date, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_update_usuarios(wid_usuario numeric, wnom_usuario character varying, wape_usuario character varying, wemail_usuario character varying, wpassword_usuario character varying, wind_genero boolean, wcel_usuario character varying, wfec_nacimiento date, wusr_operacion numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
    BEGIN
        -- VALIDACIÓN 1: ID del usuario a actualizar
        IF wid_usuario IS NULL OR wid_usuario = 0 THEN
            RETURN 'Error: El ID del usuario es obligatorio y debe ser mayor a 0.';
        END IF;

        -- VALIDACIÓN 2: Nombre del usuario
        IF wnom_usuario IS NULL OR wnom_usuario = '' OR LENGTH(TRIM(wnom_usuario)) < 3 THEN
            RETURN 'Error: El nombre del usuario es obligatorio y debe tener al menos 3 caracteres.';
        END IF;

        -- VALIDACIÓN 3: Apellido del usuario
        IF wape_usuario IS NULL OR wape_usuario = '' OR LENGTH(TRIM(wape_usuario)) < 3 THEN
            RETURN 'Error: El apellido del usuario es obligatorio y debe tener al menos 3 caracteres.';
        END IF;

        -- VALIDACIÓN 4: Email del usuario
        IF wemail_usuario IS NULL OR wemail_usuario = '' OR LENGTH(TRIM(wemail_usuario)) < 3 THEN
            RETURN 'Error: El email del usuario es obligatorio y debe tener al menos 3 caracteres.';
        END IF;

        -- VALIDACIÓN 5: Contraseña del usuario
        IF wpassword_usuario IS NULL OR wpassword_usuario = '' THEN
            RETURN 'Error: La contraseña es obligatoria y no puede estar vacía.';
        END IF;

        -- VALIDACIÓN 8: Indicador de género
        IF wind_genero IS NULL THEN
            RETURN 'Error: El indicador de género es obligatorio.';
        END IF;

        -- VALIDACIÓN 9: Número de celular
        IF wcel_usuario IS NULL OR wcel_usuario = '' OR LENGTH(TRIM(wcel_usuario)) < 3 THEN
            RETURN 'Error: El número de celular es obligatorio y debe tener al menos 3 caracteres.';
        END IF;

        -- wfec_nacimiento es opcional (puede ser NULL)

        -- VALIDACIÓN 10: ID de usuario operación para auditoría
        IF wusr_operacion IS NULL OR wusr_operacion <= 0 THEN
            RETURN 'Error: El ID del usuario que realiza la operación es obligatorio y debe ser mayor a 0.';
        END IF;

        -- ACTUALIZACIÓN: Modificar información del usuario existente
        UPDATE tab_usuarios SET 
            nom_usuario = wnom_usuario,                                     -- Nuevo nombre
            ape_usuario = wape_usuario,                                     -- Nuevo apellido
            email_usuario = wemail_usuario,                                 -- Nuevo email
            password_usuario = wpassword_usuario,                           -- Nueva contraseña
            ind_genero = wind_genero,                                       -- Nuevo género
            cel_usuario = wcel_usuario,                                     -- Nuevo celular
            fec_nacimiento = wfec_nacimiento,                               -- Nueva fecha nacimiento
            usr_update = wusr_operacion,                                    -- ID del usuario que actualiza
            fec_update = NOW()                                              -- Timestamp de actualización
        WHERE id_usuario = wid_usuario;

        -- VERIFICACIÓN: Confirmar que la actualización fue exitosa
        IF FOUND THEN
            RAISE NOTICE 'Usuario actualizado exitosamente: % por usuario ID: %', wnom_usuario, wusr_operacion;
            RETURN 'Usuario actualizado correctamente';
        ELSE
            RAISE NOTICE 'Error: No se encontró el usuario o no se pudo actualizar';
            RETURN 'Error al actualizar el usuario o usuario no encontrado';
        END IF;
    END;
$$;


--
-- Name: fun_upsert_product_embedding(numeric, public.vector, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_upsert_product_embedding(p_product_id numeric, p_embedding public.vector, p_source_text text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO tab_product_embeddings (product_id, embedding, source_text, created_at, updated_at)
  VALUES (p_product_id, p_embedding, p_source_text, NOW(), NOW())
  ON CONFLICT (product_id) DO UPDATE
    SET embedding = EXCLUDED.embedding,
        source_text = EXCLUDED.source_text,
        updated_at = NOW();
END;
$$;


--
-- Name: fun_validar_descuento_aplicable(numeric, numeric, character varying, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fun_validar_descuento_aplicable(p_id_descuento numeric, p_id_usuario numeric, p_codigo_ingresado character varying, p_usr_insert numeric) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Variables para el proceso de validación
    v_descuento RECORD;                     -- Información completa del descuento
    v_usos_usuario INT;                     -- Contador de usos del usuario
    v_dia_actual VARCHAR(1);                -- Día actual de la semana (L,M,X,J,V,S,D)
    v_hora_actual TIME;                     -- Hora actual del sistema
    v_es_primera_compra BOOLEAN;            -- Indicador si es primera compra del usuario
BEGIN
    -- PASO 1: Obtener información completa del descuento
    SELECT * INTO v_descuento FROM tab_descuentos WHERE id_descuento = p_id_descuento;

    -- VALIDACIÓN 1: Verificar existencia del descuento
    IF v_descuento IS NULL THEN
        RETURN FALSE;
    END IF;

    -- VALIDACIÓN 2: Verificar que el descuento esté activo
    IF NOT v_descuento.ind_activo THEN
        RETURN FALSE;
    END IF;

    -- VALIDACIÓN 3: Verificar vigencia de fechas (inicio y fin)
    IF CURRENT_DATE NOT BETWEEN v_descuento.fec_inicio AND v_descuento.fec_fin THEN
        RETURN FALSE;
    END IF;

    -- VALIDACIÓN 4: Verificar código de cupón si es requerido (comparación sin distinguir mayúsculas)
    IF v_descuento.requiere_codigo AND (
        p_codigo_ingresado IS NULL OR TRIM(COALESCE(p_codigo_ingresado, '')) = ''
        OR UPPER(TRIM(p_codigo_ingresado)) != UPPER(TRIM(COALESCE(v_descuento.codigo_descuento, '')))
    ) THEN
        RETURN FALSE;
    END IF;

    -- VALIDACIÓN 4b: Si el cupón es personal (id_usuario_destino), solo ese usuario puede usarlo
    IF v_descuento.id_usuario_destino IS NOT NULL THEN
        IF p_id_usuario IS NULL THEN
            RETURN FALSE;  /* Usuario anónimo no puede usar cupón personal */
        END IF;
        IF p_id_usuario IS DISTINCT FROM v_descuento.id_usuario_destino THEN
            RETURN FALSE;  /* Otro usuario no puede usar este cupón */
        END IF;
    END IF;

    -- VALIDACIÓN 5: Verificar límite de usos totales del descuento
    IF v_descuento.max_usos_total IS NOT NULL AND v_descuento.usos_actuales_total >= v_descuento.max_usos_total THEN
        RETURN FALSE;
    END IF;

    -- VALIDACIÓN 6: Verificar límite de usos por usuario específico
    -- Solo aplica para usuarios registrados
    IF v_descuento.max_usos_por_usuario IS NOT NULL AND p_id_usuario IS NOT NULL THEN
        -- Consultar cuántas veces ha usado este descuento el usuario
        SELECT COALESCE(veces_usado, 0) INTO v_usos_usuario 
        FROM tab_descuentos_usuarios 
        WHERE id_descuento = p_id_descuento AND id_usuario = p_id_usuario;

        -- Verificar si ya alcanzó el límite personal
        IF COALESCE(v_usos_usuario, 0) >= v_descuento.max_usos_por_usuario THEN
            RETURN FALSE;
        END IF;
    END IF;

    -- VALIDACIÓN 7: Verificar restricciones de días de la semana
    IF v_descuento.dias_semana_aplica IS NOT NULL THEN
        -- Convertir día actual a formato de letra (L,M,X,J,V,S,D)
        v_dia_actual := CASE EXTRACT('DOW' FROM CURRENT_DATE)
            WHEN 1 THEN 'L' WHEN 2 THEN 'M' WHEN 3 THEN 'X' 
            WHEN 4 THEN 'J' WHEN 5 THEN 'V' WHEN 6 THEN 'S' WHEN 0 THEN 'D'
        END;

        -- Verificar si el día actual está en la lista de días permitidos
        IF POSITION(v_dia_actual IN v_descuento.dias_semana_aplica) = 0 THEN
            RETURN FALSE;
        END IF;
    END IF;

    -- VALIDACIÓN 8: Verificar restricciones de horarios
    IF v_descuento.horas_inicio IS NOT NULL AND v_descuento.horas_fin IS NOT NULL THEN
        v_hora_actual := CURRENT_TIME;
        -- Verificar si la hora actual está dentro del rango permitido
        IF v_hora_actual NOT BETWEEN v_descuento.horas_inicio AND v_descuento.horas_fin THEN
            RETURN FALSE;
        END IF;
    END IF;

    -- VALIDACIÓN 9: Verificar si es descuento exclusivo para primera compra
    -- Solo aplica para usuarios registrados
    IF v_descuento.solo_primera_compra THEN
        -- Usuarios anónimos no pueden tener "primera compra" (no tienen historial)
        IF p_id_usuario IS NULL THEN
            RETURN FALSE;
        END IF;
        
        -- Verificar si el usuario no tiene órdenes previas
        SELECT NOT EXISTS (
            SELECT 1 FROM tab_ordenes WHERE id_usuario = p_id_usuario
        ) INTO v_es_primera_compra;
        
        -- Si no es primera compra, el descuento no aplica
        IF NOT v_es_primera_compra THEN
            RETURN FALSE;
        END IF;
    END IF;

    -- VALIDACIÓN 10: Verificar si es descuento especial de cumpleaños
    -- Solo aplica para usuarios registrados
    IF v_descuento.ind_es_para_cumpleanos THEN
        -- Usuarios anónimos no tienen fecha de nacimiento
        IF p_id_usuario IS NULL THEN
            RETURN FALSE;
        END IF;
        
        -- Verificar si hoy es el cumpleaños del usuario
        IF NOT EXISTS (
            SELECT 1 FROM tab_usuarios 
            WHERE id_usuario = p_id_usuario 
            AND fec_nacimiento IS NOT NULL
            AND EXTRACT('MONTH' FROM fec_nacimiento) = EXTRACT('MONTH' FROM CURRENT_DATE)
            AND EXTRACT('DAY' FROM fec_nacimiento) = EXTRACT('DAY' FROM CURRENT_DATE)
        ) THEN
            RETURN FALSE;
        END IF;
    END IF;

    -- RESULTADO: Si llegó hasta aquí, el descuento es válido y aplicable
    RETURN TRUE;
END;
$$;


--
-- Name: trg_acumular_puntos_orden(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_acumular_puntos_orden() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- En UPDATE, solo acumular si antes no estaba pagada (evitar doble acumulación)
    IF TG_OP = 'UPDATE' AND OLD.ind_estado = 2 THEN
        RETURN NEW;
    END IF;
    -- INSERT con ind_estado=2 o UPDATE de no-pagada a pagada: acumular puntos
    PERFORM fun_acumular_puntos_compra(
        NEW.id_usuario,                                            -- Usuario de la orden
        NEW.id_orden,                                               -- ID de la orden
        NEW.val_total_productos,                                    -- Valor ANTES de descuentos (para incentivar compras)
        COALESCE(NEW.usr_update, NEW.usr_insert)                    -- Usuario que actualiza/inserta
    );
    
    -- LOG: Registrar acumulación de puntos
    RAISE NOTICE 'Puntos acumulados automáticamente para usuario % en orden %', 
        NEW.id_usuario, NEW.id_orden;
    
    -- RETORNO: Continuar con la operación normal
    RETURN NEW;
END;
$$;


