    usr_insert numeric(10,0) NOT NULL,
    fec_insert timestamp without time zone NOT NULL,
    usr_update numeric(10,0),
    fec_update timestamp without time zone,
    CONSTRAINT chk_subtotal_orden_producto CHECK ((subtotal = ((cant_producto)::numeric * precio_unitario_orden))),
    CONSTRAINT tab_orden_productos_cant_producto_check CHECK ((cant_producto > 0)),
    CONSTRAINT tab_orden_productos_precio_unitario_orden_check CHECK ((precio_unitario_orden >= (0)::numeric)),
    CONSTRAINT tab_orden_productos_subtotal_check CHECK ((subtotal >= (0)::numeric))
);


