    val_base_gravable numeric(10,0),
    val_total_iva numeric(10,0),
    val_total_excluido numeric(10,0),
    CONSTRAINT chk_totales_orden CHECK ((val_total_pedido = ((val_total_productos - val_total_descuentos) + val_costo_envio))),
    CONSTRAINT tab_ordenes_ind_estado_check CHECK (((ind_estado >= (1)::numeric) AND (ind_estado <= (3)::numeric))),
    CONSTRAINT tab_ordenes_metodo_pago_check CHECK (((metodo_pago)::text = ANY ((ARRAY['tarjeta'::character varying, 'efectivo_red_pagos'::character varying, 'transferencia'::character varying])::text[]))),
    CONSTRAINT tab_ordenes_val_base_gravable_check CHECK ((val_base_gravable >= (0)::numeric)),
    CONSTRAINT tab_ordenes_val_total_descuentos_check CHECK ((val_total_descuentos >= (0)::numeric)),
    CONSTRAINT tab_ordenes_val_total_excluido_check CHECK ((val_total_excluido >= (0)::numeric)),
    CONSTRAINT tab_ordenes_val_total_iva_check CHECK ((val_total_iva >= (0)::numeric)),
    CONSTRAINT tab_ordenes_val_total_pedido_check CHECK ((val_total_pedido >= (0)::numeric)),
    CONSTRAINT tab_ordenes_val_total_productos_check CHECK ((val_total_productos >= (0)::numeric))
);


