--
-- Name: vw_descuentos_canjeables; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_descuentos_canjeables AS
 SELECT id_descuento,
    nom_descuento,
    des_descuento,
    costo_puntos_canje,
        CASE
            WHEN tipo_calculo THEN concat((val_porce_descuento)::text, '%')
            ELSE concat('$', (val_monto_descuento)::text)
        END AS valor_descuento,
    aplica_a,
    fec_inicio,
    fec_fin,
    ind_activo,
        CASE
            WHEN ((fec_inicio IS NULL) AND (fec_fin IS NULL)) THEN 'Vigente'::text
            WHEN ((CURRENT_DATE >= fec_inicio) AND (CURRENT_DATE <= fec_fin)) THEN 'Vigente'::text
            WHEN ((fec_inicio IS NOT NULL) AND (CURRENT_DATE < fec_inicio)) THEN 'Programado'::text
            ELSE 'Vencido'::text
        END AS estado_vigencia
   FROM public.tab_descuentos d
  WHERE (ind_canjeable_puntos = true);


--
-- Name: vw_kpis_disponibles; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_kpis_disponibles AS
 SELECT k.id_kpi,
    k.nom_kpi,
    k.descripcion_kpi,
    k.unidad_medida,
    k.formato_numero,
    k.tipo_grafico_sugerido,
    k.color_primario,
    k.mostrar_tendencia,
    k.mostrar_comparacion,
    k.solo_administradores,
    k.requiere_parametros,
    k.parametros_permitidos,
    k.frecuencia_actualizacion,
    k.duracion_cache_minutos,
    k.rango_esperado_min,
    k.rango_esperado_max,
    t.nom_tipo_kpi,
    t.descripcion AS descripcion_tipo,
    t.color_categoria,
    t.icono,
    t.orden_visualizacion,
    COALESCE(uso.widgets_activos, (0)::bigint) AS widgets_activos,
    COALESCE(uso.dashboards_usando, (0)::bigint) AS dashboards_usando,
    k.ultima_actualizacion,
    u.nom_usuario AS creado_por_usuario,
    k.fec_creacion,
    k.fec_update
   FROM (((public.tab_kpis_maestros k
     JOIN public.tab_tipos_kpi t ON ((k.id_tipo_kpi = t.id_tipo_kpi)))
     LEFT JOIN public.tab_usuarios u ON ((k.creado_por = u.id_usuario)))
     LEFT JOIN ( SELECT w.id_kpi,
            count(*) AS widgets_activos,
            count(DISTINCT w.id_dashboard) AS dashboards_usando
           FROM (public.tab_widgets_dashboard w
             JOIN public.tab_dashboards_usuarios d ON ((w.id_dashboard = d.id_dashboard)))
          WHERE ((w.ind_activo = true) AND (d.ind_activo = true))
          GROUP BY w.id_kpi) uso ON ((k.id_kpi = uso.id_kpi)))
  WHERE ((k.ind_activo = true) AND (t.ind_activo = true))
  ORDER BY t.orden_visualizacion, k.nom_kpi;


--
-- Name: vw_resumen_puntos_usuario; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_resumen_puntos_usuario AS
 SELECT u.id_usuario,
    u.nom_usuario,
    u.ape_usuario,
    u.email_usuario,
    COALESCE(pu.puntos_disponibles, 0) AS puntos_disponibles,
    COALESCE(pu.puntos_totales_ganados, 0) AS puntos_totales_ganados,
    COALESCE(pu.puntos_totales_canjeados, 0) AS puntos_totales_canjeados,
    ( SELECT max(mp.fec_insert) AS max
           FROM public.tab_movimientos_puntos mp
          WHERE ((mp.id_usuario = u.id_usuario) AND (mp.tipo_movimiento = (1)::numeric))) AS fec_ultima_acumulacion,
    pu.fec_ultimo_canje,
    count(cpd.id_canje) AS canjes_disponibles
   FROM ((public.tab_usuarios u
     LEFT JOIN public.tab_puntos_usuario pu ON ((u.id_usuario = pu.id_usuario)))
     LEFT JOIN public.tab_canjes_puntos_descuentos cpd ON (((u.id_usuario = cpd.id_usuario) AND (cpd.ind_utilizado = false) AND ((cpd.fec_expiracion_canje IS NULL) OR (cpd.fec_expiracion_canje >= CURRENT_DATE)))))
  WHERE (u.id_rol = (2)::numeric)
  GROUP BY u.id_usuario, u.nom_usuario, u.ape_usuario, u.email_usuario, pu.puntos_disponibles, pu.puntos_totales_ganados, pu.puntos_totales_canjeados, pu.fec_ultimo_canje;


--
-- Name: vw_resumen_ventas_categoria; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_resumen_ventas_categoria AS
 SELECT category_id,
    nom_categoria,
    categoria_activa,
    total_productos,
    productos_activos,
    productos_con_ventas,
    total_ordenes,
    total_unidades_vendidas,
    total_ingresos,
    ventas_mes_actual,
    ingresos_mes_actual,
    ventas_mes_anterior,
    ingresos_mes_anterior,
    participacion_ventas,
    crecimiento_mensual,
    precio_promedio_categoria,
    producto_mas_vendido,
    producto_mayor_ingreso,
    unidades_top_producto,
    fecha_primera_venta,
    fecha_ultima_venta,
    mejor_mes_ventas,
    ultima_actualizacion,
    periodo_calculo,
    rank() OVER (ORDER BY total_ingresos DESC) AS ranking_ingresos,
    rank() OVER (ORDER BY total_unidades_vendidas DESC) AS ranking_unidades,
        CASE
            WHEN (crecimiento_mensual > (10)::numeric) THEN 'Alto Crecimiento'::text
            WHEN (crecimiento_mensual > (0)::numeric) THEN 'Crecimiento Moderado'::text
            WHEN (crecimiento_mensual = (0)::numeric) THEN 'Estable'::text
            ELSE 'Decrecimiento'::text
        END AS tendencia_categoria
   FROM public.tab_estadisticas_categorias ec
  WHERE (categoria_activa = true);


